MREST=MREST.concat([{"id":6268,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70117.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":5,"es":"En esta situación debo:"},{"id":6270,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70250.png","v":null,"a":[{"t":"автомобилът, който завива надясно","ok":true,"i":null,"es":"el que gira a la DERECHA"},{"t":"автомобилът, който завива наляво","ok":false,"i":null,"es":"el que gira a la IZQUIERDA"}],"f":5,"es":"En esta situación tiene prioridad:"},{"id":6271,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67263.png","v":null,"a":[{"t":"водачът на зеления автомобил е задължен да пропусне червения автомобил","ok":false,"i":null,"es":"el conductor del coche verde está obligado a ceder al rojo"},{"t":"водачът на червения автомобил е задължен да пропусне зеления автомобил","ok":true,"i":null,"es":"el conductor del coche rojo está obligado a ceder al verde"}],"f":5,"es":"En esta situación:"},{"id":6277,"bg":"При тази ситуация синият автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70349.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":5,"es":"En esta situación el coche azul tiene prioridad. Esto es:"},{"id":6292,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70515.png","v":null,"a":[{"t":"червеният автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"синият автомобил","ok":false,"i":null,"es":"el coche azul"}],"f":5,"es":"En esta situación tiene prioridad:"},{"id":6336,"bg":"При тази ситуация с предимство ли сте пред трамвая, който завива?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70779.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":5,"es":"En esta situación, ¿tiene usted prioridad sobre el tranvía que gira?"},{"id":6356,"bg":"При завиване наляво за навлизане в друг път водачът на завиващото релсово ППС е длъжен да пропусне насрещно движещите се:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трамваи","ok":true,"i":null,"es":"tranvías"},{"t":"тролейбуси","ok":false,"i":null,"es":"trolebuses"},{"t":"леки автомобили","ok":false,"i":null,"es":"turismos"},{"t":"мотоциклети","ok":false,"i":null,"es":"motocicletas"}],"f":5,"es":"Al girar a la izquierda para entrar en otro camino, el tranvía que gira a la izquierda debe ceder el paso a:","explain":"El tranvía que gira a la izquierda cede el paso a los otros TRANVÍAS. Frente a trolebuses, turismos y motocicletas el tranvía tiene prioridad como vehículo ferroviario."},{"id":6382,"bg":"Когато, при голям надлъжен наклон, за разминаване на товарен автомобил с автобус е необходимо движение назад, то се извършва от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"товарния автомобил","ok":true,"i":null,"es":"el camión"},{"t":"ППС, което се изкачва по наклона","ok":false,"i":null,"es":"el vehículo que sube"},{"t":"ППС, което се спуска по наклона","ok":false,"i":null,"es":"el vehículo que baja"},{"t":"автобуса","ok":false,"i":null,"es":"el autobús"}],"f":5,"es":"En pendiente con camión y autobús que necesitan que uno retroceda, ¿quién retrocede?","explain":"Entre un camión y un autobús, retrocede el CAMIÓN: el autobús transporta pasajeros y la marcha atrás con ellos es más peligrosa. La regla sube/baja se aplica entre vehículos de la misma categoría."},{"id":6388,"bg":"При тази ситуация водачът на синия автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/72053.png","v":null,"a":[{"t":"трябва да пропусне автомобила, който вече е навлязъл в стеснения участък","ok":true,"i":null,"es":"debe dejar pasar al vehículo que ya entró en el tramo estrecho"},{"t":"е с предимство и трябва да продължи движението си","ok":false,"i":null,"es":"tiene prioridad y debe continuar"}],"f":5,"es":"En esta situación el conductor del coche azul:"},{"id":6394,"bg":"Как трябва да постъпите когато автомобилът който ви изпреварва се прибере в лентата, по която се движите, без да осигури необходимата дистанция?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да премина в лявата лента","ok":false,"i":null,"es":"debo pasar al carril izquierdo"},{"t":"трябва да продължа движението си със същата скорост","ok":false,"i":null,"es":"debo continuar igual"},{"t":"трябва да подам светлинен сигнал","ok":false,"i":null,"es":"debo señalizar con luces"}],"f":5,"es":"¿Cómo actúas cuando el vehículo que te adelantó vuelve a su carril delante de ti?","explain":"Reduce la velocidad: cuando el que te adelantó se reincorpora delante de ti, la distancia de seguridad ha desaparecido y debes restablecerla. Cambiar de carril o dar luces no resuelve el problema."},{"id":6398,"bg":"Кое от изброените ППС е забранено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"трактор","ok":true,"i":null,"es":"tractor"},{"t":"товарен автомобил","ok":true,"i":null,"es":"camión"},{"t":"мотопед","ok":false,"i":null,"es":"ciclomotor"},{"t":"велосипед","ok":false,"i":null,"es":"bicicleta"}],"f":5,"es":"¿Qué vehículo está PROHIBIDO adelantar después de esta señal? (2 correctas)"},{"id":6414,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при ограничена видимост, когато разстоянието е по-малко от необходимото за изпреварване","ok":true,"i":null,"es":"con visibilidad limitada y distancia insuficiente para adelantar"},{"t":"пред и върху сигнализирана пешеходна пътека","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"на път с еднопосочно движение","ok":false,"i":null,"es":"en vía de sentido único"},{"t":"на мост","ok":false,"i":null,"es":"en puente"}],"f":5,"es":"El adelantamiento está PROHIBIDO: (2 correctas)","explain":"Prohibido adelantar cuando la visibilidad es limitada (curva, rasante) o insuficiente para completar la maniobra. En vía de sentido único y en puente el adelantamiento no está prohibido por sí mismo."},{"id":6419,"bg":"При тази ситуация изпреварването е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71852.png","v":null,"a":[{"t":"забранено, защото видимостта е ограничена","ok":true,"i":null,"es":"prohibido, porque la visibilidad es limitada"},{"t":"забранено, защото пътят е неравен","ok":false,"i":null,"es":"prohibido, porque el camino es irregular"},{"t":"забранено, защото пътят е с голям наклон","ok":false,"i":null,"es":"prohibido, porque hay gran pendiente"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":5,"es":"En esta situación el adelantamiento está:"},{"id":6429,"bg":"Водач, който ще предприеме изпреварване, преди да подаде сигнал е длъжен да се убеди, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не го изпреварва друго пътно превозно средство","ok":true,"i":null,"es":"nadie le está adelantando a él"},{"t":"движещото се след него ППС не е подало сигнал за изменение на посоката си на движение наляво","ok":true,"i":null,"es":"el de detrás no señalizó un cambio de dirección"},{"t":"ППС, което ще изпреварва, не е подало сигнал за изменение на посоката си на движение наляво","ok":true,"i":null,"es":"el vehículo a adelantar no señalizó un cambio"},{"t":"че водачите от насрещното движение ще спрат за да го пропуснат","ok":false,"i":null,"es":"los del tráfico contrario van a parar para dejarle"}],"f":5,"es":"Antes de señalizar para adelantar, el conductor debe asegurarse de que: (3 correctas)","explain":"ANTES de señalizar el adelantamiento comprueba tres cosas: que nadie te está adelantando a ti, que el de detrás no ha señalizado ya, y que el de delante tampoco. Nunca cuentes con que el tráfico contrario 'parará para dejarte'."},{"id":6430,"bg":"Водач, който ще предприеме изпреварване, след като подаде сигнал е длъжен да се убеди, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"има видимост на достатъчно разстояние","ok":true,"i":null,"es":"hay visibilidad suficiente"},{"t":"има свободен път на разстояние, достатъчно за изпреварване","ok":true,"i":null,"es":"hay vía libre a distancia suficiente para adelantar"},{"t":"няма да принуждава изпреварваното ППС да намалява скоростта или да изменя посоката на движение","ok":true,"i":null,"es":"no obliga al vehículo adelantado a reducir velocidad ni cambiar de trayectoria"},{"t":"че водачът на изпреварвания автомобил е започнал да намалява скоростта на движение","ok":false,"i":null,"es":"el adelantado ya ha empezado a reducir velocidad"}],"f":5,"es":"Después de señalizar para adelantar, el conductor debe asegurarse de que: (3 correctas)","explain":"DESPUÉS de señalizar, asegúrate de que hay visibilidad suficiente, de que el tramo libre alcanza para toda la maniobra y de que no obligarás al adelantado a frenar o desviarse. Él no tiene obligación de reducir."},{"id":6442,"bg":"Длъжни ли сте при тази ситуация да сигнализирате с ляв пътепоказател, че започвате изпреварването?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124581.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Está obligado a señalizar con el intermitente izquierdo al iniciar el adelantamiento?"},{"id":6601,"bg":"При тази ситуация водачът на синия автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124334.png","v":null,"a":[{"t":"трябва да прекрати изпреварването","ok":true,"i":null,"es":"debe abandonar el adelantamiento"},{"t":"може да продължи изпреварването, като премине по трамвайната линия","ok":false,"i":null,"es":"puede continuar por las vías del tranvía"}],"f":5,"es":"En esta situación el conductor del coche azul:"},{"id":6701,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70051.png","v":null,"a":[{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":true,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación debo ceder el paso al peatón. Esto es:"},{"id":12005,"bg":"На кои участници в движението трябва да осигурите предимство преди да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":24,"a":[{"t":"на велосипедиста","ok":true,"i":null,"es":"al ciclista"},{"t":"на водача на черния автомобил","ok":false,"i":null,"es":"al conductor del coche negro"},{"t":"на пешеходеца","ok":true,"i":null,"es":"al peatón"}],"f":5,"es":"¿A qué participantes debes ceder el paso antes de girar a la derecha? (2 correctas)"},{"id":12048,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":40,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да включа аварийните светлини","ok":true,"i":null,"es":"debo activar las luces de emergencia"},{"t":"продължавам движението си в свободната лента","ok":false,"i":null,"es":"continúo por el carril libre"}],"f":5,"es":"¿Qué debes hacer en esta situación? (2 correctas)"},{"id":12052,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":44,"a":[{"t":"продължавам движението си, без да променям скоростта","ok":false,"i":null,"es":"continúo sin cambiar velocidad"},{"t":"преминавам в дясната лента","ok":false,"i":null,"es":"paso al carril derecho"},{"t":"намалявам скоростта си","ok":true,"i":null,"es":"reduzco la velocidad"}],"f":5,"es":"¿Cuál es la actuación correcta en esta situación?"},{"id":6459,"bg":"При несъответствие между предписанията на пътните знаци и маркировката на пътя водачите са длъжни да се съобразяват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51535.png","v":null,"a":[{"t":"с предписанията на пътните знаци","ok":true,"i":null,"es":"las señales de tráfico"},{"t":"с маркировката на пътя","ok":false,"i":null,"es":"las marcas en la calzada"}],"f":5,"es":"Cuando hay conflicto entre señales de tráfico y marcas en la calzada, los conductores deben atenerse a:"},{"id":6471,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на червения автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53542.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"ускорявам, защото съм с предимство","ok":false,"i":null,"es":"acelero porque tengo prioridad"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"f":5,"es":"¿Cómo debes actuar en esta situación si el conductor del coche rojo, que debe cederte el paso, no muestra con sus acciones que vaya a parar? (2 correctas)"},{"id":6511,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61772.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"dejar pasar al tranvía"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"dejar pasar al turismo"}],"f":5,"es":"En esta situación debo: (2 correctas)"},{"id":6512,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62113.png","v":null,"a":[{"t":"само трамвая","ok":true,"i":null,"es":"solo al tranvía"},{"t":"само автомобила","ok":false,"i":null,"es":"solo al coche"},{"t":"двете превозни средства","ok":false,"i":null,"es":"a los dos vehículos"}],"f":5,"es":"En esta situación debo ceder el paso:"},{"id":6514,"bg":"При тази ситуация трябва да пропусна червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64738.png","v":null,"a":[{"t":"се намира на пътя с предимство","ok":true,"i":null,"es":"está en la vía preferente"},{"t":"се движи направо","ok":false,"i":null,"es":"va recto"},{"t":"завивам наляво","ok":false,"i":null,"es":"yo giro a la izquierda"}],"f":5,"es":"En esta situación debo ceder el paso al rojo porque:"},{"id":6515,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61654.png","v":null,"a":[{"t":"да пропусна лекия автомобил","ok":true,"i":null,"es":"dejar pasar al turismo"},{"t":"да пропусна трамвая","ok":true,"i":null,"es":"dejar pasar al tranvía"},{"t":"да премина преди лекия автомобил","ok":false,"i":null,"es":"pasar antes que el turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"f":5,"es":"En esta situación debo: (2 correctas)"},{"id":6528,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57534.png","v":null,"a":[{"t":"да пропусна автомобила","ok":true,"i":null,"es":"ceder el paso al coche"},{"t":"да пропусна мотоциклетиста","ok":true,"i":null,"es":"dejar pasar al motorista"},{"t":"да премина преди мотоциклетиста","ok":false,"i":null,"es":"pasar antes que el motorista"},{"t":"да премина преди автомобила","ok":false,"i":null,"es":"pasar antes que el coche"}],"f":5,"explain":"Esta situación combina dos tipos de vehículo: un coche y un motociclista. La regla de prioridad NO distingue por tipo de vehículo (un motociclista tiene exactamente los mismos derechos de paso que un coche) — lo que importa es la posición relativa: ¿quién está a tu derecha?, ¿quién tiene la vía con continuidad? Si la situación indica que debes ceder el paso a ambos, es porque ambos están en la posición de prioridad respecto a ti (por ejemplo, ambos vienen por tu derecha desde direcciones distintas, o ambos circulan por una vía con prioridad sobre la tuya). No asumas que un motociclista 'cuenta menos' que un coche en las normas de prioridad — es un error común que cuesta puntos.","es":"En esta situación debo: (2 correctas)"},{"id":6547,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65840.png","v":null,"a":[{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червения автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"жълтия автомобил","ok":false,"i":null,"es":"el coche amarillo"}],"f":5,"es":"En esta situación debo ceder el paso a: (2 correctas)"},{"id":6549,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65617.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"}],"f":5,"explain":"Aquí la respuesta es mixta: pasas antes que el rojo, pero cedes al azul. Esto te indica que cada vehículo está en una posición distinta respecto a ti — el rojo probablemente viene desde tu izquierda o desde una vía sin prioridad, mientras que el azul está a tu derecha o en una vía con prioridad sobre la tuya. Esta es la clave de las preguntas de intersección con 3 vehículos: no asumas que la respuesta es igual para ambos coches — analiza la posición de cada uno por separado aplicando la regla del vehículo a la derecha y la de quién circula recto vs quién gira.","es":"En esta situación debo: (2 correctas)"},{"id":6570,"bg":"При тази ситуация синият автомобил, е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67411.png","v":null,"a":[{"t":"без предимство","ok":true,"i":null,"es":"no tiene prioridad"},{"t":"с предимство","ok":false,"i":null,"es":"tiene prioridad"}],"f":5,"es":"En esta situación el coche azul:"},{"id":6578,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67674.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación el coche rojo tiene prioridad. Esto es:"},{"id":6592,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56596.png","v":null,"a":[{"t":"е разрешено да премина, без да спирам, но трябва да пропусна ППС от другия път","ok":true,"i":null,"es":"está permitido pasar sin parar pero cediendo al tráfico del otro camino"},{"t":"задължен съм да спра, преди да премина през кръстовището","ok":false,"i":null,"es":"estoy obligado a parar antes de cruzar"},{"t":"мога да премина без да спирам, защото пътят, по който се движа, е с предимство","ok":false,"i":null,"es":"puedo pasar sin parar porque estoy en vía preferente"}],"f":5,"es":"En esta situación:"},{"id":6596,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56768.png","v":null,"a":[{"t":"е разрешено да премина, без да спирам","ok":true,"i":null,"es":"puedo pasar sin parar"},{"t":"пътят, по който се движа, е с предимство","ok":true,"i":null,"es":"estoy en vía preferente"},{"t":"ППС от другия път трябва да ме пропуснат","ok":true,"i":null,"es":"los del otro camino deben cederme el paso"},{"t":"задължен съм да спра, преди да премина през кръстовището","ok":false,"i":null,"es":"estoy obligado a parar antes de cruzar"}],"f":5,"es":"En esta situación: (3 correctas)"},{"id":6716,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на червения автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51552.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"f":5,"es":"¿Cómo debes actuar en esta situación si el conductor del coche rojo, que debe cederte el paso, no muestra con sus acciones que vaya a parar? (2 correctas)"},{"id":7964,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917931.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":5,"explain":"CORRECTO: el coche rojo sí tiene prioridad.\n\nLEE LA TABLA. El trazo GRUESO entra por abajo — tu aproximación — y tuerce a la DERECHA, hacia donde está el rojo. Los trazos finos son el de arriba y el de la izquierda.\n\nLOS DOS ESTÁIS EN LA PREFERENTE, así que el rombo no reparte nada entre vosotros. Y como la vía cambia de dirección, el чл. 50, ал. 2 devuelve el mando a la regla de la derecha: el rojo está a tu derecha y pasa primero.\n\nEL ERROR NATURAL ES PENSAR «SI YO ESTOY EN LA PREFERENTE, PASO YO». La preferente te protege de los que llegan por los ramales finos, no de otro vehículo que también circula por ella.\n\nES LA MISMA CONFIGURACIÓN que 7962 y 7963, con el camión sustituido por un turismo y preguntada en formato de verdadero o falso. Tres preguntas, una sola lectura de tabla.\n\nCLAVE: cuando la tabla muestra que la preferente tuerce, deja de mirar el rombo y mira quién está a la derecha de quién.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","es":"En esta situación el coche rojo tiene prioridad. Esto es:"},{"id":7966,"bg":"При тази ситуация преминавам преди синия автомобил защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917998.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación paso antes que el azul porque voy recto. Esto es:"},{"id":11484,"bg":"При тази ситуация при определяне на реда за преминаване през кръстовището се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/578632772.png","v":null,"a":[{"t":"през кръстовището преминават ППС, които имат разрешаващ сигнал от светофара","ok":true,"i":null,"es":"por la intersección pasan los vehículos que tienen señal permisiva del semáforo"},{"t":"ППС завиващо наляво пропуска насрещнодвижещото се","ok":true,"i":null,"es":"el vehículo que gira a la izquierda cede el paso al que viene de frente"},{"t":"ППС на пътя с предимство, трябва да премине преди ППС от другия път","ok":false,"i":null,"es":"los de vía preferente pasan antes que los del otro camino"},{"t":"ППС преминаващи при разрешаващ сигнал, прилагат правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"los vehículos que pasan con señal permisiva aplican la regla de prioridad a la derecha"}],"f":5,"explain":"Dos reglas: pasan los vehículos con señal permisiva del semáforo, y el que gira a la izquierda cede al que viene de frente.\n\nQUÉ VES. Un cruce con semáforo funcionando, un STOP en el lateral, tu coche girando a la izquierda y otro viniendo de frente.\n\nPRIMERA REGLA: con el semáforo en funcionamiento, él ordena el cruce. Pasan los que tienen luz permisiva.\n\nSEGUNDA REGLA: el verde no resuelve el conflicto entre el que gira a la izquierda y el que viene de frente, porque los dos lo tienen a la vez. Ahí sigue el чл. 37.\n\n«LOS DE LA VÍA PREFERENTE PASAN ANTES» es falsa aquí: el semáforo desplaza a las señales de prioridad, incluido el STOP que ves en el poste. Mientras las luces funcionen, esa señal no reparte nada.\n\n«ENTRE LOS QUE TIENEN VERDE, LA REGLA DE LA DERECHA» también es falsa: la derecha es el escalón más bajo y el semáforo lo desactiva.\n\nCLAVE: el semáforo apaga dos cosas — las señales de prioridad y la regla de la derecha — pero NO apaga el чл. 37. Es la lección de la 5935 con más distractores, y merece la pena verlas juntas.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)"},{"id":11618,"bg":"При тази ситуация посоката, в която на червения автомобил е разрешено да премине, се определя от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123584872.png","v":null,"a":[{"t":"пътната маркировка","ok":false,"i":null,"es":"las marcas viales"},{"t":"пътния знак","ok":true,"i":null,"es":"la señal de tráfico"},{"t":"светлинния сигнал","ok":false,"i":null,"es":"la señal luminosa"}],"f":5,"es":"En esta situación la dirección en que el rojo puede continuar la determina:"},{"id":8264,"bg":"Автомагистралата е път:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"който не обслужва пряко прилежащи територии","ok":true,"i":null,"es":"que no da servicio directo a los terrenos colindantes"},{"t":"с две самостоятелни еднопосочни платна за движение","ok":true,"i":null,"es":"con dos calzadas independientes de sentido único"},{"t":"който не се пресича с други пътища на едно ниво","ok":true,"i":null,"es":"que no se cruza a nivel con otras vías"},{"t":"по който e разрешено движението само на автомобили","ok":false,"i":null,"es":"en la que solo se permite la circulación de automóviles"}],"f":5,"es":"La autopista es una carretera: (3 correctas)","explain":"La autopista: no da servicio directo a los terrenos colindantes (sin accesos a fincas), tiene dos calzadas independientes de sentido único y no se cruza a nivel con nada. La falsa: no es 'solo para automóviles' — motocicletas y otros vehículos rápidos también circulan."},{"id":11727,"bg":"При теглене с твърда връзка по автомагистрала разрешената максимална скорост за движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"70 km/h","ok":true,"i":null,"es":"70 km/h"},{"t":"30 km/h","ok":false,"i":null,"es":"30 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"}],"f":5,"es":"Al remolcar con barra rigida en autopista la velocidad máxima permitida es:","explain":"70 km/h: máximo remolcando con barra rígida también en autopista. El límite del remolcado no sube por estar en autopista: el conjunto sigue siendo igual de inestable."},{"id":5553,"bg":"С този знак се обозначава:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38820.png","v":null,"a":[{"t":"тролейбусна спирка","ok":true,"i":null,"es":"parada de trolebús"},{"t":"пресичане на път, по който се движат тролейбуси","ok":false,"i":null,"es":"cruce con una vía por la que circulan trolebuses"},{"t":"лента за движение само на тролейбуси","ok":false,"i":null,"es":"carril reservado a trolebuses"},{"t":"пътна лента, забранена за движение на тролейбуси","ok":false,"i":null,"es":"carril prohibido para trolebuses"}],"f":5,"es":"Con esta señal se indica:","explain":""},{"id":5583,"bg":"При тази ситуация, преминавайки покрай спрелия на спирката тролейбус:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39054.png","v":null,"a":[{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"трябва да внимавам за пешеходци, преминаващи пред тролейбуса","ok":true,"i":null,"es":"debo estar atento a los peatones que cruzan por delante del trolebús"},{"t":"трябва да внимавам за пешеходци, преминаващи зад тролейбуса","ok":true,"i":null,"es":"debo estar atento a los peatones que cruzan por detrás del trolebús"},{"t":"няма опасност от пресичащи пешеходци, защото няма пешеходна пътека","ok":false,"i":null,"es":"no hay peligro de peatones cruzando, porque no hay paso de peatones"}],"f":5,"es":"En esta situación, al pasar junto al trolebús parado en la parada: (3 correctas)","explain":""},{"id":5584,"bg":"Навлизането на пешеходци на платното за движение, непосредствено пред спрелия автобус, е забранено и затова при тази ситуация не съм задължен да намаля скоростта.","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39087.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"La entrada de peatones en la calzada justo delante del autobús parado está prohibida, y por eso en esta situación no estoy obligado a reducir la velocidad. Esto es:","explain":""},{"id":5598,"bg":"При тази ситуация:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39485.png","v":null,"a":[{"t":"задължен съм да спра на 1 м зад трамвая","ok":true,"i":null,"es":"estoy obligado a detenerme a 1 m detrás del tranvía"},{"t":"трябва да спра, ако преча на пешеходците да преминават през платното за движение","ok":false,"i":null,"es":"debo detenerme si impido a los peatones cruzar la calzada"},{"t":"заобикалям трамвая отляво","ok":false,"i":null,"es":"rodear el tranvía por la izquierda"}],"f":5,"es":"En esta situación:","explain":""},{"id":5606,"bg":"При тази ситуация, когато трамваят е спрял на спирка и на платното за движение няма пешеходци:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39618.png","v":null,"a":[{"t":"трябва да спра на 1 м зад трамвая","ok":true,"i":null,"es":"debo detenerme a 1 m detrás del tranvía"},{"t":"мога да премина покрай трамвая без да спирам","ok":false,"i":null,"es":"puedo pasar junto al tranvía sin detenerme"},{"t":"заобикалям трамвая отляво","ok":false,"i":null,"es":"rodear el tranvía por la izquierda"}],"f":5,"es":"En esta situación, cuando el tranvía está parado en la parada y no hay peatones en la calzada:","explain":""},{"id":5627,"bg":"Водачът на МПС, при излизане от обозначена с пътен знак жилищна зона:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"е длъжен да пропусне ППС идващи по пътя отдясно","ok":true,"i":null,"es":"está obligado a ceder el paso a los vehículos que vienen por la derecha"},{"t":"е длъжен да пропусне ППС идващи по пътя отляво","ok":true,"i":null,"es":"está obligado a ceder el paso a los vehículos que vienen por la izquierda"},{"t":"е с предимство","ok":false,"i":null,"es":"tiene prioridad"}],"f":5,"es":"El conductor, al salir de una zona residencial señalizada con señal de tráfico: (2 correctas)","explain":"Al salir de una zona residencial cedes el paso a TODOS: a los que vienen por la derecha y por la izquierda. Sales de una zona especial e ingresas en el tráfico normal: eres tú quien se incorpora, sin prioridad alguna."},{"id":12065,"bg":"При тази ситуация:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":56,"a":[{"t":"съществува опасност пешеходци да пресичат платното за движение пред автобуса","ok":true,"i":null,"es":"existe peligro de que peatones crucen la calzada delante del autobús"},{"t":"трябва да спра зад автобуса","ok":false,"i":null,"es":"debo parar detrás del autobús"},{"t":"мога да премина, като намаля скоростта и управлявам с готовност за спиране","ok":true,"i":null,"es":"puedo pasar reduciendo velocidad y con disposición de frenar"}],"f":5,"es":"En esta situación: (2 correctas)","explain":"Minibús rojo detenido en la parada de mi lado: existe peligro real de que peatones crucen por DELANTE del autobús (salen ocultos por su frontal) y, aun así, PUEDO pasar — reduciendo la velocidad y conduciendo con disposición de frenar. No es obligatorio detenerse detrás de un autobús en parada: eso solo aplica si hay señal o peatones ya cruzando. Peligro ≠ prohibición: peligro = velocidad y pie sobre el freno."},{"id":12066,"bg":"Как трябва да постъпите при тази ситуация?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":57,"a":[{"t":"разрешено е да премина покрай автобуса, като намаля скоростта, за да мога в случай на необходимост да спра","ok":true,"i":null,"es":"está permitido pasar junto al autobús reduciendo velocidad para poder frenar si es necesario"},{"t":"трябва да спра, защото е забранено преминаването покрай спрял на спирката автобус","ok":false,"i":null,"es":"debo parar porque está prohibido pasar junto a un autobús parado en parada"},{"t":"преминавам с повишено внимание, защото пешеходци могат да преминат през платното за движение","ok":true,"i":null,"es":"paso con precaución porque peatones pueden cruzar delante del autobús"}],"f":5,"es":"¿Cómo debes actuar en esta situación? (2 correctas)","explain":"El autobús rojo está parado en su parada al otro lado de la vía: NO existe prohibición de pasar junto a un autobús detenido en parada — está permitido hacerlo reduciendo la velocidad, listo para frenar, y con atención elevada porque sus pasajeros pueden cruzar la calzada por delante. 'Debo parar porque está prohibido pasar' es una regla inventada: el peligro se gestiona con precaución, no con una parada obligatoria."},{"id":5631,"bg":"На водачите на мотопеди е забранено да се движат:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"като се държат за друго превозно средство","ok":true,"i":null,"es":"agarrándose a otro vehículo"},{"t":"в непосредствена близост до друго ППС","ok":true,"i":null,"es":"muy cerca de otro vehículo"},{"t":"по пътния банкет","ok":false,"i":null,"es":"por el arcén"},{"t":"с включени светлини през деня","ok":false,"i":null,"es":"con las luces encendidas durante el día"}],"f":5,"es":"A los conductores de ciclomotores les está prohibido circular: (2 correctas)","explain":"Prohibido a los ciclomotores: agarrarse a otro vehículo (remolcarse) y circular muy cerca de otro. Circular por el arcén derecho apto les está PERMITIDO, y las luces de día son obligatorias, no prohibidas."},{"id":5706,"bg":"При теглене на повредено МПС дължината на твърдата връзка може да бъде:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2 м","ok":true,"i":null,"es":"2 m"},{"t":"3 м","ok":true,"i":null,"es":"3 m"},{"t":"4 м","ok":true,"i":null,"es":"4 m"},{"t":"5 м","ok":false,"i":null,"es":"5 m"}],"f":5,"es":"Al remolcar un vehículo averiado, la longitud del enganche rígido puede ser: (3 correctas)","explain":"El enganche RÍGIDO mide hasta 4 m: 2, 3 y 4 valen; 5 m excede el máximo. Compara con el flexible: 4-6 m. Rígido corto (control directo), flexible más largo (margen de frenado)."},{"id":5748,"bg":"При теглене на повредено МПС с твърда връзка то трябва да бъде с изправна:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"кормилна уредба","ok":true,"i":null,"es":"sistema de dirección"},{"t":"спирачна уредба","ok":false,"i":null,"es":"sistema de frenos"},{"t":"осветителна уредба","ok":false,"i":null,"es":"sistema de alumbrado"}],"f":5,"es":"Al remolcar un vehículo averiado con enganche rígido, este debe tener en buen estado:","explain":"Con enganche rígido el remolcado necesita la DIRECCIÓN en buen estado: debe seguir la trayectoria del que remolca. Los frenos los pone la barra (empuje/tiro directo) y el alumbrado no es la condición de esta norma."},{"id":5771,"bg":"Разрешено ли е с едно превозно средство тегленето на два повредени автомобила?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":5,"es":"¿Está permitido remolcar con un solo vehículo dos automóviles averiados?","explain":"No: un solo vehículo no puede remolcar dos averiados a la vez. Un tren de tres unidades improvisado es ingobernable en frenada y en curva."},{"id":5800,"bg":"Пресичането на организирани шествия, движещи се по пътищата отворени за обществено ползване, е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено за всички превозни средства, които не участват в шествието","ok":true,"i":null,"es":"prohibido para todos los vehículos que no participan en la comitiva"},{"t":"разрешено е само за водачи на двуколесни превозни средства","ok":false,"i":null,"es":"permitido solo para conductores de vehículos de dos ruedas"},{"t":"разрешено само за водачите на леки автомобили","ok":false,"i":null,"es":"permitido solo para los conductores de turismos"}],"f":5,"es":"Cruzar comitivas organizadas que circulan por vías abiertas al uso público está:","explain":"Prohibido para todos los que no participan: una comitiva organizada (militar, escolta, columna autorizada) no se corta ni se atraviesa. Da igual el tipo de vehículo: no hay excepción para motos ni turismos."},{"id":5556,"bg":"Разрешено ли е след този знак да спрете върху платното за движение за извършване на товарно-разтоварна дейност?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42332.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":5,"es":"¿Está permitido, después de esta señal, detenerse en la calzada para realizar operaciones de carga y descarga?","explain":""},{"id":5582,"bg":"При тази ситуация правилно ли е паркиран лекият автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43318.png","v":null,"a":[{"t":"не, защото паркирането е разрешено само от дясната страна на платното за движение","ok":true,"i":null,"es":"no, porque el estacionamiento solo está permitido en el lado derecho de la calzada"},{"t":"да, защото не пречи на движението","ok":false,"i":null,"es":"sí, porque no interfiere con el tráfico"}],"f":5,"es":"En esta situación, ¿está el turismo correctamente estacionado?","explain":""},{"id":5599,"bg":"На път извън населено място, където пътният банкет е с недостатъчна широчина, спирането за престой е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено най-вдясно на пътното платно","ok":true,"i":null,"es":"permitido lo más a la derecha de la plataforma vial"},{"t":"разрешено в най-дясната пътна лента","ok":false,"i":null,"es":"permitido en el carril más a la derecha"},{"t":"разрешено най-вдясно на платното за движение","ok":false,"i":null,"es":"permitido lo más a la derecha de la calzada"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":5,"es":"En una vía fuera de poblado, donde el arcén no es suficientemente ancho, la detención (parada) está:","explain":"Con arcén insuficiente fuera de poblado, se para lo más a la derecha de la PLATAFORMA VIAL (que incluye el arcén disponible), no de la calzada ni en el carril derecho. El matiz de vocabulario es exactamente lo que se pregunta."},{"id":5636,"bg":"Когато паркирането върху тротоара е разрешено, разстоянието между превозното средство и сградата трябва да бъде не по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2,0 м","ok":true,"i":null,"es":"2,0 m"},{"t":"0,5 м","ok":false,"i":null,"es":"0,5 m"},{"t":"1,0 м","ok":false,"i":null,"es":"1,0 m"},{"t":"1,5 м","ok":false,"i":null,"es":"1,5 m"}],"f":5,"es":"Cuando el estacionamiento sobre la acera está permitido, la distancia entre el vehículo y el edificio debe ser no inferior a:","explain":"2,0 m: al aparcar sobre la acera permitida debe quedar al menos ese pasillo entre vehículo y edificio para los peatones (sillas de ruedas, carritos). Menos espacio convierte la acera en un embudo."},{"id":5652,"bg":"Разрешен ли е престоят на ППС в стеснени участъци от пътя?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":5,"es":"¿Está permitida la parada de vehículos en tramos estrechos de la vía?","explain":"No: la parada en tramos estrechos está prohibida: un vehículo detenido donde apenas cabe el tráfico bloquea o fuerza maniobras peligrosas."},{"id":5653,"bg":"Разрешено ли е паркирането на ППС в стеснени участъци от пътя?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":5,"es":"¿Está permitido el estacionamiento de vehículos en tramos estrechos de la vía?","explain":"No: el estacionamiento en tramos estrechos también está prohibido, con más razón que la parada: la obstrucción es prolongada y sin conductor presente."},{"id":5657,"bg":"При паркиране преди кръстовище водачът е в нарушение, ако разстоянието от автомобила до кръстовището е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2 м","ok":true,"i":null,"es":"2 m"},{"t":"4 м","ok":true,"i":null,"es":"4 m"},{"t":"6 м","ok":false,"i":null,"es":"6 m"},{"t":"10 м","ok":false,"i":null,"es":"10 m"}],"f":5,"es":"Al estacionar antes de una intersección, el conductor comete infracción si la distancia del automóvil a la intersección es: (2 correctas)","explain":"Menos de 5 m de la intersección = infracción: 2 m y 4 m incumplen; 6 m y 10 m son legales. Misma regla que la parada: proteger la visibilidad del cruce."},{"id":5661,"bg":"Ако преместването на повредения автомобил извън платното за движение е невъзможно, отстраняването на повредата се извършва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"след поставяне на съответната сигнализация за обозначаване на автомобила","ok":true,"i":null,"es":"después de colocar la señalización correspondiente para identificar el automóvil"},{"t":"след като водачът облече светлоотразителна жилетка","ok":true,"i":null,"es":"después de que el conductor se ponga el chaleco reflectante"},{"t":"след уведомяване на контролните органи","ok":false,"i":null,"es":"después de avisar a las autoridades de control"},{"t":"след уведомяване на съответната пътна служба","ok":false,"i":null,"es":"después de avisar al servicio de carreteras correspondiente"}],"f":5,"es":"Si es imposible apartar el automóvil averiado fuera de la calzada, la reparación de la avería se realiza: (2 correctas)","explain":"Si no puedes apartar el averiado de la calzada, antes de reparar: señaliza el vehículo (triángulo, luces) y ponte el chaleco reflectante. Avisar a autoridades o al servicio de carreteras no son requisitos legales para empezar."},{"id":11851,"bg":"За престой в населено място МПС се спира:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"възможно най-вдясно на платното за движение","ok":true,"i":null,"es":"lo más a la derecha posible de la calzada"},{"t":"задължително на тротоара","ok":false,"i":null,"es":"obligatoriamente sobre la acera"},{"t":"на не повече от 70 cm от тротоара","ok":false,"i":null,"es":"a no más de 70 cm de la acera"},{"t":"възможно най-вдясно на пътното платно","ok":false,"i":null,"es":"lo más a la derecha posible de la plataforma vial"}],"f":5,"es":"Para una parada dentro de poblado, el vehículo se detiene:","explain":"La parada en poblado: lo más a la derecha posible de la CALZADA. Sobre la acera solo donde esté señalizado, y los '70 cm' no son ninguna regla: el término correcto es calzada, no plataforma vial (esa es la fórmula de fuera de poblado)."},{"id":11852,"bg":"За паркиране в населено място МПС се спира:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"възможно най-вдясно на платното за движение","ok":true,"i":null,"es":"lo más a la derecha posible de la calzada"},{"t":"задължително на тротоара","ok":false,"i":null,"es":"obligatoriamente sobre la acera"},{"t":"на не повече от 70 cm от тротоара","ok":false,"i":null,"es":"a no más de 70 cm de la acera"},{"t":"възможно най-вдясно на пътното платно","ok":false,"i":null,"es":"lo más a la derecha posible de la plataforma vial"}],"f":5,"es":"Para estacionar dentro de poblado, el vehículo se detiene:","explain":"El estacionamiento en poblado sigue la misma fórmula: lo más a la derecha posible de la CALZADA. La pareja parada/estacionamiento comparte regla dentro de poblado: la distinción calzada/plataforma vial aparece fuera."},{"id":11893,"bg":"Престоят на ППС е забранен на кръстовище и на разстояние от него, по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 метра преди кръстовище","ok":true,"i":null,"es":"5 metros ANTES de la intersección"},{"t":"5 метра след кръстовище","ok":true,"i":null,"es":"5 metros DESPUÉS de la intersección"},{"t":"10 метра преди кръстовище","ok":false,"i":null,"es":"10 metros antes"},{"t":"10 метра след кръстовище","ok":false,"i":null,"es":"10 metros después"}],"f":5,"es":"La parada breve está prohibida en intersección y a una distancia inferior a: (2 correctas)","explain":"Parada breve prohibida en la intersección y a menos de 5 m tanto ANTES como DESPUÉS de ella: a diferencia del paso de peatones (solo antes), el cruce exige visibilidad en ambos lados. El par 5m-antes/5m-después es la clave."},{"id":5664,"bg":"На водача е забранено да използва дълги светлини при:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"разминаване","ok":true,"i":null,"es":"el cruce con vehículos en sentido contrario"},{"t":"движение по осветени участъци от пътя","ok":true,"i":null,"es":"circular por tramos iluminados de la vía"},{"t":"движение зад друго МПС на разстояние, по-малко от 50 м","ok":true,"i":null,"es":"circular detrás de otro vehículo a menos de 50 m"},{"t":"намалена видимост","ok":false,"i":null,"es":"visibilidad reducida"}],"f":5,"es":"Al conductor le está prohibido usar las luces largas: (3 correctas)","explain":"Largas prohibidas: al cruzarte con tráfico de frente (deslumbras), en tramos iluminados (innecesarias) y siguiendo a otro a menos de 50 m (lo deslumbras por los retrovisores). Con visibilidad reducida las largas pueden usarse: no es un caso de prohibición."},{"id":5669,"bg":"Когато предприема изпреварване през нощта, водачът трябва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да бъде внимателен, защото има видимост само в дължината на осветения участък","ok":true,"i":null,"es":"estar atento, porque solo hay visibilidad en la longitud del tramo iluminado"},{"t":"да бъде внимателен, защото може да бъде заслепен от светлините на насрещно движещите се автомобили","ok":true,"i":null,"es":"estar atento, porque puede ser deslumbrado por las luces de los automóviles que vienen de frente"},{"t":"да подаде звуков сигнал преди да започне изпреварването","ok":false,"i":null,"es":"dar una señal acústica antes de iniciar el adelantamiento"},{"t":"да включи дългите светлини","ok":false,"i":null,"es":"encender las luces largas"}],"f":5,"es":"Al iniciar un adelantamiento de noche, el conductor debe: (2 correctas)","explain":"Al adelantar de noche: recuerda que solo ves el tramo que iluminan tus faros y que el tráfico de frente puede deslumbrarte a mitad de maniobra. Ni el claxon es obligatorio ni las largas se encienden con tráfico de frente."},{"id":5680,"bg":"Разрешено ли е допълнителните светлини за мъгла да се използват при дъжд?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само при значително намалена видимост","ok":true,"i":null,"es":"sí, pero solo con visibilidad considerablemente reducida"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Está permitido usar las luces antiniebla adicionales con lluvia?","explain":"Con lluvia sí, pero SOLO si la visibilidad está considerablemente reducida: una llovizna no lo justifica. La antiniebla es una luz agresiva: su uso injustificado deslumbra."},{"id":5684,"bg":"Превключването от дълги на къси светлини преди разминаване през нощта се извършва, когато разстоянието между двата автомобила е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"не по-малко от 50 м","ok":false,"i":null,"es":"no menos de 50 m"},{"t":"не по-малко от 100 м","ok":false,"i":null,"es":"no menos de 100 m"},{"t":"не по-малко от 150 м","ok":true,"i":null,"es":"no menos de 150 m"},{"t":"не по-малко от 200 м","ok":false,"i":null,"es":"no menos de 200 m"}],"f":5,"es":"El cambio de largas a cortas al cruzarse de noche se hace cuando la distancia es:","explain":"A no menos de 150 m: es la distancia legal para pasar de largas a cortas ante tráfico de frente. A menos distancia ya estás deslumbrando al otro conductor en plena aproximación."},{"id":5686,"bg":"Преди разминаване през нощта, когато водачът на насрещното МПС подаде сигнал чрез светлините, длъжни ли сте да превключите от дълги на къси светлини?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да, независимо от разстоянието","ok":true,"i":null,"es":"sí, independientemente de la distancia"},{"t":"не, ако разстоянието е по-голямо от 150 м","ok":false,"i":null,"es":"no, si la distancia es superior a 150 m"},{"t":"не, защото не съм длъжен да се съобразявам с неговите сигнали","ok":false,"i":null,"es":"no, porque no estoy obligado a obedecer sus señales"},{"t":"да, но само ако разстоянието между автомобилитге е по-малко от 50 м","ok":false,"i":null,"es":"sí, pero solo si la distancia entre los automóviles es inferior a 50 m"}],"f":5,"es":"Antes de cruzarse de noche, cuando el conductor del vehículo que viene de frente hace señales con las luces, ¿está obligado a cambiar de largas a cortas?","explain":"Sí, sea cual sea la distancia: si el que viene de frente te hace señales con las luces, es que YA le estás deslumbrando: cambia a cortas de inmediato. Su señal indica un hecho, no una petición discutible."},{"id":5699,"bg":"При намалена видимост под 50 м е забранено:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"паркирането","ok":false,"i":null,"es":"el aparcamiento"},{"t":"тегленето","ok":true,"i":null,"es":"remolcar"},{"t":"завиването в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"движението без включени светлини","ok":true,"i":null,"es":"circular sin las luces encendidas"}],"f":5,"es":"Con visibilidad reducida por debajo de 50 m está prohibido: (3 correctas)","explain":"Bajo 50 m de visibilidad está prohibido: remolcar, dar la vuelta y circular sin luces: nadie te vería llegar ni maniobrar. El aparcamiento no entra en esta prohibición."},{"id":5703,"bg":"При намалена видимост под 50 м е забранено:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"спирането за престой на платното за движение извън населено място без включени габаритни светлини","ok":true,"i":null,"es":"detenerse para una parada en la calzada fuera de poblado sin las luces de posición encendidas"},{"t":"движението на извънгабаритни ППС","ok":true,"i":null,"es":"la circulación de vehículos de dimensiones excepcionales"},{"t":"изпреварването","ok":false,"i":null,"es":"el adelantamiento"},{"t":"движението на самоходни машини","ok":false,"i":null,"es":"la circulación de máquinas autopropulsadas"}],"f":5,"es":"Con visibilidad reducida por debajo de 50 m está prohibido: (2 correctas)","explain":"Bajo 50 m: prohibido parar en calzada fuera de poblado sin luces de posición y prohibida la circulación de vehículos de dimensiones excepcionales. El adelantamiento y las máquinas autopropulsadas no están prohibidos por esta norma específica."},{"id":5704,"bg":"При намалена видимост под 50 м е забранено:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"движението на извънгабаритни ППС","ok":true,"i":null,"es":"la circulación de vehículos de dimensiones excepcionales"},{"t":"спирането за престой на платното за движение на извънгабаритни ППС","ok":true,"i":null,"es":"la parada en la calzada de vehículos de dimensiones excepcionales"},{"t":"изпреварването","ok":false,"i":null,"es":"el adelantamiento"},{"t":"движението на самоходни машини","ok":false,"i":null,"es":"la circulación de máquinas autopropulsadas"}],"f":5,"es":"Con visibilidad reducida por debajo de 50 m está prohibido: (2 correctas)","explain":"Los vehículos de dimensiones excepcionales tienen doble prohibición bajo 50 m de visibilidad: ni circular ni parar en la calzada: su tamaño invisible es una trampa mortal. Adelantar y las autopropulsadas quedan fuera de esta prohibición."},{"id":6121,"bg":"Какво влияние оказва алкохолът върху поведението на водача на МПС?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"влошава координацията на движенията","ok":true,"i":null,"es":"empeora la coordinación"},{"t":"намалява концентрацията","ok":true,"i":null,"es":"reduce la concentración"},{"t":"ускорява реакциите","ok":false,"i":null,"es":"acelera las reacciones"},{"t":"повишава вниманието","ok":false,"i":null,"es":"aumenta la atención"}],"f":5,"es":"¿Qué influencia tiene el alcohol sobre el comportamiento del conductor? (2 correctas)","explain":"El alcohol empeora la coordinación y reduce la concentración: motricidad y atención degradadas a la vez. 'Acelera las reacciones' y 'aumenta la atención' son los mitos exactamente inversos a la realidad."},{"id":6125,"bg":"Ако след продължително управление водачът се чувства уморен и усеща, че може да заспи на волана, трябва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да спре за почивка","ok":true,"i":null,"es":"detenerse a descansar"},{"t":"да консумира тонизиращи напитки - чай или кафе","ok":false,"i":null,"es":"consumir bebidas estimulantes: té o café"},{"t":"да увеличи скоростта, за да концентрира вниманието си","ok":false,"i":null,"es":"aumentar la velocidad para concentrar su atención"}],"f":5,"es":"Si tras conducir mucho tiempo el conductor se siente fatigado y nota que puede dormirse al volante, debe:","explain":"Detenerse a descansar: es la única respuesta real al sueño al volante. El café da un alivio breve y traicionero, y aumentar la velocidad con sueño es multiplicar el riesgo justo cuando menos capacidad tienes."},{"id":6130,"bg":"Ако по време на управление водачът се чувства уморен, до намирането на безопасно място за спиране, е добре :","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да осигури достъп на свеж въздух в купето","ok":true,"i":null,"es":"asegurar la entrada de aire fresco en el habitáculo"},{"t":"да разговаря с пътниците в автомобила","ok":true,"i":null,"es":"conversar con los pasajeros del automóvil"},{"t":"да увеличи скоростта за да намери по-бързо място за спиране","ok":false,"i":null,"es":"aumentar la velocidad para encontrar más rápido un lugar donde detenerse"},{"t":"да сменя непрекъснато предавките за да подобри концентрацията си","ok":false,"i":null,"es":"cambiar de marcha continuamente para mejorar su concentración"}],"f":5,"es":"Si durante la conducción el conductor se siente fatigado, hasta encontrar un lugar seguro donde detenerse es conveniente: (2 correctas)","explain":"Hasta poder parar en sitio seguro: aire fresco al habitáculo y conversación con los pasajeros: estímulos suaves que mantienen despierto. Acelerar o jugar con las marchas no combate el sueño: añade riesgo."},{"id":6141,"bg":"Продължителното слушане на силна музика при управление на автомобил:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"стимулира способността за концентриране","ok":false,"i":null,"es":"estimula la capacidad de concentración"},{"t":"намалява способността за концентриране","ok":true,"i":null,"es":"REDUCE la capacidad de concentración"},{"t":"тренира и подобрява способността за чуване","ok":false,"i":null,"es":"entrena y mejora la audición"},{"t":"успокоява водача","ok":false,"i":null,"es":"tranquiliza al conductor"}],"f":5,"es":"Escuchar música alta durante la conducción:","explain":"REDUCE la capacidad de concentración: la música alta prolongada satura la atención y enmascara los sonidos del tráfico (sirenas, claxon, motor). Ni estimula, ni entrena el oído, ni tranquiliza a efectos de conducción."},{"id":6144,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"намаляване на бдителността","ok":true,"i":null,"es":"la disminución de la atención (vigilancia)"},{"t":"повишаване на устойчивостта на вниманието","ok":false,"i":null,"es":"el aumento de la estabilidad de la atención"},{"t":"нарушаване на сензомоторната координация","ok":true,"i":null,"es":"la alteración de la coordinación sensomotora"},{"t":"проблеми с кратковременната памет","ok":true,"i":null,"es":"problemas con la memoria a corto plazo"}],"f":5,"es":"Los signos de advertencia de fatiga en el conductor son: (3 correctas)","explain":"Señales de fatiga: cae la vigilancia, se altera la coordinación sensomotora y falla la memoria a corto plazo (¿he pasado ya ese pueblo?). El 'aumento de la estabilidad de la atención' es lo contrario: señal de frescura."},{"id":6147,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"забавено мислене","ok":true,"i":null,"es":"pensamiento ralentizado"},{"t":"появата на чувство за комфортност","ok":false,"i":null,"es":"la aparición de una sensación de comodidad"},{"t":"прояви на нетърпение","ok":true,"i":null,"es":"muestras de impaciencia"},{"t":"увеличени периоди на микросън","ok":true,"i":null,"es":"períodos aumentados de microsueño"}],"f":5,"es":"Los signos de advertencia de fatiga en el conductor son: (3 correctas)","explain":"Más señales de fatiga: pensamiento ralentizado, impaciencia creciente y episodios de MICROSUEÑO cada vez más largos (segundos dormido sin saberlo). La 'sensación de comodidad' no es síntoma de fatiga."},{"id":6152,"bg":"Умората на водача е причина за понижаване на устойчивостта и концентрацията на вниманието, което може да доведе до:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"неволно отклоняване от посоката на движение","ok":true,"i":null,"es":"desviarse involuntariamente de la dirección de marcha"},{"t":"повишаване на способността за предвиждане на ситуациите","ok":false,"i":null,"es":"el aumento de la capacidad de prever las situaciones"},{"t":"пропускане на пътни знаци и сигнали","ok":true,"i":null,"es":"pasar por alto señales de tráfico y semáforos"},{"t":"напускане на платното за движение","ok":true,"i":null,"es":"salirse de la calzada"}],"f":5,"es":"La fatiga del conductor causa una disminución de la estabilidad y concentración de la atención, lo que puede llevar a: (3 correctas)","explain":"La fatiga lleva a: desviarse involuntariamente de la trayectoria, saltarse señales y semáforos sin verlos, y salirse de la calzada. 'Aumento de la capacidad de prever' es el distractor absurdo: la fatiga solo resta."},{"id":6000,"bg":"При управление на състав от ППС водачът трябва ли да носи свидетелство за регистрация на тегленото ремарке?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"Al conducir un conjunto de vehículos, ¿debe llevar el conductor el permiso de circulación del remolque?","explain":"Sí: el remolque tiene su propio permiso de circulación (parte 2) y debe llevarse a bordo, igual que el del vehículo tractor. El conjunto exige la documentación de ambas unidades."},{"id":6004,"bg":"Допуска ли се на задната седалка в лек автомобил да се превозват повече от определения брой пътници?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не се допуска","ok":true,"i":null,"es":"no está permitido"},{"t":"допуска се превозването на едно дете до 7 години","ok":false,"i":null,"es":"se permite transportar a un niño de hasta 7 años"},{"t":"допуска се превозването на едно дете до 14 години","ok":false,"i":null,"es":"se permite transportar a un niño de hasta 14 años"}],"f":5,"es":"¿Se permite transportar en el asiento trasero de un turismo más pasajeros del número establecido?","explain":"No está permitido: el número de plazas del permiso de circulación es el máximo absoluto: cada pasajero necesita asiento y cinturón. No hay excepción por edad: los niños cuentan como pasajeros (y necesitan además su sistema de retención)."},{"id":6005,"bg":"Какви са задълженията на водача, ако по време на движение товарът, който превозва, падне на пътя?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да вземе необходимите мерки за сигнализиране на товара и превозното средство","ok":true,"i":null,"es":"tomar las medidas necesarias para señalizar la carga y el vehículo"},{"t":"да вземе мерки за отстраняване на товара от пътя","ok":true,"i":null,"es":"tomar medidas para retirar la carga de la vía"},{"t":"водачът няма задължения във връзка с товара, който превозва","ok":false,"i":null,"es":"el conductor no tiene obligaciones respecto a la carga que transporta"},{"t":"длъжен е само да уведоми пътните органи","ok":false,"i":null,"es":"solo está obligado a avisar a las autoridades viales"}],"f":5,"es":"¿Cuáles son las obligaciones del conductor si durante la marcha la carga que transporta cae a la vía? (2 correctas)","explain":"Si la carga cae a la vía: señaliza la carga y el vehículo, y toma medidas para RETIRARLA. Es tu carga y tu responsabilidad: 'avisar y desentenderse' no existe como opción legal."},{"id":11372,"bg":"Водачът на ППС е длъжен да не извършва маневри, изразяващи се в последователно внезапно преминаване в лентите за движение:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само в населените места","ok":false,"i":null,"es":"solo dentro de poblado"},{"t":"само извън населените места","ok":false,"i":null,"es":"solo fuera de poblado"},{"t":"в населените и извън населените места","ok":true,"i":null,"es":"dentro Y fuera de poblado"}],"f":5,"es":"El conductor no debe realizar maniobras de cambio de carril brusco y consecutivo:","explain":"Los cambios de carril bruscos y consecutivos (zigzag) están prohibidos DENTRO Y FUERA de poblado: no hay territorio donde el zigzag sea legal. Las opciones 'solo dentro' o 'solo fuera' recortan falsamente la prohibición."},{"id":11737,"bg":"В кой от изброените случаи водачът е длъжен да използва обезопасителния колан?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"при движение по път извън населено място","ok":true,"i":null,"es":"al circular por una vía fuera de poblado"},{"t":"при движение по път в населено място","ok":true,"i":null,"es":"al circular por una vía dentro de poblado"},{"t":"при движение по автомагистрала","ok":true,"i":null,"es":"al circular por autopista"},{"t":"само при движение със скорост над 30 km/h","ok":false,"i":null,"es":"solo al circular a más de 30 km/h"}],"f":5,"es":"¿En cuál de los casos indicados está obligado el conductor a usar el cinturón de seguridad? (3 correctas)","explain":"El cinturón es obligatorio SIEMPRE que se circula: dentro de poblado, fuera y en autopista. No existe umbral de velocidad que exima: los 30 km/h de la opción falsa son un mito (a 30 km/h un impacto ya es grave)."},{"id":11822,"bg":"Разрешено ли е тегленето на ремарке без регистрационен номер?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не е разрешено","ok":true,"i":null,"es":"no está permitido"},{"t":"да, когато ремаркето е с допустима максимална маса до 750 kg","ok":false,"i":null,"es":"sí, cuando el remolque tiene una masa máxima autorizada de hasta 750 kg"},{"t":"да, когато ремаркето се тегли от колесен трактор","ok":false,"i":null,"es":"sí, cuando el remolque es remolcado por un tractor de ruedas"},{"t":"да, когато ремаркето е едноосно","ok":false,"i":null,"es":"sí, cuando el remolque es de un eje"}],"f":5,"es":"¿Está permitido remolcar un remolque sin matrícula?","explain":"No: el remolque circula con su matrícula, sin excepciones por masa, tipo de tractor ni número de ejes. Sin matrícula no está identificado y no puede estar en la vía."},{"id":5448,"bg":"Извършва ли нарушение водач, който превиши разрешената скорост за движение, но с това не създава непосредствена опасност за движението?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Comete infracción el conductor que supera la velocidad permitida, pero sin crear con ello un peligro inmediato para el tráfico?","explain":"Sí: superar el límite es infracción en sí misma, haya o no peligro inmediato. El peligro agrava la sanción, pero su ausencia no legaliza el exceso."},{"id":5456,"bg":"Извършва ли нарушение водач, който управлява технически неизправно МПС, което не е негова собственост?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Comete infracción el conductor que conduce un vehículo con deficiencias técnicas que no es de su propiedad?","explain":"Sí: conducir un vehículo con deficiencias técnicas es infracción del CONDUCTOR, sea suyo o no. Al ponerte al volante asumes la responsabilidad del estado del vehículo."},{"id":5458,"bg":"Извършва ли нарушение водач, който управлява МПС в непосредствена близост до дома си, без да носи свидетелството си за управление?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Comete infracción el conductor que conduce muy cerca de su casa sin llevar su permiso de conducción?","explain":"Sí: el permiso de conducción debe llevarse SIEMPRE, también a 100 m de casa. La cercanía del trayecto no exime de la obligación documental."},{"id":5498,"bg":"Когато при съставяне на фиш за констатирано нарушение, лицето извършило нарушението откаже да подпише фиша:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"се съставя акт","ok":true,"i":null,"es":"se levanta un acta"},{"t":"фишът се подписва от двама свидетели","ok":false,"i":null,"es":"el boletín lo firman dos testigos"},{"t":"на място се налага глоба по квитанция","ok":false,"i":null,"es":"se impone en el acto una multa con recibo"}],"f":5,"es":"Cuando, al extenderse un boletín por una infracción constatada, la persona que la cometió se niega a firmarlo:","explain":"Si el infractor se niega a firmar el boletín, se levanta un ACTA: el procedimiento pasa al cauce formal. Ni los testigos firman por él ni la negativa se convierte en multa instantánea con recibo."},{"id":8299,"bg":"Какво наказание се налага на водач, когато за период от една година има влезли в сила две наказателни постановления за неосигуряване на предимство на пешеходци на пешеходна пътека?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso de conducir"},{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"}],"f":5,"es":"¿Qué sanción se impone a un conductor con dos sanciones firmes en un año?","explain":"Con dos sanciones firmes en un año: multa Y privación del permiso: la reincidencia se castiga con la sanción combinada, no con una u otra."},{"id":11376,"bg":"Контролните органи временно отнемат свидетелството за управление на МПС на водач:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"който управлява моторно превозно средство с концентрация на алкохол в кръвта над 0,5 на хиляда","ok":true,"i":null,"es":"que conduzca un vehículo de motor con una concentración de alcohol en sangre superior a 0,5 por mil"},{"t":"който управлява моторно превозно средство под въздействието на наркотично вещество","ok":true,"i":null,"es":"que conduzca un vehículo de motor bajo los efectos de sustancias estupefacientes"},{"t":"който откаже да бъде проверен от контролните органи за наличие на алкохол в кръвта","ok":true,"i":null,"es":"que se niegue a ser sometido por los agentes al control de alcohol en sangre"},{"t":"когато водачът паркира автомобила на място, където това е забранено","ok":false,"i":null,"es":"cuando el conductor estaciona el automóvil en un lugar donde está prohibido"}],"f":5,"es":"Las autoridades de control retiran temporalmente el permiso de conducción al conductor: (3 correctas)","explain":"Retirada temporal del permiso: alcohol por encima de 0,5‰, conducción bajo estupefacientes y NEGARSE al control (la negativa se trata como positivo). El mal estacionamiento se multa, pero no retira el permiso."},{"id":11400,"bg":"Контролните органи прекратяват регистрацията на пътно превозно средство на собственик, който управлява моторното превозно средство:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"без да притежава съответното свидетелство за управление","ok":true,"i":null,"es":"sin poseer el permiso de conducción correspondiente"},{"t":"с концентрация на алкохол в кръвта над 0,5 на хиляда","ok":true,"i":null,"es":"con una concentración de alcohol en sangre superior a 0,5 por mil"},{"t":"след употреба на наркотични вещества или техни аналози","ok":true,"i":null,"es":"tras el consumo de sustancias estupefacientes o sus análogos"},{"t":"има наложено наказание глоба, незаплатена в срока за доброволно заплащане","ok":false,"i":null,"es":"tiene impuesta una multa no pagada en el plazo de pago voluntario"}],"f":5,"es":"Las autoridades de control dan de baja la matriculación del vehículo del propietario que conduce el vehículo de motor: (3 correctas)","explain":"Baja de la matriculación del vehículo cuyo propietario conduce: sin permiso correspondiente, con más de 0,5‰ de alcohol o tras consumir estupefacientes: las infracciones gravísimas golpean también al vehículo. Una multa impagada no da de baja la matrícula."},{"id":11404,"bg":"Контролните органи не допускат управлението на МПС, когато при проверката са установили, че водачът:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не притежава съответното свидетелство за управление","ok":true,"i":null,"es":"no posee el permiso de conducción correspondiente"},{"t":"е с концентрация на алкохол в кръвта над 0,5 на хиляда","ok":true,"i":null,"es":"tiene una concentración de alcohol en sangre superior a 0,5 por mil"},{"t":"е употребил наркотично вещество","ok":true,"i":null,"es":"ha consumido una sustancia estupefaciente"},{"t":"не е заплатил задължителната застраховка „Гражданска отговорност“ на автомобилиста","ok":false,"i":null,"es":"no ha pagado el seguro obligatorio de responsabilidad civil del automovilista"}],"f":5,"es":"Las autoridades de control no permiten la conducción del vehículo cuando en el control comprueban que el conductor: (3 correctas)","explain":"No permiten seguir conduciendo a quien: no tiene el permiso correspondiente, supera 0,5‰ de alcohol o ha consumido estupefacientes: peligro inmediato al volante. El seguro impagado acarrea sanción, pero no impide físicamente continuar en ese control."},{"id":11728,"bg":"Водач, който превиши разрешената максимална скорост за движение в населено място с над 50 km/h се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"},{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso de conducir"}],"f":5,"es":"El conductor que supera el límite de velocidad en zona urbana en más de 50 km/h es sancionado con:","explain":"Superar en más de 50 km/h el límite urbano: multa Y privación del permiso. A esa magnitud el exceso deja de ser multa simple: es de las infracciones de velocidad más graves."},{"id":5318,"bg":"Разрешено ли е да се премества превозно средство участвало в ПТП с пострадали хора, ако то не пречи на движението?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не, освен ако се налага да превози пострадалите до здравно заведение","ok":true,"i":null,"es":"no, salvo que sea necesario transportar a los heridos a un centro de salud"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"не, забранено е във всички случаи","ok":false,"i":null,"es":"no, está prohibido en todos los casos"}],"f":5,"es":"¿Está permitido mover un vehículo implicado en un accidente con heridos, si no obstaculiza el tráfico?","explain":"No, salvo para transportar a los heridos a un centro de salud: si el vehículo no obstaculiza el tráfico, su posición debe conservarse para la investigación. La otra excepción (obstaculizar) aquí no aplica por el propio enunciado."},{"id":5335,"bg":"Задължен ли е водачът на МПС да вземе мерки за сигнализиране и обезопасяване на мястото на ПТП?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само ако е участник в произшествието","ok":false,"i":null,"es":"sí, pero solo si está implicado en el accidente"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Está obligado el conductor a tomar medidas para señalizar y asegurar el lugar del accidente?","explain":"Sí, en todos los casos: señalizar y asegurar el lugar del accidente es obligación de todo conductor que llega, esté o no implicado. Prevenir el segundo accidente es lo primero."},{"id":5336,"bg":"Какви данни е длъжен да дава за себе си участникът в ПТП?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"за самоличността си","ok":true,"i":null,"es":"de su identidad"},{"t":"за задължителната си застраховка","ok":true,"i":null,"es":"de su seguro obligatorio"},{"t":"за собствеността на автомобила","ok":false,"i":null,"es":"de la propiedad del automóvil"}],"f":5,"es":"¿Qué datos sobre sí mismo está obligado a dar el implicado en un accidente? (2 correctas)","explain":"El implicado debe dar sus datos de identidad y de su seguro obligatorio: lo necesario para tramitar la responsabilidad. La propiedad del automóvil no es dato exigido: puedes conducir un coche ajeno legalmente."},{"id":5343,"bg":"Задължен ли е водачът да уведоми собственика на имуществото, което е повредил при ПТП?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Está obligado el conductor a avisar al propietario de los bienes que ha dañado en un accidente?","explain":"Sí: si dañas bienes ajenos en un accidente (valla, farola, coche aparcado), debes avisar a su propietario. Marcharse sin avisar convierte el accidente en fuga."},{"id":5357,"bg":"При позвъняването на телефон 112 може да се получи помощ от следните служби за спешно реагиране:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"полиция и пожарна безопасност и спасяване","ok":true,"i":null,"es":"policía y bomberos (seguridad contra incendios y rescate)"},{"t":"спешна медицинска помощ","ok":true,"i":null,"es":"asistencia médica de urgencia"},{"t":"гражданска защита","ok":true,"i":null,"es":"protección civil"},{"t":"пътна помощ","ok":false,"i":null,"es":"asistencia en carretera"}],"f":5,"es":"Al llamar al teléfono 112 se puede recibir ayuda de los siguientes servicios de emergencia: (3 correctas)","explain":"El 112 conecta con policía, bomberos/rescate, asistencia médica de urgencia y protección civil: los servicios públicos de emergencia. La asistencia en carretera (grúa) es un servicio privado: no va por el 112."},{"id":5257,"bg":"Кой знак предупреждава за изкуствени неравности по платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23475.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23476.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334749.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21035.png","es":""}],"f":5,"es":"¿Cuál de las señales advierte de badenes artificiales en la calzada?","explain":"Los badenes artificiales (reductor de velocidad) se senalizan con triangulo especifico. Son obstaculos intencionados para reducir la velocidad."},{"id":6484,"bg":"Този знак:","p":3,"s":"Раздел 4","i":"66232","v":null,"a":[{"t":"указва място за излизане на пешеходците от автомагистрала","ok":false,"i":null,"es":"indica salida de peatones de la autopista"},{"t":"обозначава направление към пешеходен подлез","ok":false,"i":null,"es":"indica la dirección hacia un paso subterráneo de peatones"},{"t":"указва посока за движение към авариен изход в тунел","ok":true,"i":null,"es":"indica la dirección hacia una salida de emergencia en un túnel"},{"t":"указва задължителна посока за движение по пешеходна алея","ok":false,"i":null,"es":"indica el sentido obligatorio de circulación por una senda peatonal"}],"f":5,"es":"Esta señal:","explain":"Indica la dirección hacia una SALIDA DE EMERGENCIA en un túnel.\n\nLA SEÑAL. Rectángulo verde con la silueta de una persona corriendo, una flecha y una distancia — «100 м». Verde con figura corriendo es el código internacional de evacuación.\n\nQUÉ TE DICE EXACTAMENTE. Hacia qué lado está la salida más próxima y a cuántos metros. En un túnel con humo esa información se lee a ras de suelo cuando ya no se ve nada, y por eso se repite cada pocos metros.\n\nQUÉ HACER SI HAY QUE EVACUAR: parar el coche pegado al lateral, dejar las llaves puestas y las luces de emergencia, y salir a pie hacia la salida indicada. No dar media vuelta dentro del túnel.\n\n«DIRECCIÓN HACIA UN PASO SUBTERRÁNEO DE PEATONES» — пешеходен подлез — es el distractor principal, y comparte el símbolo del peatón. Se distingue porque el подлез se dibuja bajando escaleras, no corriendo.\n\n«SALIDA DE PEATONES DE LA AUTOPISTA» y «SENTIDO OBLIGATORIO POR SENDA PEATONAL» no existen con este diseño.\n\nCLAVE: peatón CORRIENDO + verde + distancia = evacuación. Peatón andando o bajando escaleras = paso peatonal.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5243,"bg":"Кой от пътните знаци предупреждава, че ще навлезете в опасен завой?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21012.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21013.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21035.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21036.png","es":""}],"f":5,"es":"¿Cuál de las señales advierte de que entras en una curva peligrosa? (2 correctas)","explain":"Triangulo rojo con curva - fijate en la direccion de la flecha para saber si es derecha o izquierda."},{"id":5518,"bg":"С кой от опознавателните знаци се обозначава ремаркетата?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23536.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23537.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23538.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23539.png","es":""}],"f":5,"es":"¿Con cuál de los signos distintivos se identifican los remolques? (2 correctas)","explain":"El triangulo reflectante trasero identifica remolques. Obligatorio cuando el tren de vehiculos supera ciertas dimensiones."},{"id":5252,"bg":"Кой от пътните знаци предупреждава за стеснение на платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"es":"","i":"21285"},{"t":"","ok":true,"es":"","i":"334668"},{"t":"","ok":false,"es":"","i":"334749"},{"t":"","ok":false,"es":"","i":"21286"}],"f":5,"es":"¿Cuál de las señales advierte de estrechamiento de la calzada? (2 correctas)","explain":"Hay 3 variantes segun el lado: estrechamiento por izquierda, por derecha, o por ambos lados. Fijate que lado pierde espacio."},{"id":5289,"bg":"Кой от пътните знаци предупреждава за приближаване към железопътен прелез?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"25626"},{"t":"","ok":true,"es":"","i":"334679"},{"t":"","ok":true,"es":"","i":"334680"},{"t":"","ok":false,"es":"","i":"21411"}],"f":5,"es":"¿Cuál de las señales advierte de la proximidad de un paso a nivel? (2 correctas)","explain":"Las senales de paso a nivel son triangulos con locomotora o aspas de San Andres. Hay variantes con y sin barreras."},{"id":5324,"bg":"Кое от показаните превозни средства е автомобил?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128893.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128894.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128827.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128896.png","es":""}],"f":5,"es":"¿Cuál de los vehículos mostrados es un automóvil? (3 correctas)","explain":"Automovil tiene motor, 4+ ruedas, hasta 3500 kg (cat. B). Diferencia de tractor, moto y ciclomotor."},{"id":11863,"bg":"Кой от показаните пътни знаци отменя забраната товарни автомобили с допустима максимална маса над 3.5 t. да изпреварват МПС, с изключение на мотоциклети без кош и мотопеди?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/76505283.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/76505284.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/76505285.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/76505286.png","es":""}],"f":5,"es":"¿Cuál de las señales mostradas cancela la prohibición de que los camiones con masa máxima admisible superior a 3,5 t adelanten a vehículos de motor, excepto motos sin sidecar y ciclomotores? (3 correctas)","explain":"El fin de prohibicion de adelantamiento para camiones es un circulo con lineas tachadas que se separan."},{"id":5293,"bg":"Кой знак указва, че железопътният прелез е с един коловоз?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334682.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/101894.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334679.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334680.png","es":""}],"f":5,"es":"¿Qué señal indica que el paso a nivel tiene una sola vía?","explain":"Una aspa de San Andres = una via ferroviaria. Dos aspas = dos o mas vias. Importante porque el peligro es diferente."},{"id":6043,"bg":"Когато се подава с ръка, сигналът за спиране е:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27561.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27562.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27563.png","es":""}],"f":5,"es":"Cuando se da con el brazo, la señal de parada es:","explain":"El brazo extendido verticalmente hacia arriba indica detencion. Usado cuando el sistema de frenado no funciona."},{"id":6190,"bg":"На кой от пътните знаци значението е “Движение само надясно пред знака”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45469.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45433.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334697.png","es":""}],"f":5,"es":"¿En cuál de las señales el significado es 'Circulación obligatoria solo a la derecha antes de la señal'?","explain":"Flecha obligatoria a la derecha ANTES de la senal = debes girar antes de llegar a ella. Diferente de despues."},{"id":5265,"bg":"Кой от пътните знаци предупреждава за приближаване към кръстовище на равнозначни пътища?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334675.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25039.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23809.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25041.png","es":""}],"f":5,"es":"¿Cuál de las señales advierte de la proximidad de una intersección de vías equivalentes?","explain":"Triangulo con cruz = interseccion de vias sin prioridad. Aplica norma de la derecha."},{"id":11583,"bg":"Номерът на автомагистрала по националната класификация се означава с:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20070.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20071.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20072.png","es":""}],"f":5,"es":"El número de autopista según la clasificación nacional se indica con:","explain":"Las autopistas nacionales en Bulgaria usan la letra A (ej: A1, A2). Las internacionales usan E."},{"id":5526,"bg":"С кой от знаците се обозначава МПС превозващо опасен товар?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23649.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23650.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23651.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334752.png","es":""}],"f":5,"es":"¿Con cuál de los signos se identifica un vehículo que transporta mercancía peligrosa?","explain":"Panel naranja rectangular (ADR) con numeros de peligro y materia. Obligatorio en vehiculos ADR."},{"id":6200,"bg":"След кой пътен знак действат правилата за движение в тунел?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46087.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46088.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46089.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46090.png","es":""}],"f":5,"es":"¿Después de cuál señal se aplican las normas de circulación en túnel?","explain":"La senal de tunel (rectangulo negro con curva blanca) indica inicio de tunel y sus normas especiales."},{"id":5431,"bg":"Когато налягането на въздуха в автомобилната гума е по-високо от предписаното, протекторът на гумата се износва:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"неравномерно, на отделни места","ok":false,"i":null,"es":"de forma irregular, en puntos aislados"},{"t":"само по външната страна на протектора","ok":false,"i":null,"es":"solo en el lado exterior de la banda de rodadura"},{"t":"в средата на протектора по цялата окръжност","ok":true,"i":null,"es":"en el centro de la banda de rodadura, en toda la circunferencia"},{"t":"само по вътрешната страна на протектора","ok":false,"i":null,"es":"solo en el lado interior de la banda de rodadura"}],"f":4,"es":"Cuando la presión de aire del neumático es más alta que la prescrita, la banda de rodadura se desgasta:","explain":"Con presión ALTA el neumático se abomba y apoya solo el CENTRO: desgaste central en toda la circunferencia. Es el espejo de la presión baja (desgaste en ambos bordes): el par presión-desgaste va junto."},{"id":6687,"bg":"Коя от изброените неизправности води до „пропадане” на спирачния педал?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"изтичането на спирачна течност","ok":true,"i":null,"es":"una fuga de líquido de frenos"},{"t":"омасляването на спирачните накладки","ok":false,"i":null,"es":"el engrase (contaminación con aceite) de las pastillas de freno"},{"t":"високото ниво на спирачната течност","ok":false,"i":null,"es":"el nivel alto del líquido de frenos"},{"t":"високата температура на спирачната течност","ok":false,"i":null,"es":"la temperatura alta del líquido de frenos"}],"f":4,"es":"¿Cuál de las averías indicadas provoca que el pedal de freno \"se hunda\"?","explain":"El pedal 'se hunde' por FUGA de líquido de frenos: sin líquido no hay presión hidráulica que transmitir. Las pastillas engrasadas frenan mal pero el pedal responde; el nivel alto o la temperatura no producen ese síntoma."},{"id":6162,"bg":"Антиблокиращата спирачна система (ABS) е предназначена:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"да подобри устойчивостта на автомобила","ok":true,"i":null,"es":"mejorar la estabilidad del automóvil"},{"t":"да подобри управляемостта на автомобила при спиране","ok":true,"i":null,"es":"mejorar la maniobrabilidad del automóvil al frenar"},{"t":"да увеличи налягането в спирачната система","ok":false,"i":null,"es":"aumentar la presión del sistema de frenos"},{"t":"да намали свободния ход на спирачния педал","ok":false,"i":null,"es":"reducir el recorrido libre del pedal de freno"}],"f":4,"es":"El sistema antibloqueo de frenos (ABS) está destinado a: (2 correctas)","explain":"El ABS mejora la estabilidad y la maniobrabilidad AL FRENAR: con las ruedas girando puedes seguir dirigiendo. No aumenta la presión del circuito ni acorta el recorrido del pedal: actúa modulando, no potenciando."},{"id":6165,"bg":"Какъв е резултатът от действието на електронната стабилизираща система (ESP)?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"запазва траекторията на движение при резки маневри","ok":true,"i":null,"es":"mantiene la trayectoria en maniobras bruscas"},{"t":"не позволява на автомобила да потегли, когато е спрян в наклон","ok":false,"i":null,"es":"no permite que el automóvil se desplace cuando está detenido en pendiente"},{"t":"не позволява развиването на високи скорости","ok":false,"i":null,"es":"no permite alcanzar altas velocidades"},{"t":"поддържа постоянна скоросттта на движение","ok":false,"i":null,"es":"mantiene constante la velocidad de circulación"}],"f":4,"es":"¿Cuál es el resultado de la acción del sistema electrónico de estabilidad (ESP)?","explain":"El ESP mantiene la TRAYECTORIA en maniobras bruscas: frena ruedas individuales para corregir derrapes. No es el freno de estacionamiento en pendiente (hill-holder), no limita la velocidad ni la mantiene constante (eso es el crucero)."},{"id":5434,"bg":"При намалена дължина на участъка от пътя, осветяван от фаровете на автомобила, е необходимо:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"да се регулират фаровете","ok":true,"i":null,"es":"regular los faros"},{"t":"да се подмени акумулаторната батерия","ok":false,"i":null,"es":"sustituir la batería"},{"t":"да се подменят източниците на светлина","ok":false,"i":null,"es":"sustituir las fuentes de luz (bombillas)"},{"t":"да се провери окачването на автомобила","ok":false,"i":null,"es":"revisar la suspensión del automóvil"}],"f":4,"es":"Cuando se reduce la longitud del tramo de vía iluminado por los faros del automóvil, es necesario:","explain":"Si el haz de los faros se acorta: REGULAR los faros: se han desajustado (altura de carga, golpe). La batería no cambia la geometría del haz y las bombillas solo si están fundidas, que no es el síntoma descrito."},{"id":5443,"bg":"Увеличеният свободен ход на кормилното колело може ли да предизвиква самоволна промяна на посоката на движение на автомобила?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"El juego libre aumentado del volante, ¿puede provocar un cambio involuntario de la dirección de marcha del automóvil?","explain":"Sí: el juego libre excesivo del volante significa holgura en la dirección: el coche puede desviarse sin que hayas girado. Es un defecto que compromete directamente la trayectoria."},{"id":5445,"bg":"Увеличеният свободен ход на кормилното колело при управление на автомобила предизвиква:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"неустойчивост при праволинейно движение на автомобила","ok":true,"i":null,"es":"inestabilidad del automóvil en línea recta"},{"t":"интензивно едностранно износване на гумите на двигателните колела","ok":false,"i":null,"es":"desgaste intenso y unilateral de los neumáticos de las ruedas motrices"},{"t":"трудно завъртане на кормилното колело","ok":false,"i":null,"es":"dificultad para girar el volante"}],"f":4,"es":"El juego libre aumentado del volante, al conducir el automóvil, provoca:","explain":"El juego del volante provoca inestabilidad en LÍNEA RECTA: corriges constantemente porque la dirección responde tarde y de más. No endurece el giro ni desgasta los neumáticos de forma unilateral: esos son otros defectos."},{"id":11657,"bg":"При работа на МПС с двигател с вътрешно горене в затворено помещение най-голяма опасност представляват:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"изгорелите газове от двигателя с вътрешно горене","ok":true,"i":null,"es":"los gases de escape del motor de combustión interna"},{"t":"шумът","ok":false,"i":null,"es":"el ruido"},{"t":"вибрациите","ok":false,"i":null,"es":"las vibraciones"},{"t":"бензиновите изпарения","ok":false,"i":null,"es":"los vapores de gasolina"}],"f":4,"es":"Con un vehículo de motor de combustión interna funcionando en un local cerrado, el mayor peligro son:","explain":"Los GASES DE ESCAPE: el monóxido de carbono es invisible, inodoro y mortal en minutos en un local cerrado. Ruido y vibraciones molestan, los vapores de gasolina son un riesgo menor comparado: el CO mata sin avisar."},{"id":5219,"bg":"Правилата за движение в населено място се прилагат:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"след знака, с който е обозначено началото на населеното място","ok":true,"i":null,"es":"después de la señal que indica el inicio del poblado"},{"t":"от първата сграда в населеното място","ok":false,"i":null,"es":"desde el primer edificio del poblado"},{"t":"по всички участъци от пътя, по които се движат пешеходци","ok":false,"i":null,"es":"en todos los tramos de la vía por los que circulan peatones"}],"f":4,"es":"Las normás de circulación en población se aplican:","explain":"Las normas de población rigen desde la SEÑAL de inicio del poblado (D11), no desde el primer edificio ni por la mera presencia de peatones. La señal es la frontera jurídica exacta."},{"id":5231,"bg":"Тротоарът е част от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътното платно","ok":true,"i":null,"es":"la plataforma vial (calzada + arcenes)"},{"t":"платното за движение","ok":false,"i":null,"es":"la calzada"},{"t":"най-дясната пътна лента","ok":false,"i":null,"es":"el carril más a la derecha"},{"t":"разделителната ивица","ok":false,"i":null,"es":"la franja divisoria (mediana)"}],"f":4,"es":"La acera forma parte de:","explain":"La acera forma parte de la plataforma vial (el conjunto de la vía), pero NO de la calzada: la calzada es solo la parte destinada a los vehículos. Tampoco es un carril ni parte de la mediana."},{"id":5313,"bg":"Видимостта е ограничена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"стръмни наклони","ok":true,"i":null,"es":"pendientes pronunciadas"},{"t":"завои","ok":true,"i":null,"es":"curvas"},{"t":"запрашеност","ok":false,"i":null,"es":"polvo en suspensión"},{"t":"крайпътни обекти, които ограничават видимостта","ok":true,"i":null,"es":"objetos junto a la vía que limitan la visibilidad"}],"f":4,"es":"La visibilidad esta limitada en: (3 correctas)","explain":"Visibilidad limitada: pendientes pronunciadas, curvas y objetos junto a la vía: obstáculos físicos y geométricos. El polvo en suspensión es visibilidad REDUCIDA (condición atmosférica), por eso es la falsa."},{"id":6706,"bg":"Масата с товар на превозното средство:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"включва масата на превозното средство","ok":true,"i":null,"es":"incluye la masa del vehículo"},{"t":"не включва масата на водача","ok":false,"i":null,"es":"no incluye la masa del conductor"},{"t":"не включва масата на пътниците","ok":false,"i":null,"es":"no incluye la masa de los pasajeros"},{"t":"включва масата на товара","ok":true,"i":null,"es":"incluye la masa de la carga"}],"f":4,"es":"La masa con carga del vehículo: (2 correctas)","explain":"La masa con carga incluye: la masa del propio vehículo, la carga, el conductor y los pasajeros: todo lo que pesa rodando. Por eso las dos opciones que excluyen conductor o pasajeros son falsas."},{"id":7879,"bg":"Към МПС от категория В принадлежат автомобили, за превоз на пътници, които, без мястото на водача, имат не повече от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"8 места за сядане","ok":true,"i":null,"es":"8 plazas"},{"t":"6 места за сядане","ok":false,"i":null,"es":"6 plazas"},{"t":"9 места за сядане","ok":false,"i":null,"es":"9 plazas"},{"t":"12 места за сядане","ok":false,"i":null,"es":"12 plazas"}],"f":4,"es":"A la categoría B pertenecen los automóviles de pasajeros que, sin contar al conductor, tienen hasta:","explain":"Categoría B: turismos de hasta 8 plazas sin contar al conductor (8+1). Con 9 o más plazas de pasajeros ya es categoría D."},{"id":8214,"bg":"Извън населените места, при липса на банкет, лицата бутащи мотопед са длъжни да се движат по платното за движение, като:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"се придържат възможно най-близо до дясната му граница","ok":true,"i":null,"es":"pegados todo lo posible al borde DERECHO"},{"t":"се придържат възможно най-близо до лявата му граница","ok":false,"i":null,"es":"pegados todo lo posible al borde IZQUIERDO"}],"f":4,"es":"Fuera de población, sin arcén, las personas empujando un ciclomotor deben circular por la calzada:","explain":"Quien empuja un ciclomotor a pie por la calzada (sin arcén, fuera de población) va pegado al borde DERECHO: se le trata como vehículo, no como peatón (los peatones sí van por la izquierda de frente al tráfico)."},{"id":8230,"bg":"Водач с правоспособност за управление на МПС от категория В1 има право да управлява и:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"мотопед","ok":true,"i":null,"es":"ciclomotor"},{"t":"мотоциклет","ok":false,"i":null,"es":"motocicleta"},{"t":"колесен трактор","ok":false,"i":null,"es":"tractor de ruedas"}],"f":4,"es":"El conductor con permiso de categoría B1 tiene derecho a conducir también:","explain":"El permiso B1 habilita también para conducir ciclomotor (categoría inferior incluida). No incluye motocicleta (requiere A/A1/A2) ni tractor de ruedas (categoría Ткт)."},{"id":11675,"bg":"Мотопедът има двигател с работен обем до 50 cm³ и конструктивна максимална скорост, която не надвишава 45 km/h.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":4,"es":"El ciclomotor tiene un motor con cilindrada de hasta 50 cm3 y velocidad máxima constructiva que no supera los 45 km/h.","explain":"Correcto: la definición legal del ciclomotor es exactamente esa: hasta 50 cm³ de cilindrada Y velocidad máxima constructiva de 45 km/h. Ambos límites a la vez."},{"id":11807,"bg":"Състав от МПС от категория В с допустимата максимална маса над 7000 kg но не повече от 12000 kg е разрешено да се управлява с правоспособност за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"категория С1Е","ok":true,"i":null,"es":"categoría C1E"},{"t":"категория С1","ok":false,"i":null,"es":"categoría C1"},{"t":"категория В","ok":false,"i":null,"es":"categoría B"},{"t":"категория ВЕ","ok":false,"i":null,"es":"categoría BE"}],"f":4,"es":"Un tren de vehículos categoría B con masa máxima admisible entre 7000 y 12000 kg se puede conducir con permiso de:","explain":"C1E: un conjunto de 7.000-12.000 kg supera lo que cubren B (hasta 3.500), BE (turismo+remolque hasta 7.000) y C1 solo (camión rígido 3.500-7.500 sin ese remolque). La combinación pesada exige C1E."},{"id":11810,"bg":"Каква е максималната стойност на масата без товар на автомобилите от категория В1 предназначени за превоз на товари?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"550 kg","ok":true,"i":null,"es":"550 kg"},{"t":"1250 kg","ok":false,"i":null,"es":"1250 kg"},{"t":"750 kg","ok":false,"i":null,"es":"750 kg"},{"t":"400 kg","ok":false,"i":null,"es":"400 kg"}],"f":4,"es":"¿Cuál es la masa máxima en vacio de los automóviles categoría B1 destinados al transporte de mercancias?","explain":"550 kg: es la masa máxima EN VACÍO de los B1 destinados a mercancías (cuadriciclos pesados de carga). Para los de pasajeros el límite en vacío es distinto (400 kg): ojo al matiz 'mercancías'."},{"id":11848,"bg":"Двигателят на мотопеда е с работен обем до:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"50 cm³","ok":true,"i":null,"es":"50 cm³"},{"t":"30 cm³","ok":false,"i":null,"es":"30 cm³"},{"t":"75 cm³","ok":false,"i":null,"es":"75 cm³"},{"t":"125 cm³","ok":false,"i":null,"es":"125 cm³"}],"f":4,"es":"El motor del ciclomotor tiene una cilindrada de hasta:","explain":"50 cm³: el límite de cilindrada que define al ciclomotor. 75 o 125 cm³ ya son motocicletas ligeras (A1)."},{"id":5159,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19734.png","v":null,"a":[{"t":"път с предимство","ok":true,"i":null,"es":"vía con prioridad"},{"t":"премини, ако пътят е свободен","ok":false,"i":null,"es":"pasa si la vía está libre"},{"t":"пропусни насрещно движещите се ППС","ok":false,"i":null,"es":"cede el paso a los vehículos que vienen de frente"},{"t":"внимание, кръстовище","ok":false,"i":null,"es":"atención, intersección"}],"f":4,"es":"El significado de esta señal es:","explain":"VÍA CON PRIORIDAD — «път с предимство».\n\nLA SEÑAL. Rombo amarillo con borde blanco. Es la única señal con esa forma en todo el código búlgaro, y esa exclusividad es intencionada: se reconoce de espaldas, de lado y con niebla.\n\nQUÉ TE DA. Preferencia sobre todos los que llegan por las vías que cruzan la tuya, hasta que aparezca el rombo tachado — fin de vía con prioridad — o hasta que una tabla indique que la preferente cambia de dirección.\n\n«PASA SI LA VÍA ESTÁ LIBRE» describe el ceda el paso, triángulo invertido: allí no tienes prioridad, la cedes.\n\n«CEDE EL PASO A LOS QUE VIENEN DE FRENTE» no es ninguna señal: es la regla del чл. 37, que se aplica cuando giras a la izquierda y que el rombo NO anula.\n\n«ATENCIÓN, INTERSECCIÓN» es un triángulo de peligro: avisa de que viene un cruce, sin decir quién manda.\n\nCLAVE: el rombo resuelve el cruce con las vías laterales, no con quien viene de frente por tu misma vía. Es la confusión de la pregunta 6525.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5165,"bg":"При тази ситуация пътният знак сигнализира, че:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20260.png","v":null,"a":[{"t":"за използването на пътя се изисква платена винетна такса","ok":true,"i":null,"es":"para usar la vía se exige el pago de viñeta"},{"t":"маркировката, която отделя пътните ленти е разрешена за пресичане","ok":false,"i":null,"es":"la marca vial que separa los carriles se puede cruzar"},{"t":"и двете пътни ленти са предназначени за движение в една посока","ok":false,"i":null,"es":"ambos carriles están destinados a la circulación en un mismo sentido"}],"f":4,"es":"En esta situación la señal indica que:","explain":"Se requiere pago de vineta para usar esa via. La vineta es obligatoria en autopistas y vias rapidas de Bulgaria."},{"id":5171,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334666.png","v":null,"a":[{"t":"последователни опасни завои, първият от които е надясно","ok":true,"i":null,"es":"curvas peligrosas sucesivas, la primera hacia la derecha"},{"t":"последователност от стръмни изкачвания и спускания","ok":false,"i":null,"es":"una sucesión de subidas y bajadas pronunciadas"},{"t":"опасност от хлъзгане","ok":false,"i":null,"es":"peligro de deslizamiento"},{"t":"препятствие, което трябва да бъде заобиколено отдясно","ok":false,"i":null,"es":"obstáculo que debe rodearse por la derecha"}],"f":4,"es":"Esta señal advierte de:","explain":"Advierte de CURVAS SUCESIVAS, la primera de ellas HACIA LA DERECHA.\n\nLA SEÑAL. Triángulo rojo con el trazo en forma de S. Lo que decide la respuesta es hacia dónde se dobla el trazo ABAJO, porque abajo está el punto por donde tú vas a entrar. Aquí la parte inferior gira a la derecha.\n\nCÓMO LEERLA SIN DUDAR. Sigue el trazo desde abajo hacia arriba, como si condujeras el dibujo. La primera curva que encuentras es la que la señal nombra.\n\nQUÉ CAMBIA RESPECTO A UNA CURVA SUELTA. Con curvas encadenadas no hay recta entre ellas para corregir: entras a una velocidad que te sirva para TODAS, no solo para la primera. Y adelantar dentro del tramo es especialmente malo, porque la visibilidad se cierra en cada cambio de sentido.\n\n«SUBIDAS Y BAJADAS PRONUNCIADAS» tiene su propio dibujo, con perfil de montaña.\n\n«PELIGRO DE DESLIZAMIENTO» es el coche con las trazas de derrape.\n\n«OBSTÁCULO QUE DEBE RODEARSE POR LA DERECHA» sería un círculo azul con flecha: obligación, no peligro.\n\nCLAVE: en las señales de curvas, lee el trazo de abajo arriba. La parte de abajo eres tú.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5187,"bg":"Как се променя устойчивостта на превозното средство, когато при навлизане в завой се увеличава скоростта?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"влошава се","ok":true,"i":null,"es":"empeora"},{"t":"подобрява се","ok":false,"i":null,"es":"mejora"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"}],"f":4,"es":"¿Cómo cambia la estabilidad del vehículo cuando al entrar en una curva se aumenta la velocidad?","explain":"Empeora: más velocidad en la misma curva significa más fuerza centrífuga (crece con el cuadrado de la velocidad). Por eso se frena ANTES de la curva, nunca dentro."},{"id":5192,"bg":"При движение в завой радиусът на завоя оказва ли влияние на устойчивостта на превозното средство?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"Al circular en curva, ¿el radio de la curva influye en la estabilidad del vehículo?","explain":"Sí: a menor radio (curva más cerrada), mayor fuerza lateral a igual velocidad y menor estabilidad. Radio y velocidad son las dos variables de la física de la curva."},{"id":5210,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22999.png","v":null,"a":[{"t":"че следва участък от пътя с концентрация на произшествия","ok":true,"i":null,"es":"que sigue un tramo de vía con concentración de accidentes"},{"t":"че пътят навлиза в тунел","ok":false,"i":null,"es":"que la vía entra en un túnel"},{"t":"за опасност от паднали камъни на пътя","ok":false,"i":null,"es":"del peligro de piedras caídas en la vía"},{"t":"участък от пътя в ремонт","ok":false,"i":null,"es":"un tramo en obras"}],"f":4,"es":"Esta señal señaliza:","explain":"Tramo con concentracion de accidentes (punto negro). El fondo amarillo-verde indica zona de alta siniestralidad."},{"id":5215,"bg":"Този знак предупреждава за възможна опасност от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334749.png","v":null,"a":[{"t":"работещи хора на платното за движение или в обхвата на пътя","ok":true,"i":null,"es":"trabajadores en la calzada o sus alrededores"},{"t":"строителни машини на платното за движение","ok":true,"i":null,"es":"maquinaria de construcción en la calzada"},{"t":"неравности по платното за движение","ok":true,"i":null,"es":"irregularidades en el pavimento"},{"t":"играещи деца на платното за движение","ok":false,"i":null,"es":"niños jugando en la calzada"}],"f":4,"es":"Esta señal advierte del peligro de: (3 correctas)"},{"id":5227,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334749.png","v":null,"a":[{"t":"предупреждава, че следва участък от пътя в ремонт","ok":true,"i":null,"es":"advierte de que sigue un tramo de vía en obras"},{"t":"забранява извършването на ремонтни работи по пътя","ok":false,"i":null,"es":"prohíbe realizar obras de reparación en la vía"},{"t":"указва място за извършване на товарно-разтоварна дейност на пътя","ok":false,"i":null,"es":"indica un lugar para operaciones de carga y descarga en la vía"},{"t":"сигнализира, че пътният участък е с концентрация на произшествия","ok":false,"i":null,"es":"señaliza que el tramo tiene concentración de accidentes"}],"f":4,"es":"Esta señal:","explain":"Obras en la calzada = trabajadores y maquinaria. Reduce velocidad y aumenta la atencion."},{"id":5278,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334677.png","v":null,"a":[{"t":"предупреждава водачите за приближаване към пешеходна пътека","ok":true,"i":null,"es":"advierte a los conductores de la proximidad de un paso de peatones"},{"t":"обозначава точното място на пешеходна пътека","ok":false,"i":null,"es":"indica el lugar exacto de un paso de peatones"},{"t":"указва началото на път само пешеходци","ok":false,"i":null,"es":"indica el inicio de una vía solo para peatones"},{"t":"предупреждава за кръстовище с интензивно преминаване на пешеходци","ok":false,"i":null,"es":"advierte de una intersección con paso intenso de peatones"}],"f":4,"es":"Esta señal:","explain":"Advierte a los conductores de la PROXIMIDAD de un paso de peatones.\n\nLA SEÑAL. Triángulo rojo con un peatón cruzando sobre la cebra.\n\nEL PAR QUE HAY QUE TENER CLARO. Existen dos señales de paso de peatones con el mismo dibujo y funciones distintas: el TRIÁNGULO ROJO — esta — avisa con antelación de que te acercas a uno; el CUADRADO AZUL marca dónde está exactamente. Una prepara, la otra localiza.\n\n«INDICA EL LUGAR EXACTO DE UN PASO» es por tanto el distractor central y describe la azul, que es la pregunta 5283.\n\nPOR QUÉ EXISTEN LAS DOS. En una vía rápida o con visibilidad limitada, saber dónde está el paso cuando ya lo tienes encima llega tarde. El triángulo te da margen para levantar el pie.\n\n«INICIO DE VÍA SOLO PARA PEATONES» sería un círculo azul: obligación.\n\n«INTERSECCIÓN CON PASO INTENSO DE PEATONES» no existe con este pictograma.\n\nCLAVE: triángulo rojo = «viene un paso». Cuadrado azul = «el paso es aquí». Mismo dibujo, distinta forma, distinta función.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5285,"bg":"Този пътен знак предупреждава за приближаване към:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334679.png","v":null,"a":[{"t":"железопътен прелез без бариери","ok":true,"i":null,"es":"paso a nivel SIN barreras"},{"t":"железопътен надлез","ok":false,"i":null,"es":"paso elevado sobre la vía ferroviaria"},{"t":"железопътна гара","ok":false,"i":null,"es":"estación de ferrocarril"},{"t":"железопътен прелез с автоматични бариери","ok":false,"i":null,"es":"paso a nivel CON barreras automáticas"}],"f":4,"es":"Esta señal advierte de la proximidad de:"},{"id":5294,"bg":"На показаната схема с буква „а” е означен пътният знак, който сигнарлизира, че разстоянието до железопътния прелез е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27687.png","v":null,"a":[{"t":"80 м","ok":true,"i":null,"es":"80 m"},{"t":"160 м","ok":false,"i":null,"es":"160 m"},{"t":"240 м","ok":false,"i":null,"es":"240 m"}],"f":4,"es":"En el esquema mostrado, la letra 'а' indica la señal que señaliza que la distancia al paso a nivel es:","explain":"80 metros.\n\nQUÉ VES. Tres balizas escalonadas junto a la carretera, camino de un paso a nivel, etiquetadas «а», «б» y «в». La letra «а» señala la más próxima al paso, la de UNA franja roja.\n\nLA REGLA ES ARITMÉTICA: cada franja son 80 metros. Tres franjas, 240 m. Dos franjas, 160 m. Una franja, 80 m. Las franjas van DESAPARECIENDO conforme te acercas: es una cuenta atrás.\n\nPOR QUÉ SE DISEÑÓ ASÍ. Sin saberte ninguna tabla, la cantidad de rojo que ves te dice cuánto te queda. Menos franjas, menos distancia — el aviso se vuelve más urgente justo cuando importa.\n\nFÍJATE EN QUÉ BALIZA LLEVA LA SEÑAL DE PELIGRO ENCIMA: la primera que encuentras, la de tres franjas. El triángulo con la locomotora avisa a 240 m; las otras dos solo cuentan.\n\nY OJO A LA LOCOMOTORA. El triángulo con locomotora de vapor significa paso a nivel SIN barreras; con barreras se dibuja una valla. Son dos señales distintas y la diferencia importa: sin barreras, la única protección eres tú.\n\nCLAVE: cuenta las franjas y multiplica por 80. Es la pregunta más mecánica del bloque de señales.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5295,"bg":"На показаната схема с буква „б” е означен пътният знак, който сигнарлизира, че разстоянието до железопътния прелез е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27724.png","v":null,"a":[{"t":"80 м","ok":false,"i":null,"es":"80 m"},{"t":"160 м","ok":true,"i":null,"es":"160 m"},{"t":"240 м","ok":false,"i":null,"es":"240 m"}],"f":4,"es":"En el esquema mostrado, la letra 'б' indica la señal que señaliza que la distancia al paso a nivel es:","explain":"160 metros.\n\nES LA GEMELA DE LA 5294 sobre el mismo esquema. Allí se preguntaba por la letra «а», la baliza de una franja; aquí por la «б», la del medio, que lleva DOS franjas.\n\nDOS FRANJAS × 80 METROS = 160 METROS. Sin más.\n\nEL ORDEN COMPLETO, tal como lo encuentras conduciendo: primero la de TRES franjas a 240 m, que es la que lleva encima el triángulo de peligro; después la de DOS a 160 m; y por último la de UNA a 80 m, ya pegada al paso.\n\nEL ERROR TÍPICO es contar al revés y asignar tres franjas a la más cercana. Piénsalo como una cuenta atrás: las franjas se van gastando conforme te aproximas.\n\nY RECUERDA QUÉ HACER EN EL PASO A NIVEL: no entrar si no puedes despejarlo del todo, no adelantar, no cambiar de marcha encima de los raíles y, si el vehículo se queda parado, sacar a los ocupantes y avisar.\n\nCLAVE: tres franjas 240, dos 160, una 80. Y la señal de peligro va siempre en la primera, la más lejana.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":11603,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123578342.png","v":null,"a":[{"t":"място за паркиране на електрически превозни средства за зареждане","ok":true,"i":null,"es":"lugar de estacionamiento para la recarga de vehículos eléctricos"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"забрана за престой и паркиране","ok":false,"i":null,"es":"prohibición de parada y estacionamiento"}],"f":4,"es":"Esta señal señaliza:","explain":"Señaliza un LUGAR DE ESTACIONAMIENTO PARA LA RECARGA DE VEHÍCULOS ELÉCTRICOS.\n\nLA SEÑAL. Rectángulo azul con un recuadro blanco dentro, un coche verde y un enchufe. Azul rectangular es información o servicio; el verde y el enchufe identifican el punto de recarga.\n\nQUÉ IMPLICA. Esa plaza está reservada a vehículos eléctricos que estén recargando. Aparcar ahí un vehículo de combustión, o uno eléctrico sin enchufar, es ocupar indebidamente una plaza reservada.\n\n«VÍA RÁPIDA» — автомобилен път — es azul, sí, pero su dibujo es una calzada con separación central, no un coche enchufado. El color coincide y el pictograma no.\n\n«PROHIBICIÓN DE PARADA Y ESTACIONAMIENTO» sería un círculo con borde rojo y dos barras cruzadas. La forma ya la descarta: los rectángulos no prohíben.\n\nES UNA SEÑAL RECIENTE, incorporada al código con la expansión del vehículo eléctrico. Aparece poco en el banco pero es de las que se responden rápido si tienes clara la regla de las formas.\n\nCLAVE: rectángulo = informa. Círculo = manda o prohíbe. Triángulo = avisa. Con eso descartas tres de las cuatro opciones antes de mirar el dibujo.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5759,"bg":"Кое от следващите действия трябва да предприемете при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23996.png","v":null,"a":[{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"да управлявам с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да осигуря достатъчна странична дистанция","ok":true,"i":null,"es":"garantizar distancia lateral suficiente"},{"t":"да подам звуков сигнал","ok":false,"i":null,"es":"tocar el claxon"}],"f":4,"es":"¿Cuál de las siguientes acciones debes tomar en esta situación? (3 correctas)","explain":"Con ciclistas: reduce velocidad, disposicion de frenar, y distancia lateral suficiente. NO el claxon."},{"id":5848,"bg":"Как трябва да постъпите при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25781.png","v":null,"a":[{"t":"трябва да пропусна пешеходеца","ok":true,"i":null,"es":"debo dejar pasar al peatón"},{"t":"мога да премина защото пешеходецът не е достигнал средата на платното за движение","ok":false,"i":null,"es":"puedo pasar porque el peatón no ha alcanzado el centro de la calzada"},{"t":"мога да премина защото пешеходецът е в съседната пътна лента","ok":false,"i":null,"es":"puedo pasar porque el peatón está en el carril contiguo"}],"f":4,"es":"¿Cómo debes actuar en esta situación?","explain":"Cedes al peaton. Aunque no haya llegado a la mitad de la calzada o este en otro carril, debes ceder en paso de peatones."},{"id":5851,"bg":"Има ли опасност при тази ситуация, когато детето е на тротоара?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25831.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"¿Hay peligro en esta situación cuando el niño está en la acera?","explain":"SI. Los ninos pueden bajar de la acera sin avisar. Siempre peligro potencial con ninos cerca de la calzada."},{"id":6041,"bg":"Кратковременното превключване на светлините като допълнителен сигнал при извършване на маневра е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"забранено да се използва при движение в населени места","ok":false,"i":null,"es":"PROHIBIDO en zona urbana"},{"t":"разрешено да се използва при движение извън населени места","ok":true,"i":null,"es":"PERMITIDO fuera de zona urbana"},{"t":"разрешено да се използва при движение по автомобилни пътища","ok":true,"i":null,"es":"PERMITIDO en vías rápidas"},{"t":"забранено да се използва при движение по автомагистрали","ok":false,"i":null,"es":"PROHIBIDO en autopistas"}],"f":4,"es":"El parpadeo de luces como señal adicional de maniobra está: (2 correctas)","explain":"El parpadeo de luces como señal adicional está permitido FUERA de zona urbana y en vías rápidas/autopistas (avisar de adelantamiento). En ciudad su uso como aviso está restringido."},{"id":6065,"bg":"Как трябва да постъпи водачът на превозно средство при подаден сигнал с показаната палка?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40108.png","v":null,"a":[{"t":"да спре","ok":true,"i":null,"es":"detenerse"},{"t":"да продължи движението, но с намалена скорост","ok":false,"i":null,"es":"continuar la marcha, pero a velocidad reducida"},{"t":"не е задължен да се съобразява с този сигнал","ok":false,"i":null,"es":"no está obligado a obedecer esta señal"},{"t":"да подаде авариен сигнал","ok":false,"i":null,"es":"encender las luces de emergencia"}],"f":4,"es":"¿Cómo debe actuar el conductor cuando se le da la señal con la paleta mostrada?","explain":"Parar. La paleta roja de STOP de los agentes de trafico es de obligado cumplimiento inmediato."},{"id":6693,"bg":"Има ли опасност при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25901.png","v":null,"a":[{"t":"да, защото детето не гледа към мен","ok":true,"i":null,"es":"sí, porque el niño no mira hacia mí"},{"t":"да, защото детето може да навлезе внезапно на платното за движение","ok":true,"i":null,"es":"sí, porque el niño puede entrar repentinamente en la calzada"},{"t":"не, защото детето не гледа към мен и няма да навлиза на платното за движение","ok":false,"i":null,"es":"no, porque el niño no mira hacia mí y no va a entrar en la calzada"},{"t":"не, защото детето е на тротоара","ok":false,"i":null,"es":"no, porque el niño está en la acera"}],"f":4,"es":"¿Hay peligro en esta situación? (2 correctas)","explain":"SI, doble peligro: el nino no mira hacia ti Y puede entrar en la calzada sin avisar. Los dos motivos son validos."},{"id":9851,"bg":"При тази ситуация, когато сигналът на регулировчика разрешава на водача на автомобила да премине, той задължен ли е да се съобразява с пешеходците?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044320.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"En esta situación, cuando la señal del agente permite pasar al conductor, ¿está obligado a tener en cuenta a los peatones?","explain":"SI siempre. Aunque el agente te de paso, si hay peatones cruzando debes cederles."},{"id":9853,"bg":"При тази ситуация пешеходецът е с предимство.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044419.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":4,"es":"En esta situación el peatón tiene prioridad. Esto es:","explain":"CORRECTO: el peatón tiene prioridad.\n\nQUÉ VES. Un peatón cruzando por un paso señalizado y tu coche aproximándose.\n\nLA REGLA. En un paso de peatones, el conductor de un vehículo no ferroviario está obligado a ceder el paso a los peatones que ya están cruzando o que van a hacerlo. No es cortesía: es obligación.\n\nQUÉ SIGNIFICA CEDER AQUÍ. No basta con frenar un poco. Significa no obligar al peatón a detenerse, a acelerar el paso ni a cambiar su trayectoria. Si tiene que apurar por ti, no le has cedido.\n\nY SI HAY VARIOS CARRILES, la obligación es de cada conductor por separado. Que el coche del carril de al lado no pare no te autoriza a pasar; al contrario, un vehículo detenido junto a un paso es motivo para extremar la precaución, porque tapa la visión.\n\nCLAVE: en las preguntas de peatones la respuesta casi siempre es que el peatón está protegido. Los distractores intentan condicionar esa protección a que el paso esté pintado o señalizado, y eso es justo lo que la ley no exige.\n\nMÉTODO CON PEATONES: la protección no depende de que el paso esté pintado ni de que haya señal. Depende de que el peatón esté cruzando donde tiene derecho. Desarrollado en Leyes → «Peatones: cuándo hay que cederles el paso»."},{"id":11867,"bg":"Този знак забранява влизането на:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828538.png","v":null,"a":[{"t":"ППС, обозначени с опознавателен знак за опасен товар","ok":true,"i":null,"es":"vehículos señalizados con el distintivo de mercancías peligrosas"},{"t":"извънгабаритни ППС","ok":false,"i":null,"es":"vehículos de dimensiones excepcionales"},{"t":"товарни автомобили с полуремаркета","ok":false,"i":null,"es":"camiones con semirremolques"},{"t":"товарни автомобили с обща маса над 15 t","ok":false,"i":null,"es":"camiones de masa total superior a 15 t"}],"f":4,"es":"Esta señal prohíbe la entrada a:","explain":"Vehiculos con mercancias peligrosas (senalizacion ADR/naranja). Los demas vehiculos pueden pasar."},{"id":5955,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42601.png","v":null,"a":[{"t":"място на пътя, където движението се регулира със светлинни сигнали","ok":true,"i":null,"es":"lugar de la vía donde el tráfico se regula con señales luminosas"},{"t":"кръстовище, на което светофарите са изключени или повредени","ok":false,"i":null,"es":"intersección con los semáforos apagados o averiados"},{"t":"кръстовище, на което се пресичат равнозначни пътища","ok":false,"i":null,"es":"intersección donde se cruzan vías de igual rango"},{"t":"железопътен прелез със светофарно регулиране","ok":false,"i":null,"es":"paso a nivel regulado por semáforos"}],"f":4,"es":"Esta señal advierte de:","explain":"Advierte de un LUGAR DE LA VÍA DONDE EL TRÁFICO SE REGULA CON SEÑALES LUMINOSAS.\n\nLA SEÑAL. Triángulo rojo con un semáforo de tres focos dibujado dentro, con sus colores.\n\nQUÉ TE PIDE. Prepararte para encontrar un semáforo que quizá no se ve desde lejos — una curva, un cambio de rasante, un tramo de obras con paso alternativo. Es un aviso de anticipación, no una orden.\n\n«INTERSECCIÓN CON LOS SEMÁFOROS APAGADOS O AVERIADOS» es el distractor con más gancho, porque parece razonable que exista una señal para eso. No existe: cuando un semáforo se apaga, lo que rige son las señales verticales y, si tampoco las hay, la regla de la derecha. Ninguna señal anuncia una avería.\n\n«INTERSECCIÓN DE VÍAS DE IGUAL RANGO» es el triángulo del aspa.\n\n«PASO A NIVEL CON SEMÁFOROS» tiene su propio pictograma, con la locomotora o la valla.\n\nCLAVE: el semáforo dibujado dentro de un triángulo anuncia que HAY semáforo más adelante. Nunca informa de su estado — para eso ya está el propio semáforo cuando llegues.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5956,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42635.png","v":null,"a":[{"t":"предупреждава за възможна поява на силен страничен вятър","ok":true,"i":null,"es":"advierte de la posible aparición de viento lateral fuerte"},{"t":"обозначава район на летище","ok":false,"i":null,"es":"indica la zona de un aeropuerto"},{"t":"предупреждава за нисколетящи самолети","ok":false,"i":null,"es":"advierte de aviones volando bajo"},{"t":"сигнализира място за отдих","ok":false,"i":null,"es":"señaliza un área de descanso"}],"f":4,"es":"Esta señal:","explain":"Advertencia de viento lateral fuerte. Especialmente peligroso para vehiculos altos (camiones, furgonetas)."},{"id":5965,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334703.png","v":null,"a":[{"t":"леки автомоби","ok":true,"i":null,"es":"turismos"},{"t":"автомобили със специален режим на движение","ok":false,"i":null,"es":"automóviles con régimen especial de circulación"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"}],"f":4,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (3 correctas)","explain":"Prohibido: turismos, tractores y bicicletas. Permitido: vehiculos de emergencia y transporte publico."},{"id":5971,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334704.png","v":null,"a":[{"t":"автобуси","ok":true,"i":null,"es":"autobuses"},{"t":"ППС теглени от животни","ok":true,"i":null,"es":"vehículos de tracción animal"},{"t":"автомобили със специален режим на движение","ok":false,"i":null,"es":"automóviles con régimen especial de circulación"},{"t":"превозни средства от редовните линии за обществен превоз на пътници","ok":false,"i":null,"es":"vehículos de líneas regulares de transporte público"}],"f":4,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (2 correctas)","explain":"Prohibido: autobuses y vehiculos de traccion animal. Permitido: lineas regulares de transporte publico."},{"id":5972,"bg":"Този пътен знак означава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48955.png","v":null,"a":[{"t":"че е забранено завиването в обратна посока","ok":true,"i":null,"es":"que está prohibido el cambio de sentido"},{"t":"че е забранено движението назад","ok":false,"i":null,"es":"que está prohibida la marcha atrás"},{"t":"край на ограничението за завиване в обратна посока","ok":false,"i":null,"es":"fin de la restricción de cambio de sentido"}],"f":4,"es":"Esta señal significa:","explain":"Prohibido girar en sentido contrario (media vuelta). No prohibe la marcha atras."},{"id":5974,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334705.png","v":null,"a":[{"t":"леки автомобили","ok":true,"i":null,"es":"turismos"},{"t":"товарни автомобили","ok":true,"i":null,"es":"camiones"},{"t":"мотопеди","ok":false,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"}],"f":4,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (3 correctas)","explain":"Prohibido: turismos, camiones y tractores. Permitido: ciclomotores y vehiculos de emergencia."},{"id":5981,"bg":"Този пътен знак не забранява влизането на:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334708.png","v":null,"a":[{"t":"автомобил, теглещ едноосно ремарке","ok":true,"i":null,"es":"automóvil que remolca un remolque de un eje"},{"t":"автомобил с полуремарке","ok":true,"i":null,"es":"automóvil con semirremolque"},{"t":"автомобил, теглещ ремарке с две и повече оси","ok":false,"i":null,"es":"automóvil que remolca un remolque de dos o más ejes"}],"f":4,"es":"Esta señal NO prohíbe la entrada a: (2 correctas)","explain":"Permite el paso de: coche con remolque de un eje y coche con semirremolque. Prohibe: coche con remolque de 2+ ejes."},{"id":6170,"bg":"На кои от изброените превозни средства е забранено да навлизат след този пътен знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52083.png","v":null,"a":[{"t":"автобуси","ok":true,"i":null,"es":"autobuses"},{"t":"автомобили с ремаркета","ok":true,"i":null,"es":"automóviles con remolque"},{"t":"автомобили с полуремаркета","ok":true,"i":null,"es":"automóviles con semirremolques"},{"t":"товарни автомобили","ok":false,"i":null,"es":"camiones"}],"f":4,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (3 correctas)","explain":"Prohibido: autobuses, coches con remolques y coches con semirremolques. Los camiones solos pueden pasar."},{"id":6173,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334710.png","v":null,"a":[{"t":"„Забранено е влизането на ППС с натоварване, на която и да е от осите, по-голямо от означеното”","ok":true,"i":null,"es":"\"Prohibida la entrada de vehículos con carga por eje superior a la indicada\""},{"t":"„Забранено е влизането на ППС с маса с товар, по-голяма от означената”","ok":false,"i":null,"es":"\"Prohibida la entrada de vehículos cuya masa con carga supere la indicada\""},{"t":"„Забранено е влизането на ППС с товар, по-голям от означения”","ok":false,"i":null,"es":"\"Prohibida la entrada de vehículos con carga superior a la indicada\""},{"t":"„Забранено е влизането на ППС с товароносимост, по-голяма от означената”","ok":false,"i":null,"es":"\"Prohibida la entrada de vehículos con capacidad de carga superior a la indicada\""}],"f":4,"es":"El significado de esta señal es:","explain":"Prohibida la entrada de vehiculos cuya carga por eje supere la indicada. Diferente de la masa total y la carga total."},{"id":6179,"bg":"След този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53277.png","v":null,"a":[{"t":"забранено влизането на ППС с дължината по-голяма от означената","ok":true,"i":null,"es":"prohibida la entrada de vehículos con longitud superior a la indicada"},{"t":"разрешено влизането за ППС, на които товарът е с дължина по-голяма от означената","ok":false,"i":null,"es":"permitida la entrada si solo la carga supera la longitud"},{"t":"забранено влизането за ППС, на които дължината заедно с товара е по-голяма от означената","ok":true,"i":null,"es":"prohibida la entrada de vehículos cuya longitud con carga supere la indicada"}],"f":4,"es":"Después de esta señal está: (2 correctas)"},{"id":6180,"bg":"Този пътен знак забранява влизането на ППС:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53311.png","v":null,"a":[{"t":"с дължина, включително и товара, по-голяма от означената","ok":true,"i":null,"es":"con longitud, incluyendo carga, superior a la indicada"},{"t":"движещи се едно зад друго, на разстояние по-малко от означеното","ok":false,"i":null,"es":"que circulan en convoy a menos de la distancia indicada"},{"t":"с широчина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con anchura, incluyendo carga, superior a la indicada"}],"f":4,"es":"Esta señal prohíbe la entrada de vehículos:"},{"id":6188,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334695.png","v":null,"a":[{"t":"задължава водачите да завиват само надясно след знака","ok":true,"i":null,"es":"obliga a los conductores a girar solo a la derecha después de la señal"},{"t":"препоръчва на водачите да завиват надясно","ok":false,"i":null,"es":"recomienda a los conductores girar a la derecha"},{"t":"указва посоката на предимството в кръстовището","ok":false,"i":null,"es":"indica la dirección de la prioridad en la intersección"},{"t":"предупреждава, че пътят завива надясно","ok":false,"i":null,"es":"advierte de que la vía gira a la derecha"}],"f":4,"es":"Esta señal:","explain":"OBLIGA a los conductores a girar solo a la derecha después de la señal.\n\nLA SEÑAL. Círculo AZUL con una flecha blanca doblada hacia la derecha. Azul es siempre obligación en el código búlgaro.\n\nQUÉ IMPONE. Después de la señal, la única trayectoria permitida es girar a la derecha. No es una sugerencia ni una recomendación: seguir recto o girar a la izquierda es infracción, aunque no haya nadie y la maniobra sea cómoda.\n\n«RECOMIENDA GIRAR A LA DERECHA» es el distractor central y confunde obligación con consejo. En el código búlgaro no hay señales de recomendación con forma de círculo azul; las recomendaciones son rectangulares.\n\n«INDICA LA DIRECCIÓN DE LA PRIORIDAD EN LA INTERSECCIÓN» describe la tabla blanca que cuelga bajo el rombo amarillo.\n\n«ADVIERTE DE QUE LA VÍA GIRA A LA DERECHA» sería el triángulo rojo de curva peligrosa: mismo giro, otra forma, otra cosa. Uno avisa de cómo es la carretera, el otro te ordena por dónde ir.\n\nCLAVE: es el trío completo del mismo giro en tres formas. Triángulo rojo = la vía gira. Círculo azul = tú giras, obligatoriamente. Rombo con tabla = la prioridad gira.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6211,"bg":"За какво сигнализира този пътен знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334702.png","v":null,"a":[{"t":"начало на пътна лента","ok":true,"i":null,"es":"inicio de un carril"},{"t":"пътна лента за принудително спиране","ok":false,"i":null,"es":"carril de parada de emergencia"},{"t":"допълнителна пътна лента за бавнодвижещи се ППС","ok":false,"i":null,"es":"carril adicional para vehículos lentos"},{"t":"пътна лента за завиване надясно","ok":false,"i":null,"es":"carril para girar a la derecha"}],"f":4,"es":"¿Qué señaliza esta señal?","explain":"Señaliza el INICIO DE UN CARRIL.\n\nLA SEÑAL. Cuadrado azul con tres flechas hacia arriba; una de ellas nace por la derecha e se incorpora a las otras dos. Azul cuadrado es información: describe la vía, no ordena nada.\n\nQUÉ TE DICE. Que a partir de ahí la calzada gana un carril por la derecha. Es información útil para planificar: si vas a girar pronto o quieres dejar paso, sabes que va a haber sitio.\n\n«CARRIL DE PARADA DE EMERGENCIA» tiene su propio dibujo y su propio uso, en descensos largos para vehículos sin frenos.\n\n«CARRIL ADICIONAL PARA VEHÍCULOS LENTOS» es el distractor más fino, porque también dibuja un carril que aparece. Se distingue porque el de lentos lleva el círculo con la velocidad — el «30» de la pregunta 11683 — y este no lleva ninguna cifra. Sin cifra, es un carril normal para todos.\n\n«CARRIL PARA GIRAR A LA DERECHA» dibuja la flecha doblándose, no incorporándose.\n\nCLAVE: en los paneles de carriles, mira si hay una CIFRA dentro. Con cifra el carril está reservado a los lentos; sin cifra es un carril más, abierto a todos.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6218,"bg":"С допълнителната табела към този пътен знак се указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53812.png","v":null,"a":[{"t":"разстоянието до стеснения участък от платното за движение","ok":true,"i":null,"es":"la DISTANCIA hasta el tramo estrecho"},{"t":"дължината на стеснения участък от платното за движение","ok":false,"i":null,"es":"la LONGITUD del tramo estrecho"},{"t":"разстоянието до края на стеснения участък от платното за движение","ok":false,"i":null,"es":"la distancia hasta el FINAL del tramo estrecho"}],"f":4,"es":"La tablilla complementaria junto a esta señal indica:"},{"id":6249,"bg":"При тази допълнителна табела разрешено ли е водачите на леки автомобили да завиват надясно след знака?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54256.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"Con esta tablilla adicional, ¿está permitido a los conductores de turismos girar a la derecha después de la señal?","explain":"SI, la tablilla excluye a los turismos de la prohibicion. Solo afecta a los vehiculos senalados en la tablilla."},{"id":6253,"bg":"Забраната, въведена с този пътен знак с допълнителна табела, отнася ли се за водачите на автобуси?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54388.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":4,"es":"¿La prohibición de esta señal con tablilla adicional afecta a los conductores de autobuses?","explain":"NO, la tablilla excluye expresamente a los autobuses de la prohibicion."},{"id":6257,"bg":"Забраната, въведена с този пътен знак с допълнителна табела, се отнася за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54388.png","v":null,"a":[{"t":"леките автомобили","ok":true,"i":null,"es":"los turismos"},{"t":"товарните автомобили","ok":true,"i":null,"es":"los camiones"},{"t":"мотоциклетите","ok":true,"i":null,"es":"las motocicletas"},{"t":"автобусите","ok":false,"i":null,"es":"los autobuses"}],"f":4,"es":"La prohibición de esta señal con tablilla adicional se refiere a: (3 correctas)","explain":"Afecta a: turismos, camiones y motocicletas. Los autobuses quedan excluidos por la tablilla."},{"id":6272,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54849.png","v":null,"a":[{"t":"начало на участъка, в който е забранено паркирането","ok":true,"i":null,"es":"INICIO del tramo donde está prohibido aparcar"},{"t":"край на участъка, в който е забранено паркирането","ok":false,"i":null,"es":"FIN del tramo donde está prohibido aparcar"}],"f":4,"es":"La tablilla complementaria junto a la señal indica:"},{"id":6295,"bg":"Забраната, въведена с този пътен знак, е валидна:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334715.png","v":null,"a":[{"t":"до следващото кръстовище","ok":true,"i":null,"es":"hasta la próxima intersección"},{"t":"до знак, който отменя забраната","ok":true,"i":null,"es":"hasta la señal que cancela la prohibición"},{"t":"до края на пътя","ok":false,"i":null,"es":"hasta el final de la vía"},{"t":"на 150 м след знака","ok":false,"i":null,"es":"a 150 m después de la señal"}],"f":4,"es":"La prohibición de esta señal es válida: (2 correctas)","explain":"Dos: hasta la próxima intersección, y hasta la señal que cancela la prohibición.\n\nLA SEÑAL. Círculo rojo con dos coches: prohibido adelantar a los vehículos de motor.\n\nDÓNDE ACABA UNA PROHIBICIÓN. Por defecto, en la siguiente intersección: los cruces reinician la señalización, porque quien entra por la vía lateral no ha visto la señal. Y antes de eso puede terminar si aparece la señal de fin de prohibición, con la cifra o el dibujo tachados por barras diagonales.\n\n«HASTA EL FINAL DE LA VÍA» es el distractor de la exageración: ninguna prohibición se extiende indefinidamente sin repetirse.\n\n«A 150 m DESPUÉS DE LA SEÑAL» inventa una distancia. Las distancias solo cuentan cuando una tablilla las indica expresamente debajo de la señal.\n\nESTA REGLA VALE PARA CASI TODAS LAS PROHIBICIONES, no solo para el adelantamiento: velocidad máxima, prohibido estacionar, prohibido girar. Es una de las respuestas más rentables del banco porque se repite con distintas señales.\n\nCLAVE: una prohibición muere en el cruce siguiente, o antes si algo la cancela. Si quieren que dure más, lo dicen con una tablilla.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6297,"bg":"При тази ситуация забраната от пътния знак е валидна:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56749.png","v":null,"a":[{"t":"до края на участъка от пътя с наклон","ok":true,"i":null,"es":"hasta el final del tramo de vía con pendiente"},{"t":"до знак, който отменя забраната","ok":false,"i":null,"es":"hasta la señal que cancela la prohibición"},{"t":"на разстояние, указано в забранителния знак","ok":false,"i":null,"es":"a la distancia indicada en la señal de prohibición"},{"t":"до следващото кръстовище","ok":false,"i":null,"es":"hasta la próxima intersección"}],"f":4,"es":"En esta situación la prohibición de la señal es válida:","explain":"Hasta el final del tramo con pendiente. Las senales de velocidad en pendientes son validas mientras dure la pendiente."},{"id":6710,"bg":"При тази допълнителна табела забранено ли е водачите на леки автомобили да завиват надясно след знака?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/88317.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"Con esta tablilla adicional, ¿está prohibido a los conductores de turismos girar a la derecha después de la señal?","explain":"SI, en este caso la tablilla incluye a los turismos en la prohibicion. Lee siempre la tablilla atentamente."},{"id":11682,"bg":"След този пътен знак водачът:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801980.png","v":null,"a":[{"t":"трябва да вземе мерки за ограничаване на шума","ok":true,"i":null,"es":"debe tomar medidas para limitar el ruido"},{"t":"може да паркира от двете страни на пътя","ok":false,"i":null,"es":"puede estacionar a ambos lados de la vía"},{"t":"не трябва да се движи със скорост по-висока от 40 km/h","ok":false,"i":null,"es":"no debe circular a una velocidad superior a 40 km/h"}],"f":4,"es":"Después de esta señal el conductor:","explain":"Debe tomar medidas para reducir el ruido (no tocar claxon, reducir velocidad). Zona de silencio."},{"id":11683,"bg":"Този пътен знак сигнализира за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801981.png","v":null,"a":[{"t":"допълнителна пътна лента за бавнодвижещи се ППС","ok":true,"i":null,"es":"carril adicional para vehículos lentos"},{"t":"задължително заобикаляне отдясно","ok":false,"i":null,"es":"paso obligatorio por la derecha"},{"t":"ограничение на скоростта до 30 km/h","ok":false,"i":null,"es":"limitación de velocidad a 30 km/h"},{"t":"еднопосочно движение след знака","ok":false,"i":null,"es":"tráfico de SENTIDO ÚNICO después de la señal"}],"f":4,"es":"Esta señal señaliza:","explain":"Señaliza un CARRIL ADICIONAL PARA VEHÍCULOS LENTOS.\n\nLA SEÑAL. Panel azul con los carriles dibujados y un círculo con «30» sobre el carril de la derecha, que nace y se incorpora.\n\nLA CIFRA ES LA CLAVE. Ese «30» no es un límite de velocidad de la vía: identifica el carril como reservado a los vehículos que no pueden superar esa velocidad. Es la diferencia exacta con la señal de la pregunta 6211, que dibuja un carril que aparece pero sin cifra — y por eso es un carril normal.\n\nQUIÉN DEBE USARLO. Los que llevan el distintivo «бавнодвижещо се ППС» y los que por construcción no pasan de 30 km/h. Se define por velocidad y distintivo, nunca por tipo de vehículo.\n\n«LIMITACIÓN DE VELOCIDAD A 30 km/h» es el distractor central: convierte una identificación de carril en una prohibición general. Un límite de velocidad sería un círculo ROJO aislado, no un número dentro de un panel de carriles.\n\n«PASO OBLIGATORIO POR LA DERECHA» y «SENTIDO ÚNICO» tienen dibujos completamente distintos.\n\nCLAVE: el mismo número significa cosas opuestas según dónde esté. En círculo rojo aislado, velocidad máxima. En círculo azul aislado, mínima obligatoria. Dentro de un panel de carriles, identifica a quién pertenece ese carril.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":12077,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1173458333.png","v":null,"a":[{"t":"товарни автомобили","ok":true,"i":null,"es":"camiones"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"автомобили със специален режим на движение","ok":false,"i":null,"es":"automóviles con régimen especial de circulación"},{"t":"автомобили със специално предназначение","ok":true,"i":null,"es":"automóviles de uso especial"}],"f":4,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (3 correctas)","explain":"Prohibido: camiones, tractores y automoviles con finalidad especial (no los de emergencia ni transporte publico)."},{"id":5930,"bg":"Този светлинен сигнал:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44599.png","v":null,"a":[{"t":"сигнализира, че навлизането по пътната лента, над която е поставен, е разрешено","ok":true,"i":null,"es":"indica que la entrada al carril sobre el que está es PERMITIDA"},{"t":"указва задължителна посока за движение","ok":false,"i":null,"es":"indica dirección obligatoria"},{"t":"указва място за задължително спиране","ok":false,"i":null,"es":"indica lugar de parada obligatoria"},{"t":"забранява навлизането в другите пътни ленти","ok":false,"i":null,"es":"prohíbe la entrada en los demás carriles"}],"f":4,"es":"Esta señal luminosa:"},{"id":6497,"bg":"При тази ситуация разрешено ли е да преминете по трамвайните линии, за да изпреварите товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65922.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"explain":"Las líneas de tranvía pintadas en la calzada NO son un carril normal de circulación para coches — solo puedes invadirlas en maniobras específicas y momentáneas (como girar), pero nunca para adelantar a otro vehículo, porque eso significa ocupar las vías del tranvía durante un tiempo prolongado mientras superas al vehículo lento, con riesgo de bloquear o colisionar con un tranvía que tenga prioridad absoluta sobre esa vía. Por eso la respuesta es 'no' — adelantar usando las vías del tranvía está prohibido aunque en ese momento no veas ningún tranvía circulando.","es":"En esta situación ¿está permitido circular por las vías del tranvía para adelantar al camión?"},{"id":5792,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53696.png","v":null,"a":[{"t":"забранява движението със скорост по-висока от означената","ok":true,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"указва задължителна минимална скорост за движение","ok":false,"i":null,"es":"indica velocidad mínima obligatoria"},{"t":"сигнализира препоръчителна скорост за движение","ok":false,"i":null,"es":"indica velocidad recomendada"}],"f":4,"es":"Esta señal:"},{"id":5810,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334712.png","v":null,"a":[{"t":"указва препоръчителна скорост за движение","ok":true,"i":null,"es":"indica velocidad recomendada"},{"t":"забранява движение със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"указва задължителна минимална скорост за движение","ok":false,"i":null,"es":"indica velocidad mínima obligatoria"}],"f":4,"es":"Esta señal:"},{"id":5819,"bg":"При тази ситуация разрешено ли е движение със скорост, по-ниска от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54273.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"En esta situación ¿está permitido circular a velocidad inferior a la indicada?"},{"id":5830,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57569.png","v":null,"a":[{"t":"означава край на задължителната минимална скорост","ok":true,"i":null,"es":"indica FIN de la velocidad mínima obligatoria"},{"t":"забранява движението със скорост по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"забранява движението със скорост по-ниска от означената","ok":false,"i":null,"es":"prohíbe velocidad inferior a la indicada"},{"t":"означава край на препоръчителната скорост на движение","ok":false,"i":null,"es":"indica fin de la velocidad recomendada"}],"f":4,"es":"Esta señal:"},{"id":5842,"bg":"Влияние върху големината на коефициента на сцепление на автомобилните гуми с пътя оказват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"видът на пътната настилка","ok":true,"i":null,"es":"el tipo de pavimento"},{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"видът на автомобилните гуми","ok":true,"i":null,"es":"el tipo de neumático"},{"t":"диаметърът на автомобилните гуми","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"f":4,"es":"El coeficiente de rozamiento neumático-asfalto está influido por: (3 correctas)","explain":"El rozamiento depende del tipo de pavimento (asfalto, adoquín), de su estado (seco, mojado, helado) y del tipo/estado del neumático. El DIÁMETRO de la rueda no cambia la adherencia: la superficie de contacto y el material sí."},{"id":5844,"bg":"Зависи ли коефициентът на сцепление на автомобилните гуми с пътя от състоянието на пътната настилка?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"¿Depende el coeficiente de rozamiento del estado del pavimento?","explain":"Sí: el estado del pavimento es determinante. El mismo asfalto ofrece mucha adherencia seco y muy poca mojado o helado."},{"id":5849,"bg":"При спиране на автомобила дължината на спирачния път зависи от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"скоростта на движение","ok":true,"i":null,"es":"la velocidad"},{"t":"състоянието на гумите","ok":true,"i":null,"es":"el estado de los neumáticos"},{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"диаметъра на гумите","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"f":4,"es":"La distancia de frenado depende de: (3 correctas)","explain":"La distancia de frenado depende de la velocidad (factor cuadrático: el doble de velocidad, cuatro veces más distancia), del estado de los neumáticos y del estado del pavimento. El diámetro de las ruedas no influye."},{"id":5852,"bg":"Как се променя дължината на спирачния път при мокра настилка в сравнение със суха, когато гумите са износени?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"увеличава се","ok":true,"i":null,"es":"aumenta"},{"t":"намалява","ok":false,"i":null,"es":"disminuye"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"},{"t":"зависи от вида на автомобилната гума","ok":false,"i":null,"es":"depende del tipo de neumático"}],"f":4,"es":"¿Cómo cambia la distancia de frenado en pavimento mojado respecto al seco con neumáticos normales?","explain":"Aumenta: en mojado el rozamiento cae y el vehículo necesita más metros para detenerse con neumáticos normales. Por eso en lluvia hay que aumentar la distancia y reducir la velocidad."},{"id":5856,"bg":"Блокирането на колелата на превозното средство при спиране може да доведе до:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"влошаване управляемостта на превозното средство","ok":true,"i":null,"es":"EMPEORAMIENTO de la manejabilidad"},{"t":"подобряване управляемостта на превозното средство","ok":false,"i":null,"es":"MEJORA de la manejabilidad"},{"t":"увеличаване сцеплението на гумите с пътя","ok":false,"i":null,"es":"aumento del rozamiento de los neumáticos con el asfalto"}],"f":4,"es":"El bloqueo de las ruedas durante el frenado puede provocar:","explain":"Ruedas bloqueadas = pérdida de manejabilidad: una rueda que no gira no puede dirigir, el vehículo sigue recto aunque gires el volante. El rozamiento además disminuye (deslizamiento), nunca aumenta."},{"id":5858,"bg":"Какво влияние оказва върху дължината на спирачния път блокирането на колелата при спиране?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"увеличава дължината на спирачния път","ok":true,"i":null,"es":"AUMENTA la distancia de frenado"},{"t":"не оказва влияние върху дължината на спирачния път","ok":false,"i":null,"es":"no tiene efecto"},{"t":"намалява дължината на спирачния път","ok":false,"i":null,"es":"REDUCE la distancia de frenado"}],"f":4,"es":"¿Qué efecto tiene el bloqueo de ruedas en la distancia de frenado?","explain":"AUMENTA: con las ruedas bloqueadas el neumático desliza sobre el asfalto (rozamiento dinámico, menor que el estático) y el coche recorre más metros. Por eso existe el ABS: impedir el bloqueo acorta la frenada."},{"id":5864,"bg":"Интервалът от 2 секунди между движещите се леки автомобили е достатъчен когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"пътят е сух","ok":true,"i":null,"es":"el camino está SECO"},{"t":"видимостта е намалена поради мъгла","ok":false,"i":null,"es":"la visibilidad está reducida por niebla"},{"t":"пътят е мокър","ok":false,"i":null,"es":"el camino está mojado"},{"t":"видимостта е ограничена","ok":false,"i":null,"es":"la visibilidad es limitada"}],"f":4,"es":"El intervalo de 2 segundos entre turismos es suficiente cuando:","explain":"El intervalo de 2 segundos basta solo con el camino SECO y buena visibilidad. Con lluvia, niebla o visibilidad limitada la frenada se alarga y el intervalo debe aumentarse."},{"id":5875,"bg":"Когато възникне опасност за движението водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да намали скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"в случай на необходимост да спре","ok":true,"i":null,"es":"si es necesario, parar"},{"t":"да включи аварийните светлини","ok":true,"i":null,"es":"activar las luces de emergencia"},{"t":"да изключи двигателя","ok":false,"i":null,"es":"apagar el motor"}],"f":4,"es":"Cuando surge un peligro en la circulación, el conductor debe: (3 correctas)","explain":"Ante un peligro: reduce la velocidad, para si es necesario y activa las luces de emergencia para avisar a los demás. Apagar el motor te dejaría sin dirección asistida ni capacidad de maniobra."},{"id":5883,"bg":"Кое от изброените действия на водача е най-опасно при преминаването покрай децата?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57825.png","v":null,"a":[{"t":"стремежът бързо да се премине през опасното място","ok":true,"i":null,"es":"intentar pasar rápido por el lugar peligroso"},{"t":"подаването на звуков сигнал за предупреждаване на децата","ok":false,"i":null,"es":"tocar el claxon para advertirles"},{"t":"рязкото спиране","ok":false,"i":null,"es":"frenar bruscamente"}],"f":4,"es":"¿Cuál es la acción más peligrosa al pasar junto a niños?"},{"id":5904,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58249.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да се движа с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"мога да премина зад децата, без да намалявам скоростта","ok":false,"i":null,"es":"puedo pasar detrás de los niños sin reducir"},{"t":"трябва да подам звуков сигнал, за да предупредя децата","ok":false,"i":null,"es":"debo tocar el claxon para advertir a los niños"}],"f":4,"es":"En esta situación: (2 correctas)"},{"id":6694,"bg":"При тази ситуация разрешено ли е движение със скорост, по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54350.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"En esta situación ¿está permitido circular a velocidad superior a la indicada?"},{"id":12027,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":13,"a":[{"t":"намалявам скоростта си на движение","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"рязко се отклонявам/преминавам надясно","ok":false,"i":null,"es":"me desvío bruscamente a la derecha"},{"t":"избягвам резки действия, свързани с управлението на МПС","ok":true,"i":null,"es":"evito acciones bruscas con el volante"}],"f":4,"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)"},{"id":12031,"bg":"Какъв е правилният начин на действие в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":17,"a":[{"t":"увеличавам скоростта си, за да осигуря безопасна дистанция","ok":false,"i":null,"es":"aumento la velocidad para crear distancia segura"},{"t":"намалявам скоростта си, за да може и водачът отзад да намали скоростта си","ok":false,"i":null,"es":"reduzco la velocidad para que el de atrás también pueda reducir"},{"t":"продължавам движението си, без да променям скоростта си","ok":true,"i":null,"es":"continúo sin cambiar velocidad"}],"f":4,"es":"¿Cuál es la actuación correcta en esta situación?","explain":"Un coche rojo me sigue pegado (se ve en el retrovisor) en carretera despejada: lo correcto es CONTINUAR sin cambiar mi velocidad, siendo previsible, y que sea él quien gestione su distancia o adelante. Acelerar 'para abrir hueco' me saca de mi velocidad segura e invita a acelerar; frenar 'para que él frene' es una provocación que puede provocar el alcance. Ante un pegado: cero reacciones bruscas."},{"id":6219,"bg":"Преди да предприеме маневра водачът трябва да се убеди, че няма да създаде опасност за участниците в движението, като:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да се съобрази с тяхното положение","ok":true,"i":null,"es":"debe tener en cuenta su posición"},{"t":"трябва да се съобрази с посоката им на движение","ok":true,"i":null,"es":"debe tener en cuenta su dirección de circulación"},{"t":"трябва да се съобрази със скоростта им на движение","ok":true,"i":null,"es":"debe tener en cuenta su velocidad"},{"t":"не е задължен да се съобразява със сигналите, които подават","ok":false,"i":null,"es":"no está obligado a considerar las señales que dan"}],"f":4,"es":"Antes de ejecutar una maniobra el conductor debe asegurarse de no crear peligro: (3 correctas)","explain":"Antes de maniobrar debes valorar la posición, la dirección y la velocidad de los demás participantes, Y TAMBIÉN las señales que dan (intermitentes): por eso la opción 'no está obligado a considerar las señales' es falsa."},{"id":6267,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70117.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":4,"es":"En esta situación debo:"},{"id":6337,"bg":"При тази ситуация задължени ли сте да пропуснете трамвая?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70812.png","v":null,"a":[{"t":"да, защото е релсово ППС","ok":true,"i":null,"es":"sí, porque es un vehículo ferroviario"},{"t":"не, защото се движа направо","ok":false,"i":null,"es":"no, porque voy recto"}],"f":4,"es":"En esta situación, ¿está obligado a dejar pasar al tranvía?"},{"id":6346,"bg":"При тази ситуация синият автомобил трябва да премине преди трамвая.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70978.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":4,"es":"En esta situación el coche azul debe pasar antes que el tranvía. Esto es:"},{"id":6366,"bg":"При тази ситуация с предимство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71177.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"el coche azul"}],"f":4,"es":"En esta situación tiene prioridad el conductor del:"},{"id":6370,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на мост","ok":true,"i":null,"es":"en puente"},{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"при ограничена видимост","ok":true,"i":null,"es":"con visibilidad limitada"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en un tramo de carretera en obras"}],"f":4,"es":"El cambio de sentido está PROHIBIDO: (3 correctas)","explain":"Prohibido cambiar de sentido en puente, sobre paso de peatones y con visibilidad limitada. Un tramo en obras no lo prohíbe por sí mismo (salvo señalización específica)."},{"id":6374,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"при ограничена видимост","ok":true,"i":null,"es":"con visibilidad limitada"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en un tramo de carretera en obras"},{"t":"на път с интензивно движение","ok":false,"i":null,"es":"en vía de intenso tráfico"}],"f":4,"es":"El cambio de sentido está PROHIBIDO: (2 correctas)","explain":"Prohibido en túnel y con visibilidad limitada: en ambos casos el tráfico que llega no puede verte a tiempo. Las obras o el tráfico intenso no prohíben la maniobra por sí mismos."},{"id":6390,"bg":"Кое от изброените действия е задължително при маневрата изпреварване?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"подаване на сигнал за отклонение наляво","ok":true,"i":null,"es":"señalizar desviación a la izquierda"},{"t":"подаване на сигнал за отклонение надясно","ok":true,"i":null,"es":"señalizar desviación a la derecha"},{"t":"подаване на звуков сигнал, когато маневрата се извършва в населено място","ok":false,"i":null,"es":"tocar el claxon en zona urbana"},{"t":"включване на дългите светлини","ok":false,"i":null,"es":"activar las luces largas"}],"f":4,"es":"¿Qué acciones son obligatorias en la maniobra de adelantamiento? (2 correctas)","explain":"En el adelantamiento son obligatorias DOS señales: intermitente izquierdo al salir y derecho al reincorporarte. El claxon en ciudad está prohibido salvo peligro inminente y las largas solo son señal adicional opcional."},{"id":6406,"bg":"Разрешено ли е да продължите изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71507.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":4,"es":"¿Está permitido continuar el adelantamiento en esta situación?"},{"id":6421,"bg":"При тази ситуация разрешено ли е да продължите изпреварването?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71885.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":4,"es":"En esta situación ¿está permitido continuar el adelantamiento?"},{"id":6454,"bg":"Разрешено ли е движение назад при завиване в обратна посока на път извън кръстовище?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"¿Está permitido ir marcha atrás para dar la vuelta en una vía fuera de intersección?","explain":"Sí: la marcha atrás para dar la vuelta fuera de una intersección está permitida, siempre asegurándote de no crear peligro (la marcha atrás obliga a ceder el paso a todos)."},{"id":6704,"bg":"Разрешено ли е да предприемете изпреварване при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71606.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":4,"es":"¿Está permitido adelantar en esta situación?"},{"id":9831,"bg":"Разрешено ли е да изпреварите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270042809.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"¿Está permitido adelantar en esta situación?"},{"id":11997,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":29,"a":[{"t":"да продължа да намалявам скоростта","ok":true,"i":null,"es":"continúo reduciendo la velocidad"},{"t":"да премина в лявата лента","ok":false,"i":null,"es":"paso al carril izquierdo"},{"t":"да изчакам преди препятствието","ok":true,"i":null,"es":"espero antes del obstáculo"}],"f":4,"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)"},{"id":11998,"bg":"Какво е правилното действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":42,"a":[{"t":"прекратявам изпреварването и се връщам в дясната лента","ok":true,"i":null,"es":"abandono el adelantamiento y vuelvo al carril derecho"},{"t":"продължавам изпреварването с непроменена скорост","ok":false,"i":null,"es":"continúo el adelantamiento sin cambiar velocidad"},{"t":"увеличавам скоростта си и продължавам изпреварването","ok":false,"i":null,"es":"acelero y completo el adelantamiento"}],"f":4,"es":"¿Cuál es la actuación correcta?"},{"id":12009,"bg":"Преди да преминете през кръстовището трябва да имате готовност да спрете заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":25,"a":[{"t":"автомобила със специално предназначение","ok":true,"i":null,"es":"el vehículo de emergencia"},{"t":"велосипедиста","ok":false,"i":null,"es":"el ciclista"},{"t":"състава от пътни превозни средства","ok":true,"i":null,"es":"el conjunto de vehículos (camión con remolque)"}],"f":4,"es":"Antes de pasar la intersección debes estar listo para frenar por: (2 correctas)"},{"id":12040,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":32,"a":[{"t":"да подам сигнал с превключване на дългите светлини","ok":false,"i":null,"es":"señalizo con las largas"},{"t":"да продължа без да променям скоростта, като се движа възможно най-вдясно","ok":false,"i":null,"es":"continúo sin cambiar velocidad, todo a la derecha"},{"t":"да намаля скоростта своевременно","ok":true,"i":null,"es":"reduzco la velocidad a tiempo"}],"f":4,"es":"¿Cuál es la actuación correcta en esta situación?"},{"id":5890,"bg":"При тази ситуация разрешено ли е червеният автомобил да продължи движението си направо?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48188.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":4,"es":"En esta situación ¿está permitido al coche rojo continuar recto?"},{"id":6465,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на синия автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52820.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да се движа с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото се движа направо","ok":false,"i":null,"es":"no tengo que considerarlo porque voy recto"}],"f":4,"es":"¿Cómo debes actuar en esta situación si el conductor del coche azul, que debe cederte el paso, no muestra con sus acciones que vaya a parar? (2 correctas)"},{"id":6493,"bg":"В тунел, завиването в обратна посока е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено само на път с три и повече пътни ленти","ok":false,"i":null,"es":"permitido solo en vías de 3 o más carriles"},{"t":"разрешено, ако няма насрещно движение","ok":false,"i":null,"es":"permitido si no hay tráfico contrario"},{"t":"разрешено, ако движението в тунела е двупосочно","ok":false,"i":null,"es":"permitido si el tráfico es bidireccional"}],"f":4,"es":"En un túnel el cambio de sentido está:","explain":"Prohibido, sin excepciones: en un túnel nunca se cambia de sentido, da igual el número de carriles o el tráfico. Espacio cerrado + maniobra contra el flujo = riesgo máximo."},{"id":6577,"bg":"При тази ситуация преминавам едновременно с червения автомобил и не съм задължен да пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67757.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":4,"es":"En esta situación paso simultáneamente con el rojo y no tengo que ceder al azul. Esto es:"},{"id":5562,"bg":"При тази ситуация районът на спирката започва от пътния знак и е с дължина:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38988.png","v":null,"a":[{"t":"50 м","ok":true,"i":null,"es":"50 m"},{"t":"30 м","ok":false,"i":null,"es":"30 m"},{"t":"20 м","ok":false,"i":null,"es":"20 m"},{"t":"10 м","ok":false,"i":null,"es":"10 m"}],"f":4,"es":"En esta situación, la zona de la parada empieza en la señal y tiene una longitud de:","explain":""},{"id":5579,"bg":"При тази ситуация, приближавайки към спрелия на спирката тролейбус трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39021.png","v":null,"a":[{"t":"своевременно да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad a tiempo"},{"t":"да се движа с повишено внимание","ok":true,"i":null,"es":"circular con mayor atención"},{"t":"да имам готовност да спра в случай на необходимост","ok":true,"i":null,"es":"estar preparado para detenerme en caso de necesidad"},{"t":"да подам звуков сигнал","ok":false,"i":null,"es":"tocar el claxon"}],"f":4,"es":"En esta situación, al acercarme al trolebús parado en la parada, debo: (3 correctas)","explain":""},{"id":5596,"bg":"При тази ситуация увеличавам скоростта, за да премина по-бързо покрай спиращия трамвай.","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39386.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":4,"es":"En esta situación aumento la velocidad para pasar más rápido junto al tranvía que se está deteniendo. Esto es:","explain":""},{"id":11623,"bg":"При тази ситуация длъжни ли сте да намалите скоростта, за да улесните потеглянето на автобуса от спирката?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39651.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"En esta situación, ¿está obligado a reducir la velocidad para facilitar que el autobús arranque de la parada?","explain":""},{"id":5689,"bg":"На водача на мотопед е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се движи успоредно до друго двуколесно пътно превозно средство","ok":true,"i":null,"es":"circular en paralelo a otro vehículo de dos ruedas"},{"t":"да превозва предмети, които пречат на управлението на превозното средство","ok":true,"i":null,"es":"transportar objetos que dificultan la conducción del vehículo"},{"t":"да управлява превозно средство по площите, предназначени само за пешеходци","ok":true,"i":null,"es":"conducir un vehículo por las zonas destinadas solo a peatones"},{"t":"да се движи по пътния банкет","ok":false,"i":null,"es":"circular por el arcén"}],"f":4,"es":"Al conductor de un ciclomotor le está prohibido: (3 correctas)","explain":"Prohibido al ciclomotor: circular en paralelo a otro de dos ruedas, llevar objetos que dificulten la conducción y meterse en zonas peatonales. Circular por el arcén derecho apto le está PERMITIDO: es la opción trampa."},{"id":5696,"bg":"По кой от изброените начини може да бъде обозначен повреденият автомобил при теглене през нощта?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с включени светлини и авариен сигнал","ok":true,"i":null,"es":"con las luces y las luces de emergencia encendidas"},{"t":"с включени светлини и поставяне отзад на светлоотразителен триъгълник","ok":true,"i":null,"es":"con las luces encendidas y un triángulo reflectante colocado detrás"},{"t":"с поставяне на бяла светлина отзад","ok":false,"i":null,"es":"colocando una luz blanca detrás"},{"t":"само с включване на светлините","ok":false,"i":null,"es":"solo encendiendo las luces"}],"f":4,"es":"¿De cuál de las formas indicadas puede señalizarse el automóvil averiado al ser remolcado de noche? (2 correctas)","explain":"El remolcado de noche se señaliza con: luces + luces de emergencia encendidas, o luces + triángulo reflectante colocado detrás. Una luz blanca detrás confundiría (blanco = frente/marcha atrás) y solo las luces no bastan para avisar de la anomalía."},{"id":5709,"bg":"Каква трябва да бъде дължината на гъвкавата връзка (въже, верига) при теглене на повредено МПС?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от 4 до 6 м","ok":true,"i":null,"es":"de 4 a 6 m"},{"t":"от 2 до 3 м","ok":false,"i":null,"es":"de 2 a 3 m"},{"t":"от 3 до 4 м","ok":false,"i":null,"es":"de 3 a 4 m"},{"t":"до 2 м","ok":false,"i":null,"es":"hasta 2 m"}],"f":4,"es":"¿Cuál debe ser la longitud del cable flexible al remolcar un vehículo averiado?","explain":"De 4 a 6 m: el cable flexible necesita ese rango: menos de 4 m no da margen de frenado al remolcado, y más de 6 m hace el convoy incontrolable y el cable poco visible para terceros."},{"id":5766,"bg":"При теглене на повредено превозно средство, разрешава ли се превоз на пътници в него?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не, във всички случаи","ok":true,"i":null,"es":"no, en ningún caso"},{"t":"не, но само когато водачът е със стаж до 2 години","ok":false,"i":null,"es":"no, pero solo cuando el conductor tiene menos de 2 años de experiencia"},{"t":"да, без ограничение","ok":false,"i":null,"es":"sí, sin restricciones"},{"t":"да, но само когато водачът е с правоспособност за категория С","ok":false,"i":null,"es":"sí, pero solo cuando el conductor tiene el permiso de categoría C"}],"f":4,"es":"Al remolcar un vehículo averiado, ¿se permite transportar pasajeros en él?","explain":"No, en ningún caso: el vehículo remolcado no lleva pasajeros: sin motor pleno, con frenada limitada y dependiendo de un cable o barra, es el lugar más peligroso del convoy. Ni la experiencia ni la categoría del conductor cambian eso."},{"id":5780,"bg":"Разрешено ли е теглене на повреден автомобил, когато пътят е хлъзгав?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, но само с твърда връзка","ok":true,"i":null,"es":"sí, pero solo con barra RÍGIDA"},{"t":"да, но само с гъвкава връзка","ok":false,"i":null,"es":"sí, pero solo con cable FLEXIBLE"},{"t":"да, без ограничение","ok":false,"i":null,"es":"sí, sin restricciones"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"¿Está permitido remolcar en carretera resbaladiza?","explain":"En carretera resbaladiza solo con barra RÍGIDA: la barra transmite el frenado directamente y el remolcado no puede embestir. El cable flexible está prohibido con firme deslizante: el remolcado no podría mantenerlo tenso al frenar."},{"id":5804,"bg":"При тази ситуация водачът на зеления автомобил:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29226.png","v":null,"a":[{"t":"трябва да пропусне червения автомобил, защото той е със специален режим на движение","ok":true,"i":null,"es":"debe ceder el paso al automóvil rojo, porque circula en régimen especial"},{"t":"трябва да пропусне червения автомобил, защото той приближава кръстовището от дясната му страна","ok":false,"i":null,"es":"debe ceder el paso al automóvil rojo, porque se acerca a la intersección por su derecha"},{"t":"не е задължен да пропусне червения автомобил, защото се движи по пътя с предимство","ok":false,"i":null,"es":"no está obligado a ceder el paso al automóvil rojo, porque circula por la vía con prioridad"}],"f":4,"es":"En esta situación, el conductor del automóvil verde:","explain":""},{"id":5820,"bg":"Разрешено ли е водачите на ППС да се движат в непосредствена близост зад превозните средства със специален режим на движение?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"да, когато няма ограничение на скоростта","ok":false,"i":null,"es":"sí, cuando no hay limitación de velocidad"}],"f":4,"es":"¿Está permitido que los conductores circulen muy cerca detrás de los vehículos con régimen especial de circulación?","explain":"No: prohibido pegarse detrás de un vehículo con régimen especial: frena y maniobra de forma impredecible, y tú estarías 'colándote' con su prioridad. Se le facilita el paso, no se le usa de abrelatas."},{"id":5822,"bg":"На водача на МПС със специален режим на движение е разрешено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да преминава при забраняващ сигнал на светофара","ok":true,"i":null,"es":"pasar con la señal prohibitiva del semáforo"},{"t":"да преминава, без да спира, при наличие на пътен знак, който изисква това","ok":true,"i":null,"es":"pasar sin detenerse cuando hay una señal que exige detenerse"},{"t":"да надвишава разрешената максимална скорост на движение","ok":true,"i":null,"es":"superar la velocidad máxima autorizada"},{"t":"да не спазва сигналите на регулировчика","ok":false,"i":null,"es":"no obedecer las señales del agente que regula el tráfico"}],"f":4,"es":"Al conductor de un vehículo con régimen especial de circulación le está permitido: (3 correctas)","explain":"El régimen especial permite: pasar con semáforo en rojo, no detenerse ante señal de stop y superar la velocidad máxima (con las señales luminosas y acústicas activas). Lo que NUNCA puede es desobedecer al agente regulador: el agente manda sobre todo."},{"id":6683,"bg":"При теглене на повреден автомобил е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"превозване на пътници в тегленото моторно превозно средство","ok":true,"i":null,"es":"transportar pasajeros en el vehículo REMOLCADO"},{"t":"теглене с гъвкава връзка по хлъзгав път","ok":true,"i":null,"es":"remolcar con cable flexible en carretera resbaladiza"},{"t":"превоз на пътници в теглещото превозно средство","ok":false,"i":null,"es":"transportar pasajeros en el vehículo REMOLCADOR"},{"t":"теглещото МПС да е от категория, различна от тази на тегленото МПС","ok":false,"i":null,"es":"el vehículo remolcador ser de categoría diferente al remolcado"}],"f":4,"es":"Al remolcar un vehículo averiado está PROHIBIDO: (2 correctas)","explain":"Prohibido al remolcar: pasajeros en el vehículo REMOLCADO (el punto más peligroso del convoy) y cable flexible en carretera resbaladiza. En el remolcador sí puede haber pasajeros, y la categoría de ambos vehículos no tiene por qué coincidir."},{"id":11626,"bg":"Разрешената максимална скорост за движение при теглене на повредено МПС, с изключение на автомагистрала или скоростен път е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"40 km/h","ok":true,"i":null,"es":"40 km/h"},{"t":"30 km/h","ok":false,"i":null,"es":"30 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"f":4,"es":"La velocidad máxima permitida al remolcar un vehículo averiado, excepto en autopista o vía rápida, es:","explain":"40 km/h: velocidad máxima remolcando un averiado fuera de autopista/vía rápida. El convoy improvisado no es estable: el límite bajo compensa la frenada y el control degradados."},{"id":11732,"bg":"Разрешената максимална скорост за движение в населени места при теглене на повредено МПС е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"40 km/h","ok":true,"i":null,"es":"40 km/h"},{"t":"20 km/h","ok":false,"i":null,"es":"20 km/h"},{"t":"30 km/h","ok":false,"i":null,"es":"30 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"}],"f":4,"es":"La velocidad máxima permitida dentro de poblado al remolcar un vehículo averiado es:","explain":"40 km/h también dentro de poblado: el límite de remolcado no cambia por estar en ciudad (donde el general es 50): remolcando, el techo es 40 en todas partes salvo autopista/vía rápida."},{"id":5568,"bg":"След този пътен знак спирането за престой върху платното за движение е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42668.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":4,"es":"Después de esta señal, la detención (parada) en la calzada está:","explain":""},{"id":5569,"bg":"След този пътен знак паркирането на ППС върху платното за движение е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42740.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":4,"es":"Después de esta señal, el estacionamiento de vehículos en la calzada está:","explain":""},{"id":5639,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на място, където ППС създава опасност или е пречка за движението","ok":true,"i":null,"es":"en un lugar donde el vehículo crea peligro o es un obstáculo para el tráfico"},{"t":"на място, където ППС закрива от другите участници в движението пътен знак","ok":true,"i":null,"es":"en un lugar donde el vehículo oculta a los demás usuarios una señal de tráfico"},{"t":"на място, където ППС закрива от другите участници в движението сигнал на светофара","ok":true,"i":null,"es":"en un lugar donde el vehículo oculta a los demás usuarios la señal del semáforo"},{"t":"на път с еднопосочно движение","ok":false,"i":null,"es":"en vía de sentido único"}],"f":4,"es":"El estacionamiento está prohibido: (3 correctas)","explain":"Prohibido estacionar donde el vehículo crea peligro u obstáculo, y donde oculta a los demás una señal de tráfico o un semáforo: dejarías a los otros sin ver la regulación. En vía de sentido único estacionar no está prohibido por sí mismo."},{"id":5666,"bg":"През нощта на осветен участък от пътя движението с включени дълги светлини е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"винаги разрешено","ok":false,"i":null,"es":"siempre permitido"},{"t":"разрешено само при изпреварване","ok":false,"i":null,"es":"entrar solo al adelantar"},{"t":"по преценка на водача","ok":false,"i":null,"es":"a criterio del conductor"}],"f":4,"es":"De noche, en un tramo iluminado de la vía, circular con las luces largas encendidas está:","explain":"Prohibido: en tramo iluminado de noche las largas no aportan nada y deslumbran a todos. Con luz artificial suficiente se circula con cortas: las largas son para la oscuridad sin tráfico de frente."},{"id":5668,"bg":"През нощта, при разминаване на неосветен път, водачът е длъжен да се движи с включени:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"дълги светлини","ok":false,"i":null,"es":"luces largas"},{"t":"къси светлини","ok":true,"i":null,"es":"luces cortas"},{"t":"само габаритни светлини","ok":false,"i":null,"es":"solo luces de posición"}],"f":4,"es":"De noche, al cruzarse en una vía sin iluminación, el conductor está obligado a circular con:","explain":"Con luces CORTAS: al cruzarte de noche cambias a cortas para no deslumbrar al que viene: es la regla del cruce nocturno. Solo posición te dejaría sin ver la vía."},{"id":5690,"bg":"Кое от изброените действия е опасно при навлизане в заледен участък от пътя?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"рязкото намаляване на скоростта","ok":true,"i":null,"es":"la reducción brusca de la velocidad"},{"t":"рязкото подаване на газ","ok":true,"i":null,"es":"dar gas de golpe"},{"t":"изключването на скоростния механизъм","ok":false,"i":null,"es":"desacoplar la marcha (dejar en punto muerto)"},{"t":"навлизането с висока скорост","ok":true,"i":null,"es":"entrar a alta velocidad"}],"f":4,"es":"¿Cuál de las acciones indicadas es peligrosa al entrar en un tramo helado de la vía? (3 correctas)","explain":"En hielo es peligroso todo lo BRUSCO: frenar de golpe, dar gas de golpe y entrar a alta velocidad: cualquier cambio súbito rompe la poca adherencia. El punto muerto no es lo ideal, pero no es la acción peligrosa señalada."},{"id":5734,"bg":"Пониженото налягане на въздуха в автомобилните гуми води до увеличаване на разхода на гориво.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":4,"es":"La presión de aire baja en los neumáticos provoca un aumento del consumo de combustible.","explain":"Correcto: con presión baja aumenta la superficie de contacto y la deformación del neumático: más resistencia a la rodadura, más consumo. Es una de las relaciones causa-efecto que el banco repite en ambos sentidos."},{"id":5739,"bg":"Ако водачът трябва да приеме лекарство, за което не знае дали е съвместимо с управлението на МПС:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"преди да приеме лекарството, трябва да се консултира с лекар или фармацевт","ok":true,"i":null,"es":"antes de tomar el medicamento, debe consultar a un médico o farmacéutico"},{"t":"може да приеме лекарството, но трябва за приеме и тонизиращи напитки","ok":false,"i":null,"es":"puede tomar el medicamento, pero también debe tomar bebidas estimulantes"},{"t":"не трябва да продължи да управлява след приемане на лекарството, ако не знае дали е съвместимо с управлението","ok":true,"i":null,"es":"no debe seguir conduciendo tras tomar el medicamento si no sabe si es compatible con la conducción"},{"t":"преди да приеме лекарството, трябва да се запознае с описанието на лекарството в листовката за пациента","ok":true,"i":null,"es":"antes de tomar el medicamento, debe leer su descripción en el prospecto"}],"f":4,"es":"Si el conductor debe tomar un medicamento del que no sabe si es compatible con la conducción: (3 correctas)","explain":"Ante un medicamento desconocido: consulta a médico o farmacéutico, lee el prospecto y NO sigas conduciendo si no sabes si es compatible. La opción de 'compensarlo' con bebidas estimulantes es un disparate farmacológico."},{"id":5743,"bg":"Как трябва да постъпите, ако се налага да пътувате, но сте приели лекарство, което влияе отрицателно при уравлението на автомобила?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"ще осигуря друг водач за пътуването","ok":true,"i":null,"es":"conseguiré otro conductor para el viaje"},{"t":"ще управлявам, като се движа с ниска скорост","ok":false,"i":null,"es":"conduciré circulando a baja velocidad"},{"t":"ще управлявам, като избягвам участъци с интензивно движение","ok":false,"i":null,"es":"conduciré evitando tramos con tráfico intenso"}],"f":4,"es":"¿Cómo debe actuar si necesita viajar pero ha tomado un medicamento que influye negativamente en la conducción?","explain":"Consigue otro conductor: si el medicamento afecta a la conducción, la única solución segura es no conducir. Ni la baja velocidad ni evitar el tráfico intenso devuelven los reflejos que el fármaco ha quitado."},{"id":6109,"bg":"Водачът обикновено счита, че се движи със скорост, по-ниска от действителната, когато:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"се изкачва по път с голям наклон","ok":false,"i":null,"es":"sube por una vía con gran pendiente"},{"t":"се движи по път с голяма широчина и много пътни ленти","ok":true,"i":null,"es":"circula por una vía muy ancha y con muchos carriles"},{"t":"се движи по тесен двулентов път","ok":false,"i":null,"es":"circula por una vía estrecha de dos carriles"},{"t":"се движи по път с много последователни завои","ok":false,"i":null,"es":"circula por una vía con muchas curvas sucesivas"}],"f":4,"es":"El conductor suele creer que circula a una velocidad más baja que la real cuando:","explain":"En vía muy ancha y de muchos carriles el conductor SUBESTIMA su velocidad: sin referencias cercanas (paredes, árboles), la sensación de movimiento baja. En vías estrechas o con curvas ocurre lo contrario: parece que vas más rápido."},{"id":6111,"bg":"Времето за реакция на водача при аварийно спиране, оказва ли влияние на дължината на спирачния път на автомобила?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"El tiempo de reacción del conductor en una frenada de emergencia, ¿influye en la distancia de frenado del automóvil?","explain":"Sí: la distancia total de detención = distancia de reacción + distancia de frenado. Durante tu tiempo de reacción el coche sigue avanzando a velocidad plena: cada décima de segundo son metros."},{"id":6112,"bg":"При употребата дори на малки количества алкохол времето за реакция на водача:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"се увеличава","ok":true,"i":null,"es":"aumenta"},{"t":"намалява","ok":false,"i":null,"es":"disminuye"},{"t":"не се влияе от алкохола","ok":false,"i":null,"es":"no se ve afectado por el alcohol"}],"f":4,"es":"Con el consumo incluso de pequeñas cantidades de alcohol, el tiempo de reacción del conductor:","explain":"Aumenta: incluso pequeñas cantidades de alcohol alargan el tiempo de reacción: el cerebro procesa más lento aunque el conductor 'se sienta bien'. No existe dosis que lo acorte."},{"id":6126,"bg":"Най-ефективният начин за намаляване на умората при продължително управление на МПС е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"слушането на подходяща музика","ok":false,"i":null,"es":"escuchar música adecuada"},{"t":"консумирането на тонизиращи напитки","ok":false,"i":null,"es":"consumir bebidas estimulantes"},{"t":"спирането за почивка","ok":true,"i":null,"es":"detenerse a descansar"}],"f":4,"es":"La forma más eficaz de reducir la fatiga en una conducción prolongada es:","explain":"Detenerse a descansar: es la única medida eficaz contra la fatiga. La música y las bebidas estimulantes solo la disfrazan un rato: el déficit de descanso sigue ahí, esperando."},{"id":6131,"bg":"Ако по време на управление водачът се чувства уморен, до намирането на безопасно място за спиране най-добре е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да осигури достъп на свеж въздух в купето","ok":true,"i":null,"es":"asegurar la entrada de aire fresco en el habitáculo"},{"t":"внимателно да избере скоростта, с която да се движи","ok":true,"i":null,"es":"elegir con cuidado la velocidad a la que circular"},{"t":"да разговаря с пътниците в автомобила","ok":true,"i":null,"es":"conversar con los pasajeros del automóvil"},{"t":"да сменя непрекъснато предавките за да подобри концентрацията си","ok":false,"i":null,"es":"cambiar de marcha continuamente para mejorar su concentración"}],"f":4,"es":"Si durante la conducción el conductor se siente fatigado, hasta encontrar un lugar seguro donde detenerse lo mejor es: (3 correctas)","explain":"Hasta encontrar dónde parar: aire fresco, velocidad elegida con prudencia y conversación con los pasajeros: paliativos razonables. Jugar con las marchas no mejora la concentración: añade tarea inútil."},{"id":6139,"bg":"Защо при управление през нощта водачът не трябва да гледа директно към фаровете на насрещно движещите се автомобили?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"защото ще го заболят очите","ok":false,"i":null,"es":"porque le dolerán los ojos"},{"t":"защото през времето за адаптация няма да вижда добре","ok":true,"i":null,"es":"porque durante el tiempo de adaptación no verá bien"},{"t":"защото има опасност да увреди зрението си","ok":false,"i":null,"es":"porque existe el peligro de dañarse la vista"}],"f":4,"es":"¿Por qué al conducir de noche el conductor no debe mirar directamente a los faros de los automóviles que vienen de frente?","explain":"No mires a los faros que vienen: tras el deslumbramiento, el ojo necesita un TIEMPO DE ADAPTACIÓN durante el cual apenas ves: conduces a ciegas unos segundos. Se mira al borde derecho de tu carril, no a la luz."},{"id":6146,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"трудност при съсредоточаване","ok":true,"i":null,"es":"dificultad para concentrarse"},{"t":"намаляване на обема на възприеманите обекти от пътната обстановка","ok":true,"i":null,"es":"reducción de los objetos percibidos del entorno"},{"t":"неправилни реакции","ok":true,"i":null,"es":"reacciones incorrectas"},{"t":"висока точност на възприеманите обекти от пътната обстановка","ok":false,"i":null,"es":"alta precisión en la percepción de objetos"}],"f":4,"es":"Las señales de alerta de fatiga en el conductor son: (3 correctas)","explain":"Fatiga: cuesta concentrarse, percibes MENOS objetos del entorno y las reacciones se vuelven incorrectas. La 'alta precisión en la percepción' es lo contrario: señal de conductor despejado."},{"id":6153,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"взимане на необмислени решения","ok":true,"i":null,"es":"tomar decisiones irreflexivas"},{"t":"повишаване на способността за предвиждане на ситуациите","ok":false,"i":null,"es":"el aumento de la capacidad de prever las situaciones"},{"t":"затруднения в ориентирането в пътната обстановка","ok":true,"i":null,"es":"dificultades para orientarse en la situación del tráfico"},{"t":"неправилна оценка за скоростта на движение","ok":true,"i":null,"es":"evaluar incorrectamente la velocidad de circulación"}],"f":4,"es":"Los signos de advertencia de fatiga en el conductor son: (3 correctas)","explain":"Fatiga: decisiones irreflexivas, dificultad para orientarse en el tráfico y mala evaluación de la velocidad (propia y ajena). El 'aumento de la capacidad de prever' es el distractor inverso de esta serie."},{"id":6154,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"взимане на неточни решения","ok":true,"i":null,"es":"tomar decisiones imprecisas"},{"t":"намаляване на способността за предвиждане на ситуациите","ok":true,"i":null,"es":"la disminución de la capacidad de prever las situaciones"},{"t":"затруднения в ориентирането в пътната обстановка","ok":true,"i":null,"es":"dificultades para orientarse en la situación del tráfico"},{"t":"повишаване на способността за правилна преценка","ok":false,"i":null,"es":"el aumento de la capacidad de juzgar correctamente"}],"f":4,"es":"Los signos de advertencia de fatiga en el conductor son: (3 correctas)","explain":"Variante de la misma serie: decisiones imprecisas, MENOS capacidad de prever y dificultades de orientación. La opción del 'aumento de la capacidad de juzgar' es el espejo falso: la fatiga nunca suma."},{"id":11638,"bg":"На водача е забранено да управлява пътно превозно средство с концентрация на алкохол в кръвта над 0,5 на хиляда и/или след употреба на наркотични вещества или техни аналози:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":4,"es":"Al conductor le está prohibido conducir un vehículo con una concentración de alcohol en sangre superior a 0,5 por mil y/o tras consumir estupefacientes o sus análogos:","explain":"Correcto: prohibido conducir con más de 0,5‰ de alcohol y/o tras consumir estupefacientes. Es la prohibición base de la ley: el 'y/o' significa que cada una basta por sí sola."},{"id":5536,"bg":"При движение по пътищата, отворени за обществено ползване, водачът:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не трябвада изхвърля и да оставя предмети на пътя","ok":true,"i":null,"es":"no debe arrojar ni dejar objetos en la vía"},{"t":"не е задължен да отстранява предмети, паднали от превозното средство","ok":false,"i":null,"es":"no está obligado a retirar objetos caídos de su vehículo"},{"t":"трябва да спазва действащите норми за вредни емисии на отработени газове от МПС","ok":true,"i":null,"es":"debe cumplir las normas vigentes de emisiones contaminantes de los vehículos"},{"t":"с поведението си не трябва да създава опасности и пречки за движението","ok":true,"i":null,"es":"con su comportamiento no debe crear peligros ni obstáculos para el tráfico"}],"f":4,"es":"Al circular por vías abiertas al uso público, el conductor: (3 correctas)","explain":"En vías públicas el conductor: no arroja ni deja objetos, cumple las normas de emisiones y no crea peligros ni obstáculos con su comportamiento. La falsa es clara: SÍ estás obligado a retirar lo que caiga de tu vehículo."},{"id":5997,"bg":"На кое от посочените изисквания трябва да отговаря превозваният товар?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да не закрива огледалата за виждане назад","ok":true,"i":null,"es":"no tape los retrovisores"},{"t":"да не закрива светлинните устройства на автомобила","ok":true,"i":null,"es":"no cubra los dispositivos luminosos del vehículo"},{"t":"да не закрива сигналните устройства на автомобила","ok":true,"i":null,"es":"no debe ocultar los dispositivos de señalización del automóvil"},{"t":"да е опакован и да има етикети","ok":false,"i":null,"es":"estar embalada y llevar etiquetas"}],"f":4,"es":"¿Cuál de los requisitos indicados debe cumplir la carga transportada? (3 correctas)","explain":"La carga no debe tapar: retrovisores, dispositivos luminosos ni señalización del vehículo: todo lo que te permite ver y ser visto. Embalaje y etiquetas no son exigencias del código (salvo mercancías peligrosas, que es otro régimen)."},{"id":6002,"bg":"Как трябва да постъпите, когато поради движение с ниска скорост причинявате образуване на колона от ППС?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"при първа възможност спирам и пропускам колоната","ok":true,"i":null,"es":"en la primera ocasión me detengo y dejo pasar a la columna"},{"t":"нямам задължение да се съобразявам с превозните средства, движещи се зад мен","ok":false,"i":null,"es":"no tengo obligación de tener en cuenta a los vehículos que circulan detrás de mí"}],"f":4,"es":"¿Cómo debe actuar cuando, por circular a baja velocidad, provoca la formación de una columna de vehículos?","explain":"Si tu lentitud forma columna detrás: en la primera ocasión te detienes y la dejas pasar. El lento también tiene obligaciones hacia el flujo: 'no tengo por qué mirar atrás' es la actitud que el código sanciona."},{"id":6009,"bg":"По кой от изброените начини може да се обозначи товар, който излиза отзад на най-издадената част на превозното средство с повече от 1 м?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с червен флаг през деня","ok":true,"i":null,"es":"con una bandera roja de día"},{"t":"с червен светлоотразител през нощта","ok":true,"i":null,"es":"con un catadióptrico rojo de noche"},{"t":"с червена светлина през нощта","ok":true,"i":null,"es":"con una luz roja de noche"},{"t":"с бяла светлина през деня","ok":false,"i":null,"es":"con una luz blanca de día"}],"f":4,"es":"¿De cuál de las formas indicadas puede señalizarse una carga que sobresale por detrás de la parte más saliente del vehículo más de 1 m? (3 correctas)","explain":"Carga que sobresale más de 1 m por DETRÁS: bandera roja de día, catadióptrico rojo o luz roja de noche: rojo, el color trasero. La luz blanca es delantera: usarla detrás confundiría el sentido del vehículo."},{"id":6012,"bg":"Товарът не се обозначава, ако излиза отпред на най-издадената част на ППС на разстояние:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 1 м","ok":true,"i":null,"es":"hasta 1 m"},{"t":"до 1,5 м","ok":false,"i":null,"es":"hasta 1.5 m"},{"t":"до 2 м","ok":false,"i":null,"es":"hasta 2 m"},{"t":"до 3 м","ok":false,"i":null,"es":"hasta 3 m"}],"f":4,"es":"La carga no necesita señalizarse si sobresale por DELANTE:","explain":"Por DELANTE la carga no se señaliza hasta 1 m de saliente: es el margen tolerado delantero. Compara los tres umbrales: 1 m delante, 1 m detrás, 0,2 m por los lados: los laterales son los más estrictos porque invaden otros carriles."},{"id":6017,"bg":"Длъжен ли е водачът на МПС да носи документ за сключена застраховка “Гражданска отговорност”?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"¿Está obligado el conductor a llevar el documento del seguro de responsabilidad civil contratado?","explain":"Sí: el documento del seguro de responsabilidad civil se lleva a bordo y se presenta en los controles, junto con el permiso de conducción y el de circulación."},{"id":6018,"bg":"За да участва в движението, МПС задължително трябва да бъде:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"регистрирано","ok":true,"i":null,"es":"matriculado"},{"t":"със сключена застраховка &quot;Каско&quot;","ok":false,"i":null,"es":"con seguro a todo riesgo (\"Casco\") contratado"},{"t":"оборудвано с инструменти за ремонт","ok":false,"i":null,"es":"equipado con herramientas de reparación"}],"f":4,"es":"Para participar en el tráfico, el vehículo de motor obligatoriamente debe estar:","explain":"Para circular el vehículo debe estar MATRICULADO (y con seguro obligatorio de responsabilidad civil). El 'Casco' (todo riesgo) es voluntario, y las herramientas no son requisito legal: la trampa mezcla lo obligatorio con lo opcional."},{"id":5453,"bg":"Извършва ли нарушение водач, който оставя или разпилява по пътя предмети?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да, във всички случаи, когато с това е създадена опасност за движението","ok":true,"i":null,"es":"sí, en todos los casos en que con ello se crea un peligro para el tráfico"},{"t":"да, но само когато в резултат на това е настъпило ПТП","ok":false,"i":null,"es":"sí, pero solo cuando como consecuencia se ha producido un accidente"},{"t":"не, защото водачът не отговаря за превозвания товар","ok":false,"i":null,"es":"no, porque el conductor no responde de la carga transportada"}],"f":4,"es":"¿Comete infracción el conductor que deja o esparce objetos en la vía?","explain":"Sí, siempre que se cree peligro: dejar o esparcir objetos en la vía es infracción por el riesgo mismo, sin esperar a que ocurra el accidente. Y de la carga transportada respondes tú: esa excusa es falsa."},{"id":5465,"bg":"Извършва ли нарушение водач, който откаже на контролните органи да бъде проверен за употреба на алкохол?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"¿Comete infracción el conductor que se niega ante los agentes a ser sometido al control de alcohol?","explain":"Sí: negarse al control de alcoholemia es infracción en sí misma y se trata con la misma dureza que un positivo (retirada del permiso incluida). La negativa no es una escapatoria: es la confesión procesal."},{"id":5481,"bg":"Контролните органи временно отнемат свидетелството за управление на МПС на водач:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"за когото видимо се установи, че не отговаря на медицинските изисквания","ok":true,"i":null,"es":"de quien se aprecie visiblemente que no cumple los requisitos médicos"},{"t":"който управлява МПС с концентрация на алкохол в кръвта над 0,5 на хиляда","ok":true,"i":null,"es":"que conduzca un vehículo con una concentración de alcohol en sangre superior a 0,5 por mil"},{"t":"който поради незнание е извършил немаловажно нарушение на правилата за движение","ok":true,"i":null,"es":"que por desconocimiento haya cometido una infracción no menor de las normas de circulación"},{"t":"когато МПС е технически неизправно","ok":false,"i":null,"es":"cuando el vehículo tiene deficiencias técnicas"}],"f":4,"es":"Las autoridades de control retiran temporalmente el permiso de conducción al conductor: (3 correctas)","explain":"Retiran temporalmente el permiso a quien: visiblemente no cumple los requisitos médicos, supera 0,5‰ de alcohol o comete por desconocimiento una infracción no menor (no sabe conducir con seguridad). Las deficiencias técnicas inmovilizan al VEHÍCULO, no retiran el permiso: esa es la trampa."},{"id":5491,"bg":"Каква мярка се прилага към водач, който поради незнание извърши немаловажно нарушение на правилата за движение?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"временно му се отнема свидетелството за управление","ok":true,"i":null,"es":"se le retira temporalmente el permiso de conducción"},{"t":"налага му се глоба до 300 лева","ok":false,"i":null,"es":"se le impone una multa de hasta 300 leva"},{"t":"временно се спира от движение управляваното от него МПС","ok":false,"i":null,"es":"se inmoviliza temporalmente el vehículo que conduce"}],"f":4,"es":"¿Qué medida se aplica al conductor que, por desconocimiento, comete una infracción no menor de las normas de circulación?","explain":"Retirada temporal del permiso: quien por desconocimiento comete una infracción no menor demuestra que no domina las normas, y la medida apunta a la persona, no al bolsillo (multa) ni al vehículo (inmovilización)."},{"id":5495,"bg":"Какви мерки се прилагат при управление на МПС, което няма застраховка “Гражданска отговорност”?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"временно спиране от движение на МПС и временно отнемане на свидетелството за управление на МПС на водача","ok":true,"i":null,"es":"inmovilización del vehículo Y retirada provisional del permiso"},{"t":"само временно спиране от движение на МПС","ok":false,"i":null,"es":"solo inmovilización del vehículo"},{"t":"само временно отнемане на свидетелството за управление на МПС на водача","ok":false,"i":null,"es":"solo retirada del permiso"}],"f":4,"es":"¿Qué medidas se aplican al conducir un vehículo sin seguro de responsabilidad civil?","explain":"Sin seguro de responsabilidad civil: doble medida: se inmoviliza el vehículo Y se retira provisionalmente el permiso. Circular sin el seguro obligatorio deja a las víctimas potenciales sin cobertura: por eso el golpe es doble."},{"id":5499,"bg":"Когато при нарушение водачът не е съгласен с определената му глоба, може ли да откаже да му бъде съставен фиш?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"Cuando en una infracción el conductor no está de acuerdo con la multa fijada, ¿puede negarse a que se le extienda el boletín?","explain":"Sí: si no estás de acuerdo con la multa del boletín, puedes negarte a que se te extienda: entonces se levanta acta y el caso sigue el procedimiento formal, donde podrás defenderte."},{"id":8288,"bg":"Извършва ли нарушение водач, който се движи без включени светлини?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":4,"es":"¿Comete infracción el conductor que circula sin las luces encendidas?","explain":"Sí: circular sin las luces encendidas es infracción: son obligatorias también de día (diurnas o cortas). Ver y ser visto no es opcional."},{"id":8296,"bg":"При заплащане на глоба за изършено нарушение, наложена с електронен фиш, в 14-дневен срок от получаването на фиша:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"се заплаща 70% от размера на глобата","ok":true,"i":null,"es":"el 70% del importe de la multa"},{"t":"се заплаща пълния размера на глобата","ok":false,"i":null,"es":"el 100% (importe completo)"},{"t":"се заплаща 50% от размера на глобата","ok":false,"i":null,"es":"el 50%"}],"f":4,"es":"Al pagar una multa por sanción electrónica en los primeros 14 días desde su recepción, se paga:","explain":"El 70%: pagar la sanción electrónica en los primeros 14 días desde la recepción da un descuento del 30%. Es el incentivo legal al pago voluntario rápido."},{"id":8297,"bg":"При нарушение, установено и заснето с техническо средство в отсъствието на контролен орган и на нарушител, електронният фиш се издава на собственика на МПС:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато нарушението е извършено от собственика","ok":true,"i":null,"es":"cuando la infracción ha sido cometida por el propietario"},{"t":"когато той не подаде писмена декларация с данни за лицето, извършило нарушението, и копие на свидетелството му за управление","ok":true,"i":null,"es":"cuando no presenta una declaración escrita con los datos de la persona que cometió la infracción y copia de su permiso de conducción"},{"t":"винаги, когато собственикът е предоставил пълномощно на други лица за управление на превозното средство","ok":false,"i":null,"es":"siempre que el propietario haya dado poder a otras personas para conducir el vehículo"}],"f":4,"es":"En una infracción detectada y grabada con un dispositivo técnico, en ausencia de agente y de infractor, el boletín electrónico se emite al propietario del vehículo: (2 correctas)","explain":"El boletín electrónico va al propietario: cuando la infracción la cometió él mismo, o cuando NO presenta declaración escrita identificando al conductor real (con copia de su permiso). El poder notarial a terceros no desvía automáticamente la responsabilidad."},{"id":11411,"bg":"Водач, който се движи в платното за насрещно движение по автомагистрала и/или скоростен път, се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"},{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso de conducir"}],"f":4,"es":"El conductor que circula por el carril contrario en autopista/vía rápida es sancionado con:","explain":"Circular por el carril contrario de autopista o vía rápida: multa Y privación del permiso: es de las infracciones más letales posibles (choque frontal a alta velocidad) y la sanción es la combinada."},{"id":11448,"bg":"Когато контролните органи отнемат табелите с регистрационен номер на МПС, то трябва да бъде транспортирано до място за съхранение:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 2 часа от установяване на нарушението","ok":false,"i":null,"es":"hasta 2 horas tras el establecimiento de la infracción"},{"t":"до 12 часа от установяване на нарушението","ok":true,"i":null,"es":"hasta 12 horas"},{"t":"до 24 часа от установяване на нарушението","ok":false,"i":null,"es":"hasta 24 horas"}],"f":4,"es":"Cuando las autoridades retiran las matrículas de un vehículo, debe ser trasladado a depósito:","explain":"Hasta 12 horas: es el plazo para trasladar a depósito el vehículo al que las autoridades retiraron las matrículas. Ni 2 ni 24: el 12 es el número que pide el banco."},{"id":11501,"bg":"Когато нарушението е установено и заснето с автоматизирано техническо средство в отсъствието на контролен орган и на нарушител, може да бъде наложена глоба с електронен фиш:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":4,"es":"Cuando la infracción se detecta y graba con un dispositivo automatizado, en ausencia de agente y de infractor, puede imponerse una multa con boletín electrónico:","explain":"Correcto: la infracción grabada por dispositivo automatizado, sin agente ni infractor presentes, se sanciona con boletín electrónico (фиш). Es la base legal de los radares automáticos."},{"id":5305,"bg":"При извършването на кои две от посочените нарушения настъпват най-много пътнотранспортни произшествия:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"движението с несъобразена скорост","ok":true,"i":null,"es":"circular a una velocidad inadecuada"},{"t":"отнемането на предимство","ok":true,"i":null,"es":"no respetar la prioridad"},{"t":"неправилното теглене","ok":false,"i":null,"es":"el remolcado incorrecto"},{"t":"неправилното спиране за престой","ok":false,"i":null,"es":"la parada incorrecta"}],"f":4,"es":"¿Con cuáles dos de las infracciones indicadas ocurren más accidentes de tráfico?: (2 correctas)","explain":"Las dos infracciones que más accidentes causan: velocidad inadecuada y no respetar la prioridad. El remolcado o la parada incorrectos causan incidentes, pero no dominan la estadística."},{"id":5308,"bg":"Данните от статистиката показват, че най-голям брой пътнотранспортни произшествия настъпват:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"в градовете","ok":true,"i":null,"es":"en las ciudades"},{"t":"в селата","ok":false,"i":null,"es":"en los pueblos"},{"t":"извън населените места","ok":false,"i":null,"es":"fuera de poblado"},{"t":"на автомагистралите","ok":false,"i":null,"es":"en las autopistas"}],"f":4,"es":"Los datos estadísticos muestran que el mayor número de accidentes de tráfico ocurre:","explain":"En las CIUDADES: más intersecciones, peatones, semáforos y conflictos por kilómetro. Las autopistas, contra la intuición, son las vías con menos accidentes por su tráfico ordenado sin cruces."},{"id":5309,"bg":"Данните от статистиката показват, че най-голям брой пътнотранспортни произшествия настъпват:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"през деня","ok":true,"i":null,"es":"durante el día"},{"t":"когато е тъмно","ok":false,"i":null,"es":"cuando está oscuro"},{"t":"при изкуствено осветление","ok":false,"i":null,"es":"con iluminación artificial"},{"t":"в сумрак","ok":false,"i":null,"es":"al anochecer (crepúsculo)"}],"f":4,"es":"Los datos estadísticos muestran que el mayor número de accidentes de tráfico ocurre:","explain":"Durante el DÍA: simplemente porque es cuando circula la inmensa mayoría del tráfico. De noche los accidentes son proporcionalmente más graves, pero en número absoluto gana el día."},{"id":5339,"bg":"При пътнотранспортно произшествие, независимо дали е участник в произшествието или не, водачът е длъжен:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да вземе мерки за безопасността на движението","ok":true,"i":null,"es":"tomar medidas para la seguridad del tráfico"},{"t":"да сигнализара мястото на произшествието","ok":true,"i":null,"es":"señalizar el lugar del accidente"},{"t":"да окаже помощ на пострадалите","ok":true,"i":null,"es":"prestar ayuda a los heridos"},{"t":"да окаже съдействие за отстраняване на повредите по автомобилите","ok":false,"i":null,"es":"colaborar en la reparación de los daños de los automóviles"}],"f":4,"es":"En un accidente de tráfico, esté o no implicado en él, el conductor está obligado a: (3 correctas)","explain":"Esté o no implicado: asegurar el tráfico, señalizar el lugar y ayudar a los heridos: los tres deberes universales ante un accidente. 'Colaborar en la reparación de los coches' no es obligación de nadie (y destruiría evidencias)."},{"id":5358,"bg":"Когато по телефона съобщавате за произшествие, ще бъдете най-полезни ако максимално ясно и точно подавате информацията за:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"своето име","ok":true,"i":null,"es":"su nombre"},{"t":"мястото на произшествието и вида на произшествието","ok":true,"i":null,"es":"el lugar y el tipo del accidente"},{"t":"броя на пострадалите хора","ok":true,"i":null,"es":"el número de personas heridas"},{"t":"собствениците на превозните средства","ok":false,"i":null,"es":"los propietarios de los vehículos"}],"f":4,"es":"Al comunicar un accidente por teléfono, será más útil si transmite con la máxima claridad y precisión la información sobre: (3 correctas)","explain":"Al llamar al 112: tu nombre, el LUGAR y tipo del accidente y el número de heridos: lo que los servicios necesitan para dimensionar la respuesta. La propiedad de los vehículos no salva a nadie."},{"id":11422,"bg":"Водач, който пристигне на място, където е станало пътнотранспортно произшествие и има пострадали хора е задължен:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да вземе мерки за осигуряване безопасността на движението","ok":true,"i":null,"es":"tomar medidas para garantizar la seguridad del tráfico"},{"t":"да окаже помощ на пострадалите, ако това не представлява опасност за него","ok":true,"i":null,"es":"prestar ayuda a los heridos, si no supone un peligro para él"},{"t":"да уведоми органите на МВР или администрацията на общината, на чиято територия е станало","ok":true,"i":null,"es":"avisar a la policía (MVR) o a la administración del municipio en cuyo territorio ha ocurrido"},{"t":"да вземе мерки за запазване на следите от произшествието","ok":false,"i":null,"es":"tomar medidas para conservar las huellas del accidente"}],"f":4,"es":"El conductor que llega a un lugar donde ha ocurrido un accidente de tráfico con heridos está obligado a: (3 correctas)","explain":"Quien llega a un accidente con heridos: asegura el tráfico, ayuda a los heridos si no corre peligro y avisa a la policía o al municipio. Conservar las huellas es deber de los IMPLICADOS, no del que llega a ayudar: ese matiz es la trampa."},{"id":11427,"bg":"Когато при ПТП само с имуществени вреди има съгласие на участниците относно обстоятелствата свързани с него, те:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"преместват превозните средства, така че да не възпрепятстват движението","ok":true,"i":null,"es":"apartan los vehículos para no obstaculizar el tráfico"},{"t":"попълват двустранен констативен протокол за ПТП","ok":true,"i":null,"es":"rellenan un parte amistoso de accidente"},{"t":"уведомяват полицията","ok":false,"i":null,"es":"avisan a la policía"},{"t":"подават информация за произшествието на телефон 112","ok":false,"i":null,"es":"informan del accidente al teléfono 112"}],"f":4,"es":"Cuando en un accidente solo con daños materiales los implicados están de acuerdo sobre sus circunstancias, ellos: (2 correctas)","explain":"Solo daños materiales y acuerdo entre implicados: apartan los vehículos para no estorbar y rellenan el parte amistoso. Ni policía ni 112: el sistema quiere reservar los servicios para donde hay heridos o conflicto."},{"id":11429,"bg":"Водач, който е участник в ПТП, съобразно необходимостта, уведомява за произшествието:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"органите за контрол на МВР, когато при произшествието има пострадали хора","ok":true,"i":null,"es":"a la policía (MVR), cuando en el accidente hay personas heridas"},{"t":"собствениците на имуществото, което е повредено в резултат на произшествието","ok":true,"i":null,"es":"a los propietarios de los bienes dañados como consecuencia del accidente"},{"t":"органите за контрол на МВР, когато няма пострадали хора, но между участниците в произшествието няма съгласие относно обстоятелствата, свързани с него","ok":true,"i":null,"es":"a la policía (MVR), cuando no hay heridos pero los implicados no están de acuerdo sobre las circunstancias del accidente"},{"t":"Изпълнителна агенция „Автомобилна администрация”","ok":false,"i":null,"es":"a la Agencia Ejecutiva \"Administración del Automóvil\""}],"f":4,"es":"El conductor implicado en un accidente, según la necesidad, avisa del accidente: (3 correctas)","explain":"El implicado avisa: a la policía cuando hay heridos, a la policía cuando no hay acuerdo sobre las circunstancias, y a los propietarios de los bienes dañados. La Agencia 'Administración del Automóvil' no pinta nada en un accidente: es el distractor burocrático."},{"id":5248,"bg":"Кой от пътните знаци предупреждава за опасен пътен банкет?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334667.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21147.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21148.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21149.png","es":""}],"f":4,"es":"¿Cuál de las señales advierte de arcén peligroso?","explain":"El triangulo con el coche cayendo al borde indica arcen inestable o con desnivel peligroso."},{"id":6187,"bg":"Кой пътен знак ви задължава да се движите само направо след него?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43129.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43130.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43131.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43132.png","es":""}],"f":4,"es":"¿Qué señal te obliga a circular solo recto después de ella?","explain":"Circulo azul con flecha recta = circulacion obligatoria solo hacia adelante."},{"id":5812,"bg":"Значението на кой от пътните знаци е “Препоръчителна скорост”?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334712.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53730.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334713.png","es":""}],"f":4,"es":"¿Cuál de las señales de tráfico significa 'Velocidad recomendada'?","explain":"La velocidad recomendada (senal azul con numero) no es obligatoria pero indica la velocidad optima para ese tramo. A diferencia de la limitacion de velocidad (roja), esta es solo orientativa."},{"id":5328,"bg":"Кое от показаните превозни средства е автомобил?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/129001.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/129002.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/129003.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/129004.png","es":""}],"f":4,"es":"¿Cuál de los vehículos mostrados es un automóvil? (3 correctas)","explain":"Automovil = vehiculo de motor, 4+ ruedas, hasta 3500 kg masa maxima. Diferencialo de motos, tractores y maquinaria agricola."},{"id":6195,"bg":"На кой от пътните знаци значението е “Преминаване отляво на знака”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45610.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334696.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45612.png","es":""}],"f":4,"es":"¿En cuál de las señales el significado es 'Paso por la izquierda de la señal'?","explain":"Flecha que indica pasar por la izquierda del poste o isla de trafico."},{"id":6049,"bg":"Когато при спиране подава сигнал с ръка, водачът на двуколесното ППС сигнализира чрез:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27898.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27899.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27900.png","es":""}],"f":4,"es":"Cuando al frenar da señal con el brazo, el conductor del vehículo de dos ruedas señaliza con:","explain":"El brazo izquierdo extendido hacia abajo con la palma hacia atras indica frenada o parada."},{"id":5268,"bg":"Кой от пътните знаци предупреждава за приближаване към кръстовище с кръгово движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334676.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25515.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25516.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25517.png","es":""}],"f":4,"es":"¿Cuál de las señales advierte de la proximidad de una glorieta?","explain":"Triangulo con circulos de flechas en sentido horario = glorieta proxima."},{"id":11818,"bg":"С кой от опознавателните знаци се обозначават товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334742.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23074.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334748.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334746.png","es":""}],"f":4,"es":"¿Con cuál de los signos distintivos se identifican los camiones con masa máxima admisible superior a 3500 kg y longitud superior a 7 metros? (2 correctas)","explain":"Placa reflectante trasera para camiones largos y pesados. Obligatoria para mejorar visibilidad."},{"id":5979,"bg":"Значението на кой от пътните знаци е „Забранено е влизането на товарни автомобили с допустима максимална маса над 5 т”","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51729.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51730.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334751.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334708.png","es":""}],"f":4,"es":"¿Cuál de las señales significa 'Prohibida la entrada de camiones con masa máxima admisible superior a 5 t'?","explain":"Circulo rojo con camion y el numero 5 indica prohibicion para camiones de mas de 5 toneladas."},{"id":11817,"bg":"С кой от опознавателните знаци се обозначават товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334750.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23054.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334745.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334748.png","es":""}],"f":4,"es":"¿Con cuál de los signos distintivos se identifican los camiones con masa máxima admisible superior a 3500 kg y longitud superior a 7 metros? (2 correctas)","explain":"Placa reflectante trasera identificativa. Los camiones largos deben llevarla en la parte trasera."},{"id":5825,"bg":"Значението на кой от пътните знаци е “Задължителна минимална скорост”?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334713.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334712.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53730.png","es":""}],"f":4,"es":"¿Cuál de las señales de tráfico significa 'Velocidad mínima obligatoria'?","explain":"La velocidad minima obligatoria (circulo azul) obliga a circular al menos a esa velocidad. Se usa en autopistas para garantizar fluidez."},{"id":5235,"bg":"Кой от знаците сигнализира, че пътят, по който се движите, е с предимство?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19752.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19753.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19754.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19755.png","es":""}],"f":4,"es":"¿Cuál de las señales indica que la vía por la que circulas es preferente?","explain":"El rombo amarillo con borde blanco = via con prioridad actual. Lo llevas mientras circulas por ella."},{"id":5250,"bg":"Кой от пътните знаци предупреждава за стеснение на платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"334669","es":""},{"t":"","ok":true,"i":"21285","es":""},{"t":"","ok":false,"i":"21286","es":""},{"t":"","ok":true,"i":"334668","es":""}],"f":4,"es":"¿Cuál de las señales advierte de estrechamiento de la calzada? (3 correctas)","explain":"Flechas convergentes = estrechamiento. La que pierde espacio indica el lado afectado."},{"id":5271,"bg":"Кой от пътните знаци предупреждава за приближаване към кръстовище?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"25625"},{"t":"","ok":true,"es":"","i":"334673"},{"t":"","ok":true,"es":"","i":"23811"},{"t":"","ok":false,"es":"","i":"25626"}],"f":4,"es":"¿Cuál de las señales advierte de la proximidad de una intersección? (2 correctas)","explain":"Triangulos con bifurcacion = interseccion proxima. Prepara para posible ceder el paso."},{"id":5794,"bg":"Кой от пътните знаци забранява движението със скорост, по-висока от означената?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53730.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53731.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53732.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334711.png","es":""}],"f":4,"es":"¿Cuál de las señales de tráfico prohíbe circular a velocidad superior a la indicada?","explain":"La limitacion de velocidad maxima es un circulo rojo con el numero en blanco. Diferenciala de la velocidad recomendada (azul) y la minima (circulo azul sin tachado)."},{"id":5480,"bg":"При светване на кой от символите върху арматурното табло има опасност от сериозна повреда в двигателя, ако не преустановите движението?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334684.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29956.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334683.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29958.png","es":""}],"f":4,"es":"¿Con el encendido de cuál de los símbolos del cuadro de instrumentos existe peligro de avería grave del motor si no detiene la marcha?","explain":""},{"id":5326,"bg":"Кое от показаните превозни средства е автомобил?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/19251.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128930.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128931.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128932.png","es":""}],"f":4,"es":"¿Cuál de los vehículos mostrados es un automóvil? (3 correctas)","explain":"Automovil: vehiculo de motor de 4+ ruedas hasta 3500 kg. Excluye motos, tractores y maquinaria."},{"id":5282,"bg":"Кой от пътните знаци предупреждава за приближаване към място, където през платното за движение преминават пешеходци?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334677.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46089.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27243.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27244.png","es":""}],"f":4,"es":"¿Cuál de las señales advierte de la proximidad de un lugar donde los peatones cruzan la calzada?","explain":"Triangulo con peatones = paso de peatones proximo. Reduce velocidad y prepara para ceder."},{"id":5256,"bg":"Кой знак предупреждава за неравности по платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23402.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23403.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334749.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23405.png","es":""}],"f":4,"es":"¿Qué señal advierte de irregularidades en la calzada? (2 correctas)","explain":"Triangulo con bumps = firme irregular, badenes artificiales o deterioro de la calzada."},{"id":5300,"bg":"Съединителят е предназначен:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"да прекъсва силовата връзка между двигателя и предавателната кутия","ok":true,"i":null,"es":"interrumpir la conexión entre el motor y la caja de cambios"},{"t":"да осъществява връзка между двигателя и карданното предаване","ok":false,"i":null,"es":"conectar el motor con la transmisión cardán"},{"t":"да съединява елементите на трансмисията с рамата","ok":false,"i":null,"es":"conectar los elementos de la transmisión con el chasis"},{"t":"да прекъсва връзката между предавателната кутия и карданното предаване","ok":false,"i":null,"es":"interrumpir la conexión entre la caja de cambios y el cardán"}],"f":3,"es":"El embrague sirve para:","explain":"El embrague interrumpe la conexión entre el MOTOR y la CAJA DE CAMBIOS: permite cambiar de marcha y arrancar suavemente. Las otras opciones mezclan elementos de la transmisión que el embrague no une ni separa."},{"id":5454,"bg":"При отрицателни температури на околния въздух протекторът на летните автомобилни гуми:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"се втвърдява и рязко намалява сцеплението на гумата с пътя","ok":true,"i":null,"es":"se endurece y reduce bruscamente la adherencia del neumático a la vía"},{"t":"омеква и се износва по-бързо","ok":false,"i":null,"es":"se ablanda y se desgasta más rápido"},{"t":"не се влияе от температурата","ok":false,"i":null,"es":"no se ve afectado por la temperatura"},{"t":"променя цвета си","ok":false,"i":null,"es":"cambia de color"}],"f":3,"es":"Con temperaturas ambientales bajo cero, la banda de rodadura de los neumáticos de verano:","explain":"Bajo cero, la goma de verano se ENDURECE y pierde bruscamente adherencia: su compuesto está diseñado para calor. Por eso los neumáticos de invierno existen: su goma sigue blanda en frío."},{"id":5457,"bg":"Когато през зимата няма сняг, използването на зимни гуми не е необходимо.","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"правилно","ok":false,"i":null,"es":"correcto"},{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"}],"f":3,"es":"Cuando en invierno no hay nieve, no es necesario usar neumáticos de invierno.","explain":"INCORRECTO: el neumático de invierno no es solo para nieve: su ventaja es el COMPUESTO que se mantiene flexible con frío. Bajo cero, en seco, el de verano ya ha perdido adherencia aunque no haya ni un copo."},{"id":5462,"bg":"Използването на зимни гуми през летния сезон, води до:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"увеличаване на разхода на гориво","ok":true,"i":null,"es":"aumentar el consumo de combustible"},{"t":"по-бързо износване на гумите","ok":true,"i":null,"es":"desgaste más rápido de los neumáticos"},{"t":"намаляване на разхода на гориво","ok":false,"i":null,"es":"menor consumo de combustible"}],"f":3,"es":"Usar neumáticos de invierno en verano provoca: (2 correctas)","explain":"Neumáticos de invierno en verano: más consumo y desgaste acelerado: su goma blanda se deshace con el calor y su resistencia a la rodadura es mayor. No hay ventaja alguna en usarlos fuera de temporada."},{"id":11880,"bg":"Допустимата минимална дълбочина на протектора на гумите на автомобилите през периода от 1 март до 15 ноември е:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"1,6 mm","ok":true,"i":null,"es":"1,6 mm"},{"t":"0,5 mm","ok":false,"i":null,"es":"0,5 mm"},{"t":"1,0 mm","ok":false,"i":null,"es":"1,0 mm"},{"t":"3,0 mm","ok":false,"i":null,"es":"3,0 mm"}],"f":3,"es":"La profundidad mínima admisible de la banda de rodadura de los neumáticos de los automóviles en el período del 1 de marzo al 15 de noviembre es:","explain":"1,6 mm: profundidad mínima del dibujo en el período de verano (1 marzo - 15 noviembre). El par 1,6/4,0 (verano/invierno) es de los números más preguntados del bloque técnico."},{"id":5436,"bg":"При спускане по наклон честото и продължително използване на спирачките:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"влошава ефективността им","ok":true,"i":null,"es":"la eficacia de los frenos EMPEORA"},{"t":"подобрява ефективността им","ok":false,"i":null,"es":"la eficacia MEJORA"},{"t":"не влияе на ефективността им","ok":false,"i":null,"es":"no tiene efecto"}],"f":3,"es":"Al bajar pendientes largas con frenos continuos y prolongados:","explain":"EMPEORA: el frenado continuo y prolongado en bajadas largas sobrecalienta frenos y líquido (fading): el pedal pierde eficacia justo cuando más lo necesitas. Por eso en pendiente se baja con freno motor y marcha corta."},{"id":6158,"bg":"Честата употреба на спирачки води до:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"загуба на енергия","ok":true,"i":null,"es":"pérdida de energía"},{"t":"увеличаване на разхода на гориво","ok":true,"i":null,"es":"aumentar el consumo de combustible"},{"t":"износване на автомобилните гуми","ok":true,"i":null,"es":"desgaste de los neumáticos"},{"t":"ускорено износване на окачването на автомобила","ok":false,"i":null,"es":"desgaste acelerado de la suspensión del automóvil"}],"f":3,"es":"El uso frecuente de los frenos provoca: (3 correctas)","explain":"Frenar a menudo: pierdes energía (la velocidad que pagaste en combustible se va en calor), consumes más (reacelerar) y desgastas neumáticos. La suspensión no es la víctima del freno: ese es el distractor."},{"id":11656,"bg":"Светването на този символ върху арматурното табло означава, че:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801960.png","v":null,"a":[{"t":"има опасност от блокиране на двигателя","ok":true,"i":null,"es":"existe el peligro de que el motor se gripe"},{"t":"се увеличава разходът на гориво","ok":false,"i":null,"es":"aumenta el consumo de combustible"},{"t":"има ускорено изгаряне на маслото в картера на двигателя","ok":false,"i":null,"es":"el aceite del cárter del motor se quema aceleradamente"}],"f":3,"es":"El encendido de este símbolo en el cuadro de instrumentos significa que:","explain":""},{"id":5146,"bg":"Участници в движението са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"водачите","ok":true,"i":null,"es":"los conductores"},{"t":"пътниците","ok":true,"i":null,"es":"los pasajeros"},{"t":"автомобилите","ok":false,"i":null,"es":"los automóviles"},{"t":"двуколесните превозни средства","ok":false,"i":null,"es":"los vehículos de dos ruedas"}],"f":3,"es":"Son participantes en el tráfico: (2 correctas)","explain":"Participantes en el tráfico son PERSONAS: conductores y pasajeros (también peatones). Los automóviles y los vehículos de dos ruedas son objetos: cosas que las personas usan, no participantes."},{"id":5181,"bg":"Трамваят е релсово превозно средство, което:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"се приравнява към групата на пътните превозни средства","ok":true,"i":null,"es":"se equipara al grupo de los vehículos"},{"t":"не се счита за моторно превозно средство","ok":true,"i":null,"es":"no se considera vehículo de motor"},{"t":"се приравнява към автомобилите","ok":false,"i":null,"es":"se equipara a los automóviles"},{"t":"се приравнява към тролейбусите","ok":false,"i":null,"es":"se equipara a los trolebuses"}],"f":3,"es":"El tranvia es un vehículo ferroviario que: (2 correctas)","explain":"El tranvía se equipara a los VEHÍCULOS (ППС) y NO es vehículo de motor (МПС): esa es su doble clave legal. No se equipara a automóviles ni a trolebuses, que sí son vehículos de motor."},{"id":5204,"bg":"&quot;Допустима максимална маса&quot; на превозното средство е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"разрешената от компетентните органи максимална маса в натоварено състояние","ok":true,"i":null,"es":"la masa máxima en carga autorizada por las autoridades competentes"},{"t":"максималната маса в натоварено състояние, посочена от производителя","ok":false,"i":null,"es":"la masa máxima en carga indicada por el fabricante"},{"t":"максималната маса на превозното средство без товар","ok":false,"i":null,"es":"la masa máxima del vehículo sin carga"},{"t":"разрешената товароносимост на превозното средство","ok":false,"i":null,"es":"la capacidad de carga autorizada del vehículo"}],"f":3,"es":"La 'masa máxima admisible' del vehículo es:","explain":"La masa máxima admisible es la máxima EN CARGA autorizada por las autoridades competentes: es un límite legal-administrativo. No es la cifra del fabricante, ni la masa en vacío, ni la capacidad de carga."},{"id":5236,"bg":"„Граница на платното за движение” е линията, очертана или не с пътна маркировка, която отделя платното за движение от другите конструктивни елементи на пътното платно.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":3,"es":"'Límite de calzada' es la línea, marcada o no con marcado vial, que separa la calzada de los otros elementos constructivos del firme.","explain":"Correcto: esa ES la definición legal del límite de calzada: la línea (marcada o no) que separa la calzada de los demás elementos del firme (arcenes, aceras)."},{"id":5238,"bg":"“Граница на платното за движение” е линията, очертана или не, с пътна маркировка, която отделя пътните платна едно от друго.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":3,"es":"'Límite de calzada' es la línea, marcada o no con marcado vial, que separa las plataformas entre si.","explain":"INCORRECTO: el límite de calzada separa la calzada de los otros elementos del firme, no 'las plataformas entre sí'. Es la versión trampa de la definición: cambia el objeto separado."},{"id":5297,"bg":"Видимостта е намалена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"мъгла","ok":true,"i":null,"es":"niebla"},{"t":"проливен дъжд","ok":true,"i":null,"es":"lluvia torrencial"},{"t":"силен снеговалеж","ok":true,"i":null,"es":"nevada intensa"},{"t":"завой","ok":false,"i":null,"es":"curva"}],"f":3,"es":"La visibilidad esta reducida en: (3 correctas)","explain":"Visibilidad REDUCIDA: niebla, lluvia torrencial, nevada intensa: fenómenos atmosféricos. La curva es visibilidad LIMITADA (geometría de la vía). Domina este par de conceptos: el banco lo pregunta de las dos formas."},{"id":5312,"bg":"На показаната фигура видимостта е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20510.png","v":null,"a":[{"t":"намалена","ok":true,"i":null,"es":"reducida"},{"t":"ограничена","ok":false,"i":null,"es":"limitada"}],"f":3,"es":"En la figura mostrada la visibilidad está:","explain":"REDUCIDA = no puedes ver bien por condiciones meteorologicas o ambientales (niebla, lluvia, humo)."},{"id":5316,"bg":"Видимостта е ограничена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"стръмни наклони","ok":true,"i":null,"es":"pendientes pronunciadas"},{"t":"препятствия, които пречат на видимостта","ok":true,"i":null,"es":"obstáculos que impiden la visibilidad"},{"t":"крайпътни обекти, които ограничават видимостта","ok":true,"i":null,"es":"objetos junto a la vía que limitan la visibilidad"},{"t":"запрашеност","ok":false,"i":null,"es":"polvo en suspensión"}],"f":3,"es":"La visibilidad esta limitada en: (3 correctas)","explain":"Visibilidad limitada: pendientes, obstáculos y objetos junto a la vía: cosas físicas que tapan. El polvo en suspensión es atmosférico: visibilidad REDUCIDA. Mismo patrón de siempre."},{"id":8247,"bg":"Към категория АМ принадлежат превозни средства с конструктивна максимална скорост до 45 km/h и двигатели с вътрешно горене с работен обем до 50 cm3, които са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"с две колела","ok":true,"i":null,"es":"dos ruedas"},{"t":"с три колела","ok":true,"i":null,"es":"tres ruedas"},{"t":"с четири колела и маса без товар не повече от 350 kg","ok":true,"i":null,"es":"cuatro ruedas y masa sin carga no superior a 350 kg"},{"t":"с четири колела и маса без товар не повече от 400 kg","ok":false,"i":null,"es":"cuatro ruedas y masa sin carga no superior a 400 kg"}],"f":3,"es":"A la categoría AM pertenecen vehículos con velocidad máxima hasta 45 km/h y motor... con: (3 correctas)","explain":"Categoría AM: dos ruedas, tres ruedas y cuatriciclos LIGEROS de hasta 350 kg en vacío (y 45 km/h). El límite de 400 kg no corresponde a AM: ya entra en B1: ojo al número exacto."},{"id":8249,"bg":"Триколесни моторни превозни средства с мощност по-голяма от 15 kW се управляват с правоспособност за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"категория АМ","ok":false,"i":null,"es":"categoría AM"},{"t":"категория А1","ok":false,"i":null,"es":"categoría A1"},{"t":"категория А","ok":true,"i":null,"es":"categoría A"},{"t":"категория В1","ok":false,"i":null,"es":"categoría B1"}],"f":3,"es":"Los vehículos de motor de tres ruedas con potencia superior a 15 kW se conducen con permiso de:","explain":"Categoría A: los triciclos de motor con potencia SUPERIOR a 15 kW exigen el permiso completo de motocicletas. A1 cubre triciclos solo hasta 15 kW, y AM/B1 se quedan muy por debajo."},{"id":11579,"bg":"Коя част от пътя на показаната схема е означена с буквата „B”?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1086155016.png","v":null,"a":[{"t":"платното за движение","ok":true,"i":null,"es":"la calzada"},{"t":"пътното платно","ok":false,"i":null,"es":"la plataforma vial (calzada + arcenes)"},{"t":"пътна лента","ok":false,"i":null,"es":"carril"}],"f":3,"es":"¿Qué parte de la carretera del esquema está indicada con la letra 'В'?","explain":"B = calzada (platno za dvizhenie) = la parte por donde circulan los vehiculos. Sin aceras ni arcenes."},{"id":11676,"bg":"Конструктивната максимална скорост на мотопеда е не по-голяма от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"45 km/h","ok":true,"i":null,"es":"45 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"f":3,"es":"La velocidad máxima constructiva del ciclomotor no supera:","explain":"45 km/h: la velocidad máxima constructiva que define al ciclomotor, junto con los 50 cm³. Por encima ya es motocicleta."},{"id":11808,"bg":"На водач с правоспособност за категория ВЕ е разрешено да управлява състав от ППС с теглещо превозно средство от категория В и ремарке с допустима максимална маса не повече от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"3500 kg","ok":true,"i":null,"es":"3500 kg"},{"t":"2500 kg","ok":false,"i":null,"es":"2500 kg"},{"t":"1250 kg","ok":false,"i":null,"es":"1250 kg"},{"t":"750 kg","ok":false,"i":null,"es":"750 kg"}],"f":3,"es":"El conductor con permiso BE puede conducir un tren de vehículos con tractor categoría B y remolque con masa máxima admisible no superior a:","explain":"3.500 kg: el BE cubre tractor categoría B con remolque de hasta 3.500 kg de masa máxima admisible. Hasta 750 kg de remolque ni siquiera hace falta BE: basta B: por eso existe la categoría."},{"id":11811,"bg":"Автомобилите от категория В1, предназначени за превоз на пътници, имат маса без товар не по-голяма от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"400 kg","ok":true,"i":null,"es":"400 kg"},{"t":"550 kg","ok":false,"i":null,"es":"550 kg"},{"t":"750 kg","ok":false,"i":null,"es":"750 kg"},{"t":"900 kg","ok":false,"i":null,"es":"900 kg"}],"f":3,"es":"Los automóviles categoría B1 destinados al transporte de pasajeros tienen una masa en vacio no superior a:","explain":"400 kg: masa máxima EN VACÍO de los B1 de pasajeros. Los de mercancías llegan a 550 kg: el par 400/550 según finalidad es la distinción que el banco pregunta en ambos sentidos."},{"id":12073,"bg":"Автомобилите със специално предназначение:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"притежават специфични технически характеристики, които им позволяват да изпълняват функции, изискващи специална конфигурация или оборудване","ok":true,"i":null,"es":"tienen características técnicas específicas que les permiten realizar funciones que exigen configuración o equipamiento especial"},{"t":"са обозначени с жълта проблясваща светлина","ok":false,"i":null,"es":"están señalizados con luz amarilla intermitente"},{"t":"сигнализират със синя или червена проблясваща светлина","ok":false,"i":null,"es":"señalizan con luz azul o roja intermitente"},{"t":"ползват специален режим на движение","ok":false,"i":null,"es":"utilizan un régimen especial de circulación"}],"f":3,"es":"Los automóviles de finalidad especial:","explain":"Los automóviles de finalidad especial se definen por sus características técnicas y equipamiento específicos (grúas, hormigoneras, talleres móviles). Las luces amarillas, azules o rojas y el régimen especial definen OTRAS categorías: esa es la confusión que explota la pregunta."},{"id":5164,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20124.png","v":null,"a":[{"t":"че за използването на пътя се изисква платена винетна такса","ok":true,"i":null,"es":"que para usar la vía se exige el pago de viñeta"},{"t":"двупосочно движение след знака","ok":false,"i":null,"es":"circulación en ambos sentidos después de la señal"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"броя на пътните ленти за движение в една посока","ok":false,"i":null,"es":"el número de carriles de circulación en un sentido"}],"f":3,"es":"Esta señal señaliza:","explain":"Se requiere vineta para usar la via. Obligatorio tenerla antes de entrar."},{"id":5169,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334665.png","v":null,"a":[{"t":"последователни опасни завои, първият от които е наляво","ok":true,"i":null,"es":"curvas peligrosas sucesivas, la primera hacia la izquierda"},{"t":"последователност от стръмни изкачвания и спускания","ok":false,"i":null,"es":"una sucesión de subidas y bajadas pronunciadas"},{"t":"опасност от хлъзгане","ok":false,"i":null,"es":"peligro de deslizamiento"},{"t":"препятствие, което трябва да бъде заобиколено отляво","ok":false,"i":null,"es":"obstáculo que debe rodearse por la izquierda"}],"f":3,"es":"Esta señal advierte de:","explain":"Advierte de CURVAS SUCESIVAS, la primera de ellas HACIA LA IZQUIERDA.\n\nLA SEÑAL. Triángulo rojo con el trazo en forma de S, cuya parte de ABAJO se dobla hacia la izquierda.\n\nES LA IMAGEN ESPEJO DE LA 5171. Las dos dibujan curvas encadenadas y solo cambia el sentido de la primera. Lee el trazo de abajo arriba, como si condujeras el dibujo: la parte de abajo eres tú.\n\nQUÉ CAMBIA RESPECTO A UNA CURVA SUELTA. Entre curvas encadenadas no hay recta para corregir la velocidad, así que hay que entrar a una velocidad que sirva para todas. Y adelantar dentro del tramo es especialmente malo: la visibilidad se cierra en cada cambio de sentido.\n\n«SUBIDAS Y BAJADAS PRONUNCIADAS» dibuja un perfil de montaña, no una S en planta.\n\n«PELIGRO DE DESLIZAMIENTO» es el coche con las trazas de derrape.\n\n«OBSTÁCULO QUE DEBE RODEARSE POR LA IZQUIERDA» sería un círculo azul con flecha: obligación, no aviso.\n\nCLAVE: el par 5169 y 5171 solo se distingue por hacia dónde se dobla el trazo inferior. Izquierda o derecha, y con eso está resuelto.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5188,"bg":"При навлизане в завой, с увеличаването на скоростта, устойчивостта на превозното средство се подобрява.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":3,"es":"Al entrar en una curva, al aumentar la velocidad la estabilidad del vehículo mejora.","explain":"INCORRECTO: más velocidad en la curva significa MENOS estabilidad, no más: la fuerza centrífuga crece con el cuadrado de la velocidad. La afirmación invierte la física."},{"id":5200,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21435.png","v":null,"a":[{"t":"Внимание! Други опасности","ok":true,"i":null,"es":"¡Atención! Otros peligros"},{"t":"Внимание! Пешеходна пътека","ok":false,"i":null,"es":"¡Atención! Paso de peatones"},{"t":"Внимание! Спри!","ok":false,"i":null,"es":"¡Atención! ¡Detente!"},{"t":"Внимание! Деца","ok":false,"i":null,"es":"¡Atención! Niños"}],"f":3,"es":"El significado de esta señal es:","explain":"«¡Atención! Otros peligros» — «Внимание! Други опасности».\n\nLA SEÑAL. Triángulo rojo con un signo de exclamación. Es la señal comodín del grupo de peligro: se usa cuando el riesgo no encaja en ninguno de los pictogramas existentes.\n\nQUÉ TE PIDE. Reducir la velocidad y prepararte para algo que aún no sabes qué es. Casi siempre viene acompañada de una tablilla que lo explica — obras, animales, gravilla, hundimiento — y esa tablilla es lo primero que hay que leer.\n\n«¡ATENCIÓN! ¡DETENTE!» es el distractor más peligroso porque comparte la palabra «Внимание». Pero «Внимание, спри!» es el nombre del ÁMBAR FIJO del semáforo y del brazo vertical del agente, no de ninguna señal vertical. Esa etiqueta pertenece a otra familia entera.\n\n«PASO DE PEATONES» y «NIÑOS» tienen sus propios pictogramas dentro del mismo triángulo. Aquí no hay dibujo, solo la exclamación.\n\nCLAVE: signo de exclamación = peligro sin nombre. Busca la tablilla debajo; si no la hay, modera y observa. Y no confundas «Внимание! Други опасности» con «Внимание, спри!»: la primera avisa, la segunda ordena parar.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5259,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23760.png","v":null,"a":[{"t":"предупреждава за кръстовище с път отляво, който е без предимство","ok":true,"i":null,"es":"advierte de una intersección con una vía por la izquierda sin prioridad"},{"t":"указва задължителна посока за преминаване през следващото кръстовище","ok":false,"i":null,"es":"indica el sentido obligatorio de paso en la próxima intersección"},{"t":"сигнализира за пресичане на равнозначни пътища","ok":false,"i":null,"es":"señaliza un cruce de vías de igual rango"},{"t":"сигнализира място за спиране край пътя","ok":false,"i":null,"es":"señaliza zona de parada junto a la vía"}],"f":3,"es":"Esta señal:","explain":"Advierte de una INTERSECCIÓN CON UNA VÍA POR LA IZQUIERDA SIN PRIORIDAD.\n\nLA SEÑAL. Triángulo rojo con un trazo vertical GRUESO y un ramal FINO que sale hacia la izquierda.\n\nLA GRAMÁTICA DEL GROSOR, la misma de las tablas de dirección: grueso es la vía con prioridad — la tuya —, fino es la secundaria que se incorpora. Aquí entra por la izquierda.\n\nES LA IMAGEN ESPEJO DE LA 5258, la del ramal a la derecha. Y las dos forman familia con la de ramales a ambos lados y con el aspa.\n\nCUIDADO CON UNA COSA. Aunque la secundaria entre por tu izquierda y tú tengas prioridad, sigue siendo el punto donde más se falla en la práctica: quien llega por la izquierda te ve tarde porque tiene el pilar del coche justo en tu dirección.\n\n«SEÑALIZA UN CRUCE DE VÍAS DE IGUAL RANGO» es el aspa, que no lleva trazo grueso precisamente porque no hay jerarquía.\n\n«INDICA EL SENTIDO OBLIGATORIO EN LA PRÓXIMA INTERSECCIÓN» sería un panel azul.\n\nCLAVE: cuenta los ramales finos y mira de qué lado salen. Grueso mandas tú; si no hay grueso, es el aspa y vuelve la regla de la derecha.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5287,"bg":"Този пътен знак предупреждава за приближаване към:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334680.png","v":null,"a":[{"t":"железопътен прелез с бариери","ok":true,"i":null,"es":"paso a nivel con barreras"},{"t":"подвижен мост","ok":false,"i":null,"es":"puente móvil"},{"t":"трамвайна линия","ok":false,"i":null,"es":"línea de tranvía"},{"t":"път затворен за обществено ползване","ok":false,"i":null,"es":"vía cerrada al uso público"}],"f":3,"es":"Esta señal advierte de la proximidad de:","explain":"Paso a nivel con barreras (barieri). Las barreras bajan automaticamente antes del tren."},{"id":5290,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334681.png","v":null,"a":[{"t":"сигнализира, че железопътният прелез е с два или повече коловоза","ok":true,"i":null,"es":"indica que el paso a nivel tiene DOS O MÁS vías"},{"t":"забранява преминаването без спиране","ok":false,"i":null,"es":"prohíbe pasar sin detenerse"},{"t":"указва място за задължително спиране","ok":false,"i":null,"es":"indica lugar de parada obligatoria"},{"t":"сигнализира, че железопътният прелез е с един коловоз","ok":false,"i":null,"es":"indica que el paso a nivel tiene UNA vía"}],"f":3,"es":"Esta señal:"},{"id":5420,"bg":"Кои от посочените превозни средства се обозначават с този опознавателен знак?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23200.png","v":null,"a":[{"t":"ремаркетата с две и повече оси","ok":true,"i":null,"es":"los remolques de dos o más ejes"},{"t":"едноосните ремаркета","ok":true,"i":null,"es":"los remolques de un eje"},{"t":"товарните автомобили","ok":false,"i":null,"es":"los camiones"},{"t":"съставите от ППС при теглене на повреден автомобил","ok":false,"i":null,"es":"los conjuntos de vehículos al remolcar un automóvil averiado"}],"f":3,"es":"¿A cuáles de los vehículos identifica este signo distintivo? (2 correctas)","explain":"Identifica remolques de dos o mas ejes Y remolques de un eje. Todos los remolques llevan este signo."},{"id":5541,"bg":"При тази ситуация съществува ли опасност при разминаването с децата велосипедисти?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23862.png","v":null,"a":[{"t":"да, защото велосипедистите са деца","ok":true,"i":null,"es":"sí, porque los ciclistas son niños"},{"t":"да, защото велосипедистите се движат непосредствено до средата на платното за движение","ok":true,"i":null,"es":"sí, porque los ciclistas circulan justo al lado del centro de la calzada"},{"t":"не, защото велосипедистите са в съседната пътна лента","ok":false,"i":null,"es":"no, porque los ciclistas están en el carril contiguo"},{"t":"не, защото велосипедистите ме виждат","ok":false,"i":null,"es":"no, porque los ciclistas me ven"}],"f":3,"es":"En esta situación, ¿existe peligro al cruzarse con los niños ciclistas? (2 correctas)","explain":"SI, doble peligro: son ninos (impredecibles) Y estan cerca de la mediana de la calzada."},{"id":5765,"bg":"При тази ситуация, за да осигуря безопасността на децата велосипедисти, трябва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24013.png","v":null,"a":[{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"да осигуря достатъчна странична дистанция","ok":true,"i":null,"es":"garantizar distancia lateral suficiente"},{"t":"незабавно да спра","ok":false,"i":null,"es":"frenar de inmediato"},{"t":"да подам звуков сигнал","ok":false,"i":null,"es":"tocar el claxon"}],"f":3,"es":"En esta situación, para garantizar la seguridad de los niños ciclistas, debo: (2 correctas)","explain":"Reducir velocidad Y asegurar distancia lateral suficiente. No frenar bruscamente ni tocar el claxon."},{"id":5768,"bg":"При тази ситуация, преди да започна изпреварването, трябва да подам звуков сигнал.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24454.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":3,"es":"En esta situación, antes de comenzar el adelantamiento, debo dar señal acústica. Esto es:","explain":"INCORRECTO. El claxon no es obligatorio antes de adelantar. Solo se usa para evitar accidentes."},{"id":5787,"bg":"Водачите на двуколесни МПС са по-уязвими от водачите на автомобили защото:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"лесно губят устойчивост при движението","ok":true,"i":null,"es":"pierden fácilmente la estabilidad al circular"},{"t":"не са защитени от купето на автомобила","ok":true,"i":null,"es":"no están protegidos por la carrocería del automóvil"},{"t":"по-трудно се забелязват когато са в „мъртвата зона” на автомобила","ok":true,"i":null,"es":"son más difíciles de ver cuando están en el \"ángulo muerto\" del automóvil"},{"t":"се движат по-бавно","ok":false,"i":null,"es":"circulan más despacio"}],"f":3,"es":"Los conductores de vehículos de dos ruedas son mas vulnerables porque: (3 correctas)","explain":"Los de dos ruedas son vulnerables porque pierden fácilmente la estabilidad, no tienen carrocería que los proteja y desaparecen en el ángulo muerto. Que circulen despacio es falso y no es la razón de su vulnerabilidad."},{"id":5802,"bg":"При тази ситуация при изпреварване на каруцата:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24779.png","v":null,"a":[{"t":"има опасност от падане на товар пред автомобила","ok":true,"i":null,"es":"existe el peligro de que caiga carga delante del automóvil"},{"t":"има опасност каруцата да промени внезапно посоката си на движение, поради подплашване на животното","ok":true,"i":null,"es":"existe el peligro de que el carro cambie bruscamente de dirección si el animal se asusta"},{"t":"има опасност от поява на друго домашно животно на платното за движение, което придружава каруцата","ok":true,"i":null,"es":"existe el peligro de que aparezca en la calzada otro animal doméstico que acompaña al carro"},{"t":"няма опасност, защото каруцата се движи бавно","ok":false,"i":null,"es":"no hay peligro, porque el carro circula despacio"}],"f":3,"es":"En esta situación, al adelantar a la carreta: (3 correctas)","explain":"3 peligros reales: caida de carga, el animal puede asustarse y cambiar de direccion, otro animal puede aparecer."},{"id":5824,"bg":"При тази ситуация водачът на лекия автомобил трябва да пропусне пешеходеца.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25365.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":3,"es":"En esta situación el conductor del turismo debe ceder el paso al peatón. Esto es:","explain":"CORRECTO. En paso de peatones siempre se cede, independientemente de si el peaton ya llego a la mitad."},{"id":6029,"bg":"При тази ситуация е достатъчно децата да застанат в средата на улицата, за да премина безопасно зад тях.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26035.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":3,"es":"En esta situación es suficiente que los niños se paren en el centro de la calle para que yo pase por detrás de ellos con seguridad. Esto es:","explain":"INCORRECTO. Nunca es suficiente que los ninos esten parados en la mediana. Siguen siendo peligro."},{"id":6035,"bg":"След подаването на сигнал от светофар, който разрешава на водача на МПС да пресече пешеходна пътека, той задължен ли е да се съобразява с намиращите се на нея пешеходци?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"да, винаги","ok":true,"i":null,"es":"sí, siempre"},{"t":"да, но само с тези от тях, които подават сигнал с ръка","ok":false,"i":null,"es":"sí, pero solo con aquellos que hacen una señal con la mano"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"Después de que el semáforo permita al conductor cruzar un paso de peatones, ¿está obligado a ceder a los peatones que hay en el paso?","explain":"Sí, siempre: aunque tu semáforo se ponga verde, los peatones que YA están en el paso terminan de cruzar con prioridad. El verde te permite avanzar, no atropellar a quien empezó a cruzar legalmente."},{"id":6037,"bg":"Кога водачът на ППС трябва да сигнализира за намерението си да извърши маневра свързана с отклонение встрани?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"винаги","ok":true,"i":null,"es":"siempre"},{"t":"само когато зад него се движи друго ППС","ok":false,"i":null,"es":"solo cuando detrás de él circula otro vehículo"},{"t":"само при интензивно движение","ok":false,"i":null,"es":"solo con tráfico intenso"},{"t":"само при намалена видимост","ok":false,"i":null,"es":"solo con visibilidad reducida"}],"f":3,"es":"¿Cuándo debe el conductor señalizar su intención de realizar una maniobra de desviación lateral?","explain":"Siempre: la maniobra lateral se señaliza haya o no alguien detrás, con cualquier tráfico y con cualquier visibilidad. Nunca sabes con certeza quién puede verte: la señal no es opcional."},{"id":6038,"bg":"Необходимо ли е винаги преди потегляне за включване в движението водачът да сигнализира със съответен сигнал?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"¿Es siempre necesario que el conductor señalice antes de arrancar para incorporarse al tráfico?","explain":"Sí: antes de arrancar e incorporarte al tráfico la señal es siempre obligatoria. El intermitente avisa a quienes quizá no has visto tú."},{"id":6051,"bg":"Когато пътепоказателите са повредени, как трябва да сигнализирате преди заобикаляне с отклонение наляво?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"с изпъната встрани лява ръка","ok":true,"i":null,"es":"con el brazo IZQUIERDO extendido lateralmente"},{"t":"с вдигната вертикално нагоре ръка","ok":false,"i":null,"es":"con el brazo levantado verticalmente"},{"t":"с изпъната встрани дясна ръка","ok":false,"i":null,"es":"con el brazo DERECHO extendido lateralmente"},{"t":"не съм задължен да сигнализирам","ok":false,"i":null,"es":"no estoy obligado a señalizar"}],"f":3,"es":"Con los intermitentes averiados, ¿cómo señalizas antes de rodear un obstáculo desviándote a la izquierda?","explain":"Con intermitentes averiados, la desviación a la izquierda se señaliza con el brazo IZQUIERDO extendido lateralmente: apunta hacia donde vas. El brazo vertical o el derecho indican otras cosas, y 'no señalizar' nunca es opción."},{"id":6055,"bg":"При движение извън населено място, звуковият сигнал е разрешено да се използва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"като допълнителен сигнал, по преценка на водача","ok":true,"i":null,"es":"como señal adicional, a criterio del conductor"},{"t":"в случаите за предотвратяване на ПТП","ok":true,"i":null,"es":"en los casos necesarios para evitar un accidente de tráfico"},{"t":"при движение с висока скорост","ok":false,"i":null,"es":"al circular a alta velocidad"},{"t":"без ограничения","ok":false,"i":null,"es":"sin restricciones"}],"f":3,"es":"Al circular fuera de población, el uso del claxon está permitido: (2 correctas)","explain":"Fuera de población el claxon es libre como señal adicional a criterio del conductor, y en cualquier caso para evitar un accidente. Ni la alta velocidad lo exige ni existe un 'sin restricciones': dentro de población sigue limitado."},{"id":6056,"bg":"Използването на звуковия сигнал е разрешено:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"извън населените места, като допълнителен сигнал за маневра","ok":true,"i":null,"es":"fuera de población, como señal adicional de maniobra"},{"t":"навсякъде, за недопускане на ПТП","ok":true,"i":null,"es":"en cualquier lugar, para evitar un accidente"},{"t":"в населените места, като допълнителен сигнал за маневра","ok":false,"i":null,"es":"en zona urbana, como señal adicional de maniobra"},{"t":"навсякъде, без ограничения","ok":false,"i":null,"es":"en cualquier lugar, sin restricciones"}],"f":3,"es":"El uso del claxon está PERMITIDO: (2 correctas)","explain":"Permitido: fuera de población como señal adicional de maniobra, y en CUALQUIER lugar para evitar un accidente. En zona urbana como simple señal de maniobra está prohibido: esa es la diferencia clave ciudad/carretera."},{"id":6062,"bg":"Преди извършване на маневра водачът на ППС сигнализира за нея, защото:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"чрез сигнала предупреждава останалите участници в движението за намерението си","ok":true,"i":null,"es":"con la señal advierte a los demás usuarios de la vía de su intención"},{"t":"указва на останалите водачи, посоката в която ще се продължи движението си","ok":true,"i":null,"es":"indica a los demás conductores la dirección en la que continuará su marcha"},{"t":"сигналът го освобождава от отговорност","ok":false,"i":null,"es":"la señal lo exime de responsabilidad"},{"t":"сигналът му дава предимство","ok":false,"i":null,"es":"la señal le da prioridad"}],"f":3,"es":"Antes de realizar una maniobra el conductor del vehículo señaliza porque: (2 correctas)","explain":"Se señaliza para ADVERTIR a los demás de tu intención y para indicarles tu dirección. La señal ni te exime de responsabilidad ni te da prioridad: señalizar no convierte una maniobra insegura en legal."},{"id":6067,"bg":"Как пешеходците сигнализират за намерението си да преминат през платното за движение?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"с ръка, изпъната нагоре","ok":true,"i":null,"es":"con el brazo extendido hacia arriba"},{"t":"с ръка, изпъната напречно на платното за движение","ok":true,"i":null,"es":"con el brazo extendido transversalmente a la calzada"},{"t":"с кръгово движение на ръката","ok":false,"i":null,"es":"con un movimiento circular del brazo"},{"t":"пешеходците нямат право да подават сигнали","ok":false,"i":null,"es":"los peatones no tienen derecho a hacer señales"}],"f":3,"es":"¿Cómo señalizan los peatones su intención de cruzar la calzada? (2 correctas)","explain":"El peatón anuncia el cruce con el brazo extendido hacia arriba o transversalmente a la calzada: son sus dos señales legales. El movimiento circular es la señal ferroviaria de parada, y los peatones SÍ tienen derecho a señalizar."},{"id":9852,"bg":"Кога водачът на нерелсово ППС е длъжен да пропусне преминаващите по пешеходната пътека пешеходци?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044369.png","v":null,"a":[{"t":"винаги","ok":true,"i":null,"es":"siempre"},{"t":"само когато пешеходците са достигнали средата на платното за движение","ok":false,"i":null,"es":"solo cuando los peatones han alcanzado el centro de la calzada"},{"t":"само когато са в непосредствена близост до автомобила","ok":false,"i":null,"es":"solo cuando están muy cerca del automóvil"}],"f":3,"es":"¿Cuándo está obligado el conductor de un vehículo no ferroviario a ceder el paso a los peatones que cruzan por el paso de peatones?","explain":"SIEMPRE, sin condiciones. No depende de si el peaton llego a la mitad ni de su distancia al vehiculo."},{"id":5946,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42480.png","v":null,"a":[{"t":"предупреждава, че е възможна появата на домашни животни на пътя","ok":true,"i":null,"es":"advierte de la posible aparición de animales domésticos en la vía"},{"t":"сигнализира път, по който се движат ППС с животинска тяга","ok":false,"i":null,"es":"señaliza una vía por la que circulan vehículos de tracción animal"},{"t":"забранява воденето на домашни животни по платното за движение","ok":false,"i":null,"es":"prohíbe llevar animales domésticos por la calzada"},{"t":"указва път задължителен за движение на ППС теглени от животни","ok":false,"i":null,"es":"indica una vía obligatoria para vehículos de tracción animal"}],"f":3,"es":"Esta señal:","explain":"Advertencia de animales domesticos en la carretera. No prohibe el paso de vehiculos de traccion animal."},{"id":5957,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334693.png","v":null,"a":[{"t":"&quot;Пропусни движещите се по пътя с предимство&quot;","ok":true,"i":null,"es":"\"Cede el paso a quienes circulan por la vía con prioridad\""},{"t":"&quot;Пропусни насрещно движещите се превозни средства&quot;","ok":false,"i":null,"es":"\"Cede el paso a los vehículos que vienen de frente\""},{"t":"&quot;Внимание, други опасности&quot;","ok":false,"i":null,"es":"\"Atención, otros peligros\""},{"t":"&quot;Внимание спри&quot;","ok":false,"i":null,"es":"\"Atención, detente\""}],"f":3,"es":"El significado de esta señal es:","explain":"«Cede el paso a quienes circulan por la vía con prioridad» — «Пропусни движещите се по пътя с предимство».\n\nLA SEÑAL. Triángulo con el vértice hacia ABAJO y el interior blanco. Es la única señal invertida de todo el código, y esa forma exclusiva se reconoce incluso por detrás.\n\nQUÉ TE OBLIGA A HACER. A ceder el paso a los que circulan por la vía preferente. NO a detenerte: si la vía está libre, puedes seguir sin parar. Esa es la diferencia con el STOP.\n\n«CEDE EL PASO A LOS QUE VIENEN DE FRENTE» no es ninguna señal: es la regla del чл. 37, que se aplica cuando giras a la izquierda.\n\n«ATENCIÓN, OTROS PELIGROS» es el triángulo normal con el signo de exclamación — pregunta 5200 — y solo avisa.\n\n«ATENCIÓN, DETENTE» es el ámbar fijo del semáforo y el brazo vertical del agente, no una señal vertical. Es el cebo de vocabulario que se repite en toda esta familia.\n\nCLAVE: el trío de la prioridad, por forma. Rombo amarillo: mando yo. Triángulo invertido: cedo, sin parar obligatoriamente. Octógono rojo: paro siempre y luego cedo.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5963,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334703.png","v":null,"a":[{"t":"забранява влизането на ППС срещу него","ok":true,"i":null,"es":"prohíbe la entrada de vehículos en su sentido"},{"t":"сигнализира път затворен за обществено ползване","ok":false,"i":null,"es":"señaliza una vía cerrada al uso público"},{"t":"забранява преминаването без спиране","ok":false,"i":null,"es":"prohíbe pasar sin detenerse"},{"t":"указва, че пътят е без изход","ok":false,"i":null,"es":"indica que la vía no tiene salida (calle sin salida)"}],"f":3,"es":"Esta señal:","explain":"PROHÍBE LA ENTRADA DE VEHÍCULOS en su sentido de circulación.\n\nLA SEÑAL. Círculo rojo macizo con una barra blanca horizontal en el centro: «Забранено е влизането на пътни превозни средства».\n\nQUÉ SIGNIFICA EN LA PRÁCTICA. Casi siempre estás ante la salida de una calle de sentido único: por ahí no se entra, aunque sí se salga. Es la señal que ves cuando te has equivocado de calle.\n\nA QUIÉN AFECTA. A todos los vehículos, «пътни превозни средства» — incluidas bicicletas y ciclomotores. No solo a los coches.\n\n«SEÑALIZA UNA VÍA CERRADA AL USO PÚBLICO» es otra señal distinta, y además significa otra cosa: allí no se entra en ningún sentido.\n\n«PROHÍBE PASAR SIN DETENERSE» es el STOP, octogonal.\n\n«CALLE SIN SALIDA» es un panel azul informativo, y ahí sí puedes entrar: simplemente tendrás que volver.\n\nCLAVE: el círculo rojo macizo con la barra blanca es de las señales más reconocibles del mundo entero. Prohíbe ENTRAR, no circular: la misma calle es legal en el otro sentido.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5966,"bg":"На кои от изброените превозни средства е разрешено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334703.png","v":null,"a":[{"t":"велосипеди","ok":false,"i":null,"es":"bicicletas"},{"t":"ППС теглени от животни","ok":false,"i":null,"es":"vehículos de tracción animal"},{"t":"мотопеди","ok":false,"i":null,"es":"ciclomotores"},{"t":"автомобили със специален режим на движение","ok":true,"i":null,"es":"automóviles con régimen especial de circulación"}],"f":3,"es":"¿A cuáles de los vehículos les está permitido entrar después de esta señal?","explain":"Solo vehiculos con regimen especial (ambulancia, policia, bomberos). Los demas estan prohibidos."},{"id":5982,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334708.png","v":null,"a":[{"t":"&quot;Забранено е влизането на МПС с ремаркета, освен с полуремаркета или единични едноосни ремаркета&quot;","ok":true,"i":null,"es":"'Prohibida la entrada de vehículos CON REMOLQUES, excepto semirremolques o remolques simples de un eje'"},{"t":"&quot;Забранено е влизането на МПС с ремаркета&quot;","ok":false,"i":null,"es":"'Prohibida la entrada de vehículos con remolques'"},{"t":"&quot;Забранено е влизането на товарни автомобили&quot;","ok":false,"i":null,"es":"'Prohibida la entrada de camiones'"}],"f":3,"es":"El significado de esta señal es:"},{"id":5983,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51816.png","v":null,"a":[{"t":"&quot;Забранено е влизането на МПС с ремаркета&quot;","ok":true,"i":null,"es":"'Prohibida la entrada de vehículos con remolques'"},{"t":"&quot;Забранено е влизането на МПС с ремаркета, освен с полуремаркета или единични едноосни ремаркета&quot;","ok":false,"i":null,"es":"'Prohibida la entrada de vehículos CON REMOLQUES, excepto semirremolques o remolques simples de un eje'"}],"f":3,"es":"El significado de esta señal es:"},{"id":5986,"bg":"Този пътен знак забранява влизането на:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51854.png","v":null,"a":[{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"самоходни машини","ok":true,"i":null,"es":"máquinas autopropulsadas"},{"t":"товарни автомобили","ok":false,"i":null,"es":"camiones"},{"t":"ППС теглени от животни","ok":false,"i":null,"es":"vehículos de tracción animal"}],"f":3,"es":"Esta señal prohíbe la entrada a: (2 correctas)","explain":"Tractores y maquinaria autopropulsada. Los camiones normales pueden pasar."},{"id":5987,"bg":"Разрешено ли е влизането на мотопеди след този пътен знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51892.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":3,"es":"¿Está permitida la entrada de ciclomotores después de esta señal?","explain":"NO, no está permitida.\n\nLA SEÑAL. Círculo rojo con una motocicleta dibujada: prohibida la entrada de motocicletas.\n\nPOR QUÉ TAMBIÉN ALCANZA A LOS CICLOMOTORES. La prohibición se refiere a la categoría, y a efectos de esta señal el ciclomotor entra dentro del grupo: son vehículos de dos ruedas a motor. Que sea más pequeño o más lento no lo excluye.\n\nEL RAZONAMIENTO QUE FALLA es «un ciclomotor no es una motocicleta, así que puedo pasar». Las señales de prohibición por categoría se leen en sentido amplio, no buscando el resquicio.\n\nCOMPÁRALA CON LA EXCEPCIÓN DE LA 6408, donde sí hay un resquicio escrito: la señal de prohibido adelantar excluye expresamente a las motos de dos ruedas sin sidecar. Allí la excepción está en la norma; aquí no hay ninguna.\n\nCLAVE: cuando una señal prohíbe una categoría de vehículo, incluye a sus variantes menores salvo que la norma diga lo contrario. Y cuando el banco quiere que apliques una excepción, esa excepción existe por escrito — no se deduce del tamaño.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5990,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51949.png","v":null,"a":[{"t":"&quot;Забранено е преминаването без спиране&quot;","ok":true,"i":null,"es":"\"Prohibido pasar sin detenerse\""},{"t":"&quot;Забранено е влизането срещу знака&quot;","ok":false,"i":null,"es":"\"Prohibida la entrada en el sentido de la señal\""},{"t":"&quot;Внимание! Митница&quot;","ok":false,"i":null,"es":"\"¡Atención! Aduana\""},{"t":"&quot;Път, затворен за обществено ползване&quot;","ok":false,"i":null,"es":"\"Vía cerrada al uso público\""}],"f":3,"es":"El significado de esta señal es:","explain":"Parada obligatoria (STOP). Debes detenerte completamente aunque no venga nadie."},{"id":6167,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51988.png","v":null,"a":[{"t":"товарни автомобили","ok":true,"i":null,"es":"camiones"},{"t":"мотоциклети","ok":true,"i":null,"es":"motocicletas"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"велосипеди","ok":false,"i":null,"es":"bicicletas"}],"f":3,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (3 correctas)","explain":"Prohibido: camiones, motos y ciclomotores. Las bicicletas pueden pasar."},{"id":6168,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51988.png","v":null,"a":[{"t":"товарни автомобили","ok":true,"i":null,"es":"camiones"},{"t":"мотоциклети с кош","ok":true,"i":null,"es":"motos con sidecar"},{"t":"мотоциклети без кош","ok":true,"i":null,"es":"motos sin sidecar"},{"t":"трактори","ok":false,"i":null,"es":"tractores"}],"f":3,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (3 correctas)","explain":"Prohibido: camiones, motos con sidecar y motos sin sidecar. Los ciclomotores y tractores pueden pasar."},{"id":6169,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52064.png","v":null,"a":[{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"самоходни машини","ok":true,"i":null,"es":"máquinas autopropulsadas"},{"t":"ППС теглени от животни","ok":true,"i":null,"es":"vehículos de tracción animal"},{"t":"автомобили с ремаркета","ok":false,"i":null,"es":"automóviles con remolque"}],"f":3,"es":"¿A cuáles de los vehículos les está prohibido entrar después de esta señal? (3 correctas)","explain":"Prohibido: tractores, maquinaria autopropulsada y vehiculos de traccion animal. Los coches con remolque pueden pasar."},{"id":6176,"bg":"Този пътен знак забранява влизането след него на превозно средство, на което:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52235.png","v":null,"a":[{"t":"височината на превозното средство е по-голяма от означената","ok":true,"i":null,"es":"altura del vehículo es superior a la indicada"},{"t":"височината на превозното средство с товара е по-голяма от означената","ok":true,"i":null,"es":"altura del vehículo CON CARGA es superior a la indicada"},{"t":"дължината на превозното средство е по-голяма от означената","ok":false,"i":null,"es":"longitud del vehículo es superior a la indicada"},{"t":"товарът е с дължина по-голяма от означената","ok":false,"i":null,"es":"longitud de la carga es superior a la indicada"}],"f":3,"es":"Esta señal prohíbe la entrada de vehículos cuya: (2 correctas)"},{"id":6193,"bg":"При този пътен знак водачът трябва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334697.png","v":null,"a":[{"t":"да премине отдясно на знака","ok":true,"i":null,"es":"pasar por la derecha de la señal"},{"t":"да продължи движението си надясно след знака","ok":false,"i":null,"es":"continuar su marcha hacia la derecha después de la señal"},{"t":"да завие надясно след знака","ok":false,"i":null,"es":"girar a la derecha después de la señal"},{"t":"да спре вдясно от знака","ok":false,"i":null,"es":"detenerse a la derecha de la señal"}],"f":3,"es":"Ante esta señal el conductor debe:","explain":"Pasar POR LA DERECHA de la señal.\n\nLA SEÑAL. Círculo azul con una flecha blanca apuntando en diagonal hacia abajo y a la derecha: «Заобикаляне отдясно», rodear por la derecha.\n\nDÓNDE SE COLOCA. Sobre un obstáculo físico en la calzada — una isleta, un separador, una zona de obras, el principio de una mediana. Te dice por qué lado hay que esquivarlo.\n\nLA FLECHA APUNTA AL SUELO, no al horizonte, y ahí está toda la diferencia. Señala el hueco por donde debes pasar, no una dirección de viaje.\n\n«CONTINUAR SU MARCHA HACIA LA DERECHA» y «GIRAR A LA DERECHA» describen la señal de dirección obligatoria, que es un círculo azul con la flecha horizontal o doblada — la de la pregunta 6188. Aquella ordena hacia dónde vas; esta solo dice por qué lado rodeas.\n\n«DETENERSE A LA DERECHA DE LA SEÑAL» no corresponde a ningún círculo azul: las obligaciones de detenerse son el STOP y el agente.\n\nCLAVE: flecha en diagonal hacia abajo = rodea el obstáculo por ese lado. Flecha horizontal o doblada = ve en esa dirección. La inclinación de la flecha es el dato.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6225,"bg":"При тази ситуация дължината на участъка с последователни опасни завои е 1000 м.","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53982.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":3,"es":"En esta situación la longitud del tramo de curvas peligrosas sucesivas es 1000 m. Esto es:","explain":"CORRECTO. La tablilla adicional con '1000m' indica la longitud del tramo de curvas."},{"id":6244,"bg":"Допълнителната табела указва, че забраната за завиване наляво се отнася:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54164.png","v":null,"a":[{"t":"само за товарните автомобили","ok":true,"i":null,"es":"solo para los camiones"},{"t":"за всички автомобили","ok":false,"i":null,"es":"para todos los automóviles"},{"t":"за всички автомобили, с изключение на товарните","ok":false,"i":null,"es":"para todos los automóviles, excepto los camiones"},{"t":"за всички ППС, с изключение на товарните автомобили","ok":false,"i":null,"es":"para todos los vehículos, excepto los camiones"}],"f":3,"es":"La tablilla adicional indica que la prohibición de girar a la izquierda afecta:","explain":"SOLO para los camiones.\n\nQUÉ VES. La señal circular que prohíbe girar a la izquierda, y debajo una tablilla con el dibujo de un camión.\n\nQUÉ HACE LA TABLILLA. Restringe a QUIÉN se aplica la prohibición. Con el camión dibujado, la prohibición de girar a la izquierda afecta únicamente a los camiones; el resto de vehículos puede girar con normalidad.\n\n«PARA TODOS LOS AUTOMÓVILES» sería la lectura si NO hubiera tablilla. Ese es el error: ignorar la tablilla y aplicar la señal a todos.\n\n«PARA TODOS EXCEPTO LOS CAMIONES» es la inversión exacta, y es el distractor más peligroso porque también parece una lectura razonable del dibujo. La tablilla con un vehículo dentro señala al DESTINATARIO de la prohibición, no a quien queda excluido. Cuando la norma quiere excluir, tacha el símbolo o escribe «освен».\n\nTRES FORMAS DE ACOTAR con tablilla, ya vistas en el banco: por HORARIO (6239), por CONDICIONES (6280) y por TIPO de vehículo, como aquí.\n\nCLAVE: la tablilla responde a «cuándo» o «a quién», nunca a «qué». Y el vehículo dibujado es a quien le toca, no quien se libra.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Rectángulo con fondo gris bajo la señal = tablilla que la acota. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6275,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54986.png","v":null,"a":[{"t":"продължаване зоната на действие на пътния знак","ok":true,"i":null,"es":"la continuación de la zona de validez de la señal"},{"t":"край на участък, в който са забранени престоят и паркирането","ok":false,"i":null,"es":"fin del tramo donde están prohibidas la parada y el estacionamiento"},{"t":"начало на участък, в който са забранени престоят и паркирането","ok":false,"i":null,"es":"inicio del tramo donde están prohibidas la parada y el estacionamiento"}],"f":3,"es":"La tablilla adicional de la señal indica:","explain":"La CONTINUACIÓN de la zona de validez de la señal.\n\nQUÉ VES. El aspa azul con borde rojo — prohibidas la parada y el estacionamiento — y debajo una tablilla con una flecha de DOBLE PUNTA.\n\nLA DOBLE PUNTA SIGNIFICA «SIGUES DENTRO». Se coloca en mitad de un tramo largo para recordarte que la prohibición no ha terminado. Es un recordatorio, no un comienzo ni un final.\n\nPOR QUÉ EXISTE. Un tramo prohibido puede medir cientos de metros, y quien se incorpora por una calle lateral no ha visto la señal inicial. Repetirla con la doble flecha resuelve ese hueco de información.\n\n«INICIO DEL TRAMO» y «FIN DEL TRAMO» son los dos distractores, y cada uno tiene su propia tablilla, con la flecha de UNA sola punta. La forma de la flecha es el dato entero: dos puntas, estás dentro; una punta, es el borde del tramo.\n\nCLAVE: cuenta las puntas de la flecha. Dos puntas = la prohibición continúa. Una punta = estás en el extremo del tramo. No hace falta saber nada más de la señal principal.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro. Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado o rectángulo azul = información. Rombo amarillo = prioridad. Tablilla gris debajo = acota la señal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6276,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60865.png","v":null,"a":[{"t":"продължаване зоната на действие на пътния знак","ok":true,"i":null,"es":"la continuación de la zona de validez de la señal"},{"t":"край на участък, в който са забранени престоят и паркирането","ok":false,"i":null,"es":"fin del tramo donde están prohibidas la parada y el estacionamiento"},{"t":"че забраната за престой и паркиране се отнася и за двете страни на пътя","ok":false,"i":null,"es":"que la prohibición de parada y estacionamiento se aplica a ambos lados de la vía"},{"t":"начало на участък, в който са забранени престоят и паркирането","ok":false,"i":null,"es":"inicio del tramo donde están prohibidas la parada y el estacionamiento"}],"f":3,"es":"La tablilla adicional de la señal indica:","explain":"La CONTINUACIÓN de la zona de validez de la señal.\n\nES LA MISMA RESPUESTA QUE LA 6275 con la flecha girada. Allí la doble punta era vertical; aquí es horizontal. El significado no cambia: dos puntas siguen queriendo decir que la prohibición continúa.\n\nLA ORIENTACIÓN NO ALTERA EL MENSAJE. Lo que cuenta es cuántas puntas tiene la flecha, no en qué eje esté dibujada. Es exactamente el tipo de detalle irrelevante que el banco usa para hacerte dudar.\n\n«QUE LA PROHIBICIÓN SE APLICA A AMBOS LADOS DE LA VÍA» es el distractor nuevo de esta pregunta y es tentador, porque una flecha horizontal de doble punta sugiere «a un lado y al otro». Pero la tablilla habla de la LONGITUD del tramo, no de la anchura de la calle.\n\n«INICIO» y «FIN» vuelven a ser las tablillas de una sola punta.\n\nCLAVE: estúdiala junto a la 6275. Dos preguntas, dos dibujos distintos, una sola respuesta — el banco comprueba que has entendido el principio y no memorizado un dibujo.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro. Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado o rectángulo azul = información. Rombo amarillo = prioridad. Tablilla gris debajo = acota la señal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6278,"bg":"Този пътен знак с допълнителна табела указват:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60988.png","v":null,"a":[{"t":"място за паркиране на ППС","ok":true,"i":null,"es":"lugar de estacionamiento de vehículos"},{"t":"начин за паркиране на ППС","ok":true,"i":null,"es":"modo de estacionamiento de vehículos"},{"t":"забрана за паркиране на тротоара","ok":false,"i":null,"es":"prohibición de estacionar en la acera"},{"t":"че е разрешено паркирането само на леки автомобили","ok":false,"i":null,"es":"que solo está permitido el estacionamiento de turismos"}],"f":3,"es":"Esta señal con tablilla adicional indica: (2 correctas)","explain":"Lugar de aparcamiento Y la forma de aparcar (en angulo, paralelo, etc.). Doble informacion."},{"id":6291,"bg":"При тази ситуация на какво разстояние трябва да очакваме опасния завой, за който ни предупреждава пътният знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55978.png","v":null,"a":[{"t":"от 100 до 150 м","ok":true,"i":null,"es":"entre 100 y 150 m"},{"t":"от 50 до 100 м","ok":false,"i":null,"es":"entre 50 y 100 m"},{"t":"на повече от 200 м","ok":false,"i":null,"es":"más de 200 m"},{"t":"на повече от 50 м","ok":false,"i":null,"es":"más de 50 m"}],"f":3,"es":"En esta situación, ¿a qué distancia debemos esperar la curva que advierte la señal?"},{"id":6302,"bg":"При тази ситуация забраната за престой и паркиране е валидна:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/159617.png","v":null,"a":[{"t":"до края на опасността, сигнализирана с предупредителния пътен знак","ok":true,"i":null,"es":"hasta el final del peligro señalizado por la señal de advertencia"},{"t":"до знак, който отменя забраната","ok":false,"i":null,"es":"hasta la señal que cancela la prohibición"},{"t":"до следващото кръстовище","ok":false,"i":null,"es":"hasta la próxima intersección"},{"t":"само на мястото, на което са поставени знаците","ok":false,"i":null,"es":"solo en el lugar donde están colocadas las señales"}],"f":3,"es":"En esta situación la prohibición de parada y estacionamiento es válida:","explain":"Hasta el final del peligro senalizado por la senal de advertencia previa."},{"id":6306,"bg":"При тази ситуация движението на товарни автомобили в лентата, над която е поставен пътният знак, е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57588.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":3,"es":"En esta situación la circulación de camiones por el carril sobre el que está colocada la señal está:","explain":"PROHIBIDA. Los paneles de senales sobre carriles son obligatorios."},{"id":11680,"bg":"След този пътен знак водачът:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801977.png","v":null,"a":[{"t":"трябва да вземе мерки за ограничаване на шума","ok":true,"i":null,"es":"debe tomar medidas para limitar el ruido"},{"t":"може да паркира от двете страни на пътя","ok":false,"i":null,"es":"puede estacionar a ambos lados de la vía"},{"t":"не трябва да се движи със скорост по-висока от 40 km/h","ok":false,"i":null,"es":"no debe circular a una velocidad superior a 40 km/h"}],"f":3,"es":"Después de esta señal el conductor:","explain":"Debe reducir el ruido del motor y evitar el claxon. Zona de silencio (hospital, area residencial nocturna)."},{"id":11885,"bg":"В кой от изброените отговори е посочено вярно значението на пътния знак с допълнителна табела?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828556.png","v":null,"a":[{"t":"стесненият участък от платното за движение започва на 200 метра след знака","ok":true,"i":null,"es":"el tramo estrecho empieza a 200 metros después de la señal"},{"t":"стесненият участък от платното за движение е с дължина 200 метра","ok":false,"i":null,"es":"el tramo estrecho tiene una longitud de 200 metros"},{"t":"стесненият участък от пътя завършва на 200 метра след знака","ok":false,"i":null,"es":"el tramo estrecho termina a 200 metros después"}],"f":3,"es":"¿Cuál es el significado correcto de esta señal con tablilla?"},{"id":11886,"bg":"В кой отговор е посочено вярно значението на пътния знак с допълнителна табела?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828558.png","v":null,"a":[{"t":"стесненият участък от платното за движение е с дължина 200 метра","ok":true,"i":null,"es":"el tramo estrecho tiene una longitud de 200 metros"},{"t":"стесненият участък от платното за движение започва на 200 метра след знака","ok":false,"i":null,"es":"el tramo estrecho empieza a 200 metros después de la señal"},{"t":"стесненият участък от пътя завършва на 200 метра след знака","ok":false,"i":null,"es":"el tramo estrecho termina a 200 metros después"}],"f":3,"es":"¿Cuál es el significado correcto de esta señal con tablilla?"},{"id":11887,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828560.png","v":null,"a":[{"t":"начало на участък с дължина 10 метра, където е забранено паркирането","ok":true,"i":null,"es":"inicio de un tramo de 10 m donde está prohibido aparcar"},{"t":"че началото на участъка, в който е забранено паркирането, е след 10 метра","ok":false,"i":null,"es":"que el inicio de la zona prohibida está a 10 m"},{"t":"края на участък с дължина 10 метра, в който е забранено паркирането","ok":false,"i":null,"es":"fin de un tramo de 10 m donde está prohibido aparcar"}],"f":3,"es":"La tablilla complementaria junto a la señal indica:"},{"id":12079,"bg":"Задължителното предписание на този пътен знак се отнася за водачите на:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1173460262.png","v":null,"a":[{"t":"ППС, обозначени с опознавателен знак за опасен товар","ok":true,"i":null,"es":"vehículos señalizados con el distintivo de mercancías peligrosas"},{"t":"извънгабаритни ППС","ok":false,"i":null,"es":"vehículos de dimensiones excepcionales"},{"t":"бавнодвижещи се ППС","ok":false,"i":null,"es":"vehículos lentos"},{"t":"автомобили със специално предназначение","ok":false,"i":null,"es":"automóviles de uso especial"}],"f":3,"es":"La prescripción obligatoria de esta señal afecta a los conductores de:","explain":"A los conductores de vehículos señalizados con el DISTINTIVO DE MERCANCÍAS PELIGROSAS.\n\nQUÉ VES. Un panel rectangular que contiene dos cosas: arriba, un vehículo cisterna con la placa NARANJA; abajo, un círculo azul con la flecha de dirección obligatoria a la izquierda.\n\nCÓMO SE LEE UN PANEL COMBINADO. La imagen de arriba dice A QUIÉN va dirigida la prescripción; la señal de abajo dice QUÉ tiene que hacer. Aquí: los vehículos con mercancías peligrosas están obligados a girar a la izquierda. El resto sigue su camino.\n\nPOR QUÉ EXISTE. A las mercancías peligrosas se les desvía de túneles, zonas densamente pobladas y captaciones de agua. En vez de prohibirles el paso a secas, se les marca un itinerario obligatorio.\n\n«VEHÍCULOS DE DIMENSIONES EXCEPCIONALES» se señalizan con paneles a rayas rojas y blancas.\n\n«VEHÍCULOS LENTOS» llevan el triángulo rojo reflectante de la pregunta 5522.\n\n«AUTOMÓVILES DE USO ESPECIAL» no tienen un distintivo con placa naranja.\n\nCLAVE: la placa naranja rectangular es siempre mercancías peligrosas, esté suelta en un camión o dibujada dentro de un panel. Es el único distintivo de ese color.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro. Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado o rectángulo azul = información. Rombo amarillo = prioridad. Tablilla gris debajo = acota la señal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5806,"bg":"След този пътен знак движението с разрешената максимална скорост е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54052.png","v":null,"a":[{"t":"разрешено само при наличие на необходимите условия за безопасност","ok":true,"i":null,"es":"permitido solo si hay condiciones de seguridad"},{"t":"разрешено във всички случаи","ok":false,"i":null,"es":"permitido siempre"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":3,"es":"Después de esta señal, circular a la velocidad máxima permitida está:"},{"id":5855,"bg":"Рязко спиране на превозното средство се допуска:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато е необходимо да се предотврати ПТП","ok":true,"i":null,"es":"cuando es necesario para evitar un accidente"},{"t":"при подаден сигнал със стоп-палка","ok":false,"i":null,"es":"cuando lo indique un agente con pala reflectante"},{"t":"когато зад него не се движи друго ППС","ok":false,"i":null,"es":"cuando no viene nadie detrás"},{"t":"винаги","ok":false,"i":null,"es":"siempre"}],"f":3,"es":"El frenado brusco está permitido:","explain":"El frenado brusco solo está permitido para evitar un accidente: es una maniobra de emergencia. Que no venga nadie detrás no lo legaliza como práctica y ningún agente lo ordena con pala."}]);
